begin;

-- This pool is teacher-authored from curriculum concepts and examination forms.
-- Commercial books informed only the coverage categories; no stem is copied.
create temporary table review_exam_target_skills(
  skill_id text primary key,
  level_cap smallint not null
) on commit drop;

insert into review_exam_target_skills(skill_id,level_cap) values
  ('H1_CLASSIFY',3),
  ('H1_GAS_MOLAR_VOLUME',3),
  ('H1_MOLE_INTRO',3),
  ('H1_PERIODIC',3),
  ('H1_REDOX',3),
  ('H2_ELECTRO',3),
  ('H2_EQUIL',3),
  ('H2_K',3),
  ('H2_KSP',3),
  ('H2_PH_HYDRO',3),
  ('H2_RATE',3),
  ('H2_THERMO',3),
  ('H2_WEAK',3),
  ('H3_AQ',4),
  ('H3_ELECTRO',4),
  ('H3_EQUILIBRIUM',4),
  ('H3_EXPERIMENT',4),
  ('H3_INORGANIC',4),
  ('H3_ION_REDOX',4),
  ('H3_ORGANIC',4),
  ('H3_PROCESS',4),
  ('H3_STOICH',4),
  ('H3_STRUCTURE',4),
  ('H3_THERMO_RATE',4);

alter table public.chem_questions
  add column if not exists concept_key text;

alter table public.chem_attempt_answers
  add column if not exists concept_key text;

comment on column public.chem_questions.concept_key is
  'Fine-grained concept identity used to replace an uncertain answer with a new mother question of the same concept.';

comment on column public.chem_attempt_answers.concept_key is
  'Snapshot of the answered question fine-grained concept for same-concept five-round progression.';

create index if not exists chem_questions_review_concept_idx
  on public.chem_questions(skill_id,concept_key,level)
  where review_status='approved' and scope_status='IN' and usable_for_review;

create index if not exists chem_answers_attempt_concept_idx
  on public.chem_attempt_answers(attempt_id,concept_key,created_at desc)
  where concept_key is not null;

-- Retire generic content-production prompts while preserving every historical row.
update public.chem_questions q
set review_status='retired',
    usable_for_review=false,
    updated_at=now()
where q.skill_id in (select skill_id from review_exam_target_skills)
  and q.review_status='approved'
  and q.stem ~ '(核心规律|最可靠.{0,8}第一步|处理.{0,20}(第一步|优先)|优先检查|最先做)';

with authored as (
  select *
  from jsonb_to_recordset(
    $review_question_bank$[{"id":"Q5R_H1_CLASSIFY_01","mother_id":"M5R_H1_CLASSIFY_01","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__matter_composition","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.空气由多种气体组成，属于混合物。 Ⅱ.空气中含N₂、O₂、稀有气体等多种物质，应按混合物判断。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。空气中含N₂、O₂、稀有气体等多种物质，应按混合物判断。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_02","mother_id":"M5R_H1_CLASSIFY_02","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__matter_composition","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.冰水共存物只含H₂O一种物质，属于纯净物。 Ⅱ.同一种物质的不同状态共存，不会因此变成混合物。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。同一种物质的不同状态共存，不会因此变成混合物。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_03","mother_id":"M5R_H1_CLASSIFY_03","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__matter_composition","level":1,"grade_band":"高一","stem":"判断：O₂和O₃组成的气体只含氧元素，所以属于纯净物。","options":["正确","错误"],"correct_option":1,"explanation":"错误。O₂和O₃是两种不同单质，混在一起仍是混合物。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_04","mother_id":"M5R_H1_CLASSIFY_04","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__matter_composition","level":1,"grade_band":"高一","stem":"判断：由一种元素组成的纯净物一定是单质。","options":["正确","错误"],"correct_option":0,"explanation":"正确。先满足纯净物，再满足只含一种元素，才可判为单质。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_05","mother_id":"M5R_H1_CLASSIFY_05","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__oxide_classification","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.Na₂O属于碱性氧化物。 Ⅱ.Na₂O能与酸反应生成盐和水，也能与水生成NaOH。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。Na₂O能与酸反应生成盐和水，也能与水生成NaOH。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_06","mother_id":"M5R_H1_CLASSIFY_06","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__oxide_classification","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.CO₂属于酸性氧化物。 Ⅱ.CO₂能与碱反应生成盐和水，是典型酸性氧化物。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。CO₂能与碱反应生成盐和水，是典型酸性氧化物。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_07","mother_id":"M5R_H1_CLASSIFY_07","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__oxide_classification","level":1,"grade_band":"高一","stem":"判断：CO属于酸性氧化物。","options":["正确","错误"],"correct_option":1,"explanation":"错误。CO通常既不与酸反应生成盐和水，也不与碱反应生成盐和水，属于不成盐氧化物。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_08","mother_id":"M5R_H1_CLASSIFY_08","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__oxide_classification","level":1,"grade_band":"高一","stem":"判断：Al₂O₃只能归为碱性氧化物。","options":["正确","错误"],"correct_option":1,"explanation":"错误。Al₂O₃既能与酸反应，也能与强碱反应，属于两性氧化物。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_09","mother_id":"M5R_H1_CLASSIFY_09","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__acid_base_salt_classification","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.H₂SO₄按可电离出的H⁺数目可归为二元酸。 Ⅱ.每个H₂SO₄分子可分步电离出两个H⁺。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。每个H₂SO₄分子可分步电离出两个H⁺。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_10","mother_id":"M5R_H1_CLASSIFY_10","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__acid_base_salt_classification","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.H₃PO₄按可电离出的H⁺数目可归为三元酸。 Ⅱ.H₃PO₄可分步电离出三个H⁺，酸的元数不等于电离强弱。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。H₃PO₄可分步电离出三个H⁺，酸的元数不等于电离强弱。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_11","mother_id":"M5R_H1_CLASSIFY_11","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__acid_base_salt_classification","level":2,"grade_band":"高一","stem":"判断：NaHSO₄的化学式中含H，因此NaHSO₄属于酸。","options":["正确","错误"],"correct_option":1,"explanation":"错误。NaHSO₄由Na⁺和HSO₄⁻构成，按组成属于酸式盐。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_12","mother_id":"M5R_H1_CLASSIFY_12","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__acid_base_salt_classification","level":2,"grade_band":"高一","stem":"判断：Ba(OH)₂按每个化学式单位中OH⁻数目可归为二元碱。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Ba(OH)₂完全电离时每个化学式单位给出两个OH⁻。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_13","mother_id":"M5R_H1_CLASSIFY_13","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__acid_base_salt_classification","level":2,"grade_band":"高一","stem":"判断：Cu(OH)₂含有OH⁻，所以一定是强碱。","options":["正确","错误"],"correct_option":1,"explanation":"错误。碱的强弱看电离程度，Cu(OH)₂是难溶弱碱。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_14","mother_id":"M5R_H1_CLASSIFY_14","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__dispersion_system","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.溶液的分散质粒子直径通常小于1 nm。 Ⅱ.溶液中分散质以分子或离子尺度均匀分散，粒子直径通常小于1 nm。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。溶液中分散质以分子或离子尺度均匀分散，粒子直径通常小于1 nm。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_15","mother_id":"M5R_H1_CLASSIFY_15","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__dispersion_system","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.悬浊液的分散质粒子直径通常小于1 nm。 Ⅱ.悬浊液的分散质粒子通常大于100 nm，静置时容易沉降。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。悬浊液的分散质粒子通常大于100 nm，静置时容易沉降。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_16","mother_id":"M5R_H1_CLASSIFY_16","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__dispersion_system","level":2,"grade_band":"高一","stem":"判断：丁达尔效应可用于区分胶体与溶液。","options":["正确","错误"],"correct_option":0,"explanation":"正确。胶体粒子能使光发生明显散射，形成可见光路。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_17","mother_id":"M5R_H1_CLASSIFY_17","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__electrolyte_classification","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.HCl在水溶液中能自身电离产生自由离子，HCl属于电解质。 Ⅱ.判断对象是HCl这种化合物，不是盐酸这一混合物。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。判断对象是HCl这种化合物，不是盐酸这一混合物。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_18","mother_id":"M5R_H1_CLASSIFY_18","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__electrolyte_classification","level":3,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.铜能导电，所以铜属于电解质。 Ⅱ.电解质与非电解质只针对化合物；铜是单质，不能这样分类。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。电解质与非电解质只针对化合物；铜是单质，不能这样分类。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_19","mother_id":"M5R_H1_CLASSIFY_19","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__electrolyte_classification","level":3,"grade_band":"高一","stem":"判断：蔗糖在水溶液中以分子存在，属于非电解质。","options":["正确","错误"],"correct_option":0,"explanation":"正确。蔗糖是化合物，但在水中和熔融状态下不能自身电离。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_20","mother_id":"M5R_H1_CLASSIFY_20","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__electrolyte_classification","level":3,"grade_band":"高一","stem":"判断：SO₂溶于水后形成的体系能导电，因此SO₂属于电解质。","options":["正确","错误"],"correct_option":1,"explanation":"错误。SO₂与水反应形成的体系会产生离子，但SO₂物质本身不发生电离，所以SO₂仍属于非电解质。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_21","mother_id":"M5R_H1_CLASSIFY_21","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__matter_composition","level":3,"grade_band":"高一","stem":"判断：NaCl溶液中只有NaCl一种物质，因此属于纯净物。","options":["正确","错误"],"correct_option":1,"explanation":"错误。NaCl溶液至少含水和NaCl，按组成属于混合物。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_22","mother_id":"M5R_H1_CLASSIFY_22","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__dispersion_system","level":3,"grade_band":"高一","stem":"判断：分散质粒子直径约为1～100 nm的分散系属于胶体。","options":["正确","错误"],"correct_option":0,"explanation":"正确。胶体按分散质粒子尺度判断，不按是否透明判断。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_23","mother_id":"M5R_H1_CLASSIFY_23","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__dispersion_system","level":3,"grade_band":"高一","stem":"判断：可用普通滤纸把NaCl从NaCl溶液中直接过滤出来。","options":["正确","错误"],"correct_option":1,"explanation":"错误。溶液中的离子能通过普通滤纸，过滤不能分离溶质和溶剂。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_24","mother_id":"M5R_H1_CLASSIFY_24","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__electrolyte_classification","level":3,"grade_band":"高一","stem":"判断：熔融NaCl中存在可自由移动的离子，NaCl属于电解质。","options":["正确","错误"],"correct_option":0,"explanation":"正确。NaCl是化合物，在熔融状态能电离出可移动的Na⁺和Cl⁻。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_CLASSIFY_25","mother_id":"M5R_H1_CLASSIFY_25","skill_id":"H1_CLASSIFY","concept_key":"H1_CLASSIFY__oxide_classification","level":3,"grade_band":"高一","stem":"判断：Na₂O由两种元素组成且其中一种是氧元素，所以先判为氧化物，再判为碱性氧化物。","options":["正确","错误"],"correct_option":0,"explanation":"正确。应先沿组成树确定氧化物，再根据与酸碱反应的性质细分。","scaffold":"先锁定研究对象和分类标准，再沿组成树逐层判断。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_01","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_01","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__standard_condition_scope","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.0 ℃、101 kPa属于高中常用的标准状况。 Ⅱ.标准状况的温度和压强必须同时满足，不能只看其中一个条件。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。标准状况的温度和压强必须同时满足，不能只看其中一个条件。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_02","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_02","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__standard_condition_scope","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.任何温度和压强下，气体摩尔体积都等于22.4 L·mol⁻¹。 Ⅱ.气体摩尔体积随温度和压强改变，22.4 L·mol⁻¹只用于标准状况的常用近似。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。气体摩尔体积随温度和压强改变，22.4 L·mol⁻¹只用于标准状况的常用近似。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_03","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_03","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__standard_condition_scope","level":1,"grade_band":"高一","stem":"判断：标准状况下，1 mol任何物质的体积都约为22.4 L。","options":["正确","错误"],"correct_option":1,"explanation":"错误。22.4 L·mol⁻¹只适用于标准状况下的气体，不适用于固体或液体。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_04","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_04","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__standard_condition_scope","level":1,"grade_band":"高一","stem":"判断：标准状况下的H₂O是液体，不能用22.4 L·mol⁻¹计算1 mol水的体积。","options":["正确","错误"],"correct_option":0,"explanation":"正确。使用气体摩尔体积前必须先判断物态。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_05","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_05","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__amount_volume_conversion","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.标准状况下0.25 mol N₂的体积约为5.6 L。 Ⅱ.V=nVₘ=0.25×22.4 L=5.6 L。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。V=nVₘ=0.25×22.4 L=5.6 L。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_06","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_06","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__amount_volume_conversion","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.标准状况下33.6 L O₂的物质的量约为1.5 mol。 Ⅱ.n=V/Vₘ=33.6/22.4 mol=1.5 mol。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。n=V/Vₘ=33.6/22.4 mol=1.5 mol。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_07","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_07","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__amount_volume_conversion","level":1,"grade_band":"高一","stem":"判断：标准状况下4.48 L CO₂的物质的量约为0.20 mol。","options":["正确","错误"],"correct_option":0,"explanation":"正确。4.48÷22.4=0.20，体积单位与Vₘ匹配。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_08","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_08","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__amount_volume_conversion","level":1,"grade_band":"高一","stem":"判断：标准状况下2 mol H₂的体积约为22.4 L。","options":["正确","错误"],"correct_option":1,"explanation":"错误。2 mol气体的体积约为2×22.4 L=44.8 L。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_09","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_09","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__particle_volume_conversion","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.标准状况下11.2 L N₂含有约0.5N_A个N₂分子。 Ⅱ.11.2 L对应0.5 mol N₂，因此分子数为0.5N_A。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。11.2 L对应0.5 mol N₂，因此分子数为0.5N_A。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_10","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_10","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__particle_volume_conversion","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.标准状况下11.2 L N₂含有约0.5N_A个N原子。 Ⅱ.0.5 mol N₂含1.0 mol N原子，即约N_A个N原子。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。0.5 mol N₂含1.0 mol N原子，即约N_A个N原子。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_11","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_11","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__particle_volume_conversion","level":2,"grade_band":"高一","stem":"判断：标准状况下5.6 L CH₄含有约0.25N_A个CH₄分子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。5.6 L对应0.25 mol CH₄，分子数为0.25N_A。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_12","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_12","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__particle_volume_conversion","level":2,"grade_band":"高一","stem":"判断：标准状况下5.6 L CH₄含有约N_A个H原子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。0.25 mol CH₄含1.0 mol H原子，所以H原子数约为N_A。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_13","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_13","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__mass_volume_conversion","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.标准状况下22.4 L CO₂的质量约为44 g。 Ⅱ.22.4 L CO₂约为1 mol，质量为1 mol×44 g·mol⁻¹。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。22.4 L CO₂约为1 mol，质量为1 mol×44 g·mol⁻¹。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_14","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_14","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__mass_volume_conversion","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.标准状况下11.2 L O₂的质量约为32 g。 Ⅱ.11.2 L O₂为0.5 mol，质量应为0.5×32 g=16 g。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。11.2 L O₂为0.5 mol，质量应为0.5×32 g=16 g。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_15","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_15","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__mass_volume_conversion","level":2,"grade_band":"高一","stem":"判断：标准状况下5.6 L N₂的质量约为7.0 g。","options":["正确","错误"],"correct_option":0,"explanation":"正确。5.6 L N₂为0.25 mol，质量为0.25×28 g=7.0 g。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_16","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_16","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__particle_volume_conversion","level":2,"grade_band":"高一","stem":"判断：标准状况下3.01×10²³个H₂分子的体积约为11.2 L。","options":["正确","错误"],"correct_option":0,"explanation":"正确。该分子数约为0.5 mol，再由V=nVₘ得到11.2 L。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_17","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_17","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__mass_volume_conversion","level":2,"grade_band":"高一","stem":"判断：标准状况下44.8 L O₂的质量约为64 g。","options":["正确","错误"],"correct_option":0,"explanation":"正确。44.8 L O₂约为2 mol，质量为2×32 g=64 g。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_18","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_18","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__mass_volume_conversion","level":3,"grade_band":"高一","stem":"判断：标准状况下22.4 L He的质量约为4.0 g。","options":["正确","错误"],"correct_option":0,"explanation":"正确。22.4 L He约为1 mol，质量约为4.0 g。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_19","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_19","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__same_temperature_pressure_relation","level":3,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.同温同压下，等物质的量的不同气体体积相等。 Ⅱ.同温同压时不同气体的气体摩尔体积相同。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。同温同压时不同气体的气体摩尔体积相同。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_20","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_20","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__same_temperature_pressure_relation","level":3,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.同温同压下，两种气体的体积比等于其物质的量之比。 Ⅱ.由V=nVₘ且两者Vₘ相同，可得V₁/V₂=n₁/n₂。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。由V=nVₘ且两者Vₘ相同，可得V₁/V₂=n₁/n₂。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_21","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_21","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__amount_volume_conversion","level":3,"grade_band":"高一","stem":"判断：某条件下题目给出Vₘ=24.0 L·mol⁻¹，则0.50 mol气体体积为12.0 L。","options":["正确","错误"],"correct_option":0,"explanation":"正确。非标准状况应使用题给Vₘ，V=0.50×24.0 L。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_22","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_22","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__standard_condition_scope","level":3,"grade_band":"高一","stem":"判断：25 ℃、101 kPa下计算气体体积时，可不看题给条件直接使用22.4 L·mol⁻¹。","options":["正确","错误"],"correct_option":1,"explanation":"错误。25 ℃不是标准状况，不能机械套用22.4 L·mol⁻¹。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_23","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_23","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__same_temperature_pressure_relation","level":3,"grade_band":"高一","stem":"判断：标准状况下0.50 mol N₂与0.50 mol O₂混合后的总体积约为22.4 L。","options":["正确","错误"],"correct_option":0,"explanation":"正确。混合前后总物质的量为1.00 mol，同一条件下总体积约22.4 L。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_24","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_24","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__same_temperature_pressure_relation","level":3,"grade_band":"高一","stem":"判断：同温同压下，等体积H₂和O₂的质量相等。","options":["正确","错误"],"correct_option":1,"explanation":"错误。等体积对应等物质的量，但O₂的摩尔质量大于H₂，所以质量不相等。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_GAS_MOLAR_VOLUME_25","mother_id":"M5R_H1_GAS_MOLAR_VOLUME_25","skill_id":"H1_GAS_MOLAR_VOLUME","concept_key":"H1_GAS_MOLAR_VOLUME__same_temperature_pressure_relation","level":3,"grade_band":"高一","stem":"判断：同温同压下，1.0 L H₂和1.0 L O₂所含分子数相等。","options":["正确","错误"],"correct_option":0,"explanation":"正确。同温同压下等体积气体含有相同物质的量，分子数也相等。","scaffold":"先检查物态和温压条件，再用V↔n连接N或m。"},{"id":"Q5R_H1_MOLE_INTRO_01","mother_id":"M5R_H1_MOLE_INTRO_01","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__amount_to_particle_count","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.1 mol指定微粒所含的微粒数约为6.02×10²³。 Ⅱ.1 mol任何指定微粒都含约N_A个该微粒。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。1 mol任何指定微粒都含约N_A个该微粒。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_02","mother_id":"M5R_H1_MOLE_INTRO_02","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__avogadro_constant_conversion","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.阿伏加德罗常数的单位可写为mol⁻¹。 Ⅱ.N_A表示每摩尔所含微粒数，常用单位为mol⁻¹。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。N_A表示每摩尔所含微粒数，常用单位为mol⁻¹。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_03","mother_id":"M5R_H1_MOLE_INTRO_03","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__amount_to_particle_count","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.1 mol O₂含有N_A个O原子。 Ⅱ.1 mol O₂含N_A个O₂分子，每个分子含2个O原子，共2N_A个O原子。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。1 mol O₂含N_A个O₂分子，每个分子含2个O原子，共2N_A个O原子。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_04","mother_id":"M5R_H1_MOLE_INTRO_04","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__amount_to_particle_count","level":1,"grade_band":"高一","stem":"判断：0.50 mol H₂O含有约0.50N_A个H₂O分子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。分子数N=nN_A=0.50N_A。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_05","mother_id":"M5R_H1_MOLE_INTRO_05","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__amount_to_particle_count","level":1,"grade_band":"高一","stem":"判断：0.50 mol H₂O含有约1.50N_A个原子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。每个H₂O分子含3个原子，总原子数为0.50×3N_A。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_06","mother_id":"M5R_H1_MOLE_INTRO_06","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__avogadro_constant_conversion","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.3.01×10²³个CO₂分子约为0.50 mol CO₂。 Ⅱ.该分子数约为N_A的一半，对应0.50 mol。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。该分子数约为N_A的一半，对应0.50 mol。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_07","mother_id":"M5R_H1_MOLE_INTRO_07","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__avogadro_constant_conversion","level":1,"grade_band":"高一","stem":"判断：1.204×10²⁴个N₂分子约为1 mol N₂。","options":["正确","错误"],"correct_option":1,"explanation":"错误。该数约为2N_A，对应2 mol N₂。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_08","mother_id":"M5R_H1_MOLE_INTRO_08","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__molar_mass_and_amount","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.O₂的摩尔质量为32 g。 Ⅱ.摩尔质量应带单位，O₂的摩尔质量为32 g·mol⁻¹。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。摩尔质量应带单位，O₂的摩尔质量为32 g·mol⁻¹。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_09","mother_id":"M5R_H1_MOLE_INTRO_09","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__molar_mass_and_amount","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.数值上，某物质的相对分子质量与其摩尔质量以g·mol⁻¹为单位时相等。 Ⅱ.二者物理意义和单位不同，但数值可对应。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。二者物理意义和单位不同，但数值可对应。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_10","mother_id":"M5R_H1_MOLE_INTRO_10","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__molar_mass_and_amount","level":2,"grade_band":"高一","stem":"判断：18 g H₂O的物质的量为1.0 mol。","options":["正确","错误"],"correct_option":0,"explanation":"正确。n=m/M=18 g÷18 g·mol⁻¹=1.0 mol。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_11","mother_id":"M5R_H1_MOLE_INTRO_11","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__mass_to_particle_count","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.9.0 g H₂O含有1 mol H₂O分子。 Ⅱ.9.0 g H₂O为0.50 mol，只含0.50N_A个H₂O分子。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。9.0 g H₂O为0.50 mol，只含0.50N_A个H₂O分子。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_12","mother_id":"M5R_H1_MOLE_INTRO_12","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__molar_mass_and_amount","level":2,"grade_band":"高一","stem":"判断：44 g CO₂的物质的量为1.0 mol。","options":["正确","错误"],"correct_option":0,"explanation":"正确。CO₂的摩尔质量为44 g·mol⁻¹。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_13","mother_id":"M5R_H1_MOLE_INTRO_13","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__mass_to_particle_count","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.11 g CO₂含有约0.25N_A个CO₂分子。 Ⅱ.11 g÷44 g·mol⁻¹=0.25 mol，分子数为0.25N_A。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。11 g÷44 g·mol⁻¹=0.25 mol，分子数为0.25N_A。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_14","mother_id":"M5R_H1_MOLE_INTRO_14","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__molar_mass_and_amount","level":2,"grade_band":"高一","stem":"判断：16 g O₂的物质的量为1.0 mol。","options":["正确","错误"],"correct_option":1,"explanation":"错误。O₂的摩尔质量为32 g·mol⁻¹，16 g对应0.50 mol。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_15","mother_id":"M5R_H1_MOLE_INTRO_15","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__mass_to_particle_count","level":2,"grade_band":"高一","stem":"判断：14 g N₂含有约0.50N_A个N₂分子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。14 g÷28 g·mol⁻¹=0.50 mol。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_16","mother_id":"M5R_H1_MOLE_INTRO_16","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__mass_to_particle_count","level":2,"grade_band":"高一","stem":"判断：23 g Na含有约N_A个Na原子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Na的摩尔质量约为23 g·mol⁻¹，23 g为1 mol。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_17","mother_id":"M5R_H1_MOLE_INTRO_17","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__formula_unit_composition","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.0.25 mol NaCl含有约0.25N_A个NaCl化学式单位。 Ⅱ.离子晶体用化学式单位计数，仍满足N=nN_A。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。离子晶体用化学式单位计数，仍满足N=nN_A。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_18","mother_id":"M5R_H1_MOLE_INTRO_18","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__formula_unit_composition","level":3,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.1 mol Na₂SO₄中所含原子总数约为6N_A。 Ⅱ.一个Na₂SO₄化学式单位含2+1+4=7个原子，总数为7N_A。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。一个Na₂SO₄化学式单位含2+1+4=7个原子，总数为7N_A。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_19","mother_id":"M5R_H1_MOLE_INTRO_19","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__formula_unit_composition","level":3,"grade_band":"高一","stem":"判断：0.20 mol CaCO₃中含有约0.60N_A个O原子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。每个CaCO₃含3个O原子，0.20×3=0.60 mol O原子。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_20","mother_id":"M5R_H1_MOLE_INTRO_20","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__mass_to_particle_count","level":3,"grade_band":"高一","stem":"判断：等质量的O₂和CO₂所含分子数相等。","options":["正确","错误"],"correct_option":1,"explanation":"错误。等质量时物质的量与摩尔质量成反比，O₂的摩尔质量更小，分子数更多。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_21","mother_id":"M5R_H1_MOLE_INTRO_21","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__amount_to_particle_count","level":3,"grade_band":"高一","stem":"判断：等物质的量的CO₂和N₂所含分子数相等。","options":["正确","错误"],"correct_option":0,"explanation":"正确。指定微粒相同时，微粒数只由物质的量决定。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_22","mother_id":"M5R_H1_MOLE_INTRO_22","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__avogadro_constant_conversion","level":3,"grade_band":"高一","stem":"判断：1 mol电子所含电子数约为N_A。","options":["正确","错误"],"correct_option":0,"explanation":"正确。电子也可作为指定微粒使用物质的量计数。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_23","mother_id":"M5R_H1_MOLE_INTRO_23","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__avogadro_constant_conversion","level":3,"grade_band":"高一","stem":"判断：由微粒数求物质的量可用n=N/N_A。","options":["正确","错误"],"correct_option":0,"explanation":"正确。N与n之间通过阿伏加德罗常数换算。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_24","mother_id":"M5R_H1_MOLE_INTRO_24","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__formula_unit_composition","level":3,"grade_band":"高一","stem":"判断：0.10 mol Al₂(SO₄)₃含有0.30 mol SO₄²⁻。","options":["正确","错误"],"correct_option":0,"explanation":"正确。每个Al₂(SO₄)₃化学式单位含3个SO₄²⁻，对应物质的量为0.10×3 mol。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_MOLE_INTRO_25","mother_id":"M5R_H1_MOLE_INTRO_25","skill_id":"H1_MOLE_INTRO","concept_key":"H1_MOLE_INTRO__formula_unit_composition","level":3,"grade_band":"高一","stem":"判断：1 mol NaCl所数对象应写为NaCl化学式单位，而不是NaCl分子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。NaCl是离子晶体，不存在独立NaCl分子，计数对象应为化学式单位。","scaffold":"把已知量先换成n，并写清所数微粒及化学式下标。"},{"id":"Q5R_H1_PERIODIC_01","mother_id":"M5R_H1_PERIODIC_01","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__periodic_structure","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.主族元素的周期序数通常等于其原子的电子层数。 Ⅱ.周期反映原子核外电子层数。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。周期反映原子核外电子层数。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_02","mother_id":"M5R_H1_PERIODIC_02","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_period_trend","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.同周期主族元素从左到右，原子半径总体逐渐增大。 Ⅱ.核电荷数增加而电子层数相同，原子半径总体减小。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。核电荷数增加而电子层数相同，原子半径总体减小。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_03","mother_id":"M5R_H1_PERIODIC_03","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_period_trend","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.第三周期中Na原子半径大于Mg原子半径。 Ⅱ.同周期从左到右原子半径总体减小。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。同周期从左到右原子半径总体减小。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_04","mother_id":"M5R_H1_PERIODIC_04","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_period_trend","level":1,"grade_band":"高一","stem":"判断：第三周期中Cl的非金属性强于S。","options":["正确","错误"],"correct_option":0,"explanation":"正确。同周期从左到右非金属性总体增强。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_05","mother_id":"M5R_H1_PERIODIC_05","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_group_trend","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.同主族从上到下，原子半径总体增大。 Ⅱ.电子层数增加是半径增大的主要因素。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。电子层数增加是半径增大的主要因素。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_06","mother_id":"M5R_H1_PERIODIC_06","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_group_trend","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.同主族从上到下，元素的金属性总体减弱。 Ⅱ.原子更易失电子，金属性总体增强。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。原子更易失电子，金属性总体增强。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_07","mother_id":"M5R_H1_PERIODIC_07","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_group_trend","level":1,"grade_band":"高一","stem":"判断：Na的金属性强于K。","options":["正确","错误"],"correct_option":1,"explanation":"错误。同主族向下金属性增强，因此K强于Na。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_08","mother_id":"M5R_H1_PERIODIC_08","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_group_trend","level":1,"grade_band":"高一","stem":"判断：F的非金属性强于Cl。","options":["正确","错误"],"correct_option":0,"explanation":"正确。卤族从上到下非金属性减弱。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_09","mother_id":"M5R_H1_PERIODIC_09","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__compound_property_trend","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.NaOH的碱性强于Mg(OH)₂。 Ⅱ.第三周期最高价氧化物对应水化物的碱性从左到右总体减弱。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。第三周期最高价氧化物对应水化物的碱性从左到右总体减弱。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_10","mother_id":"M5R_H1_PERIODIC_10","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__compound_property_trend","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.HClO₄的酸性强于H₂SO₄。 Ⅱ.第三周期最高价含氧酸的酸性从左到右总体增强。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。第三周期最高价含氧酸的酸性从左到右总体增强。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_11","mother_id":"M5R_H1_PERIODIC_11","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__compound_property_trend","level":2,"grade_band":"高一","stem":"判断：同主族从上到下，气态氢化物的热稳定性总体增强。","options":["正确","错误"],"correct_option":1,"explanation":"错误。元素非金属性减弱、E—H键通常变弱，热稳定性总体下降。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_12","mother_id":"M5R_H1_PERIODIC_12","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__compound_property_trend","level":2,"grade_band":"高一","stem":"判断：HF的热稳定性强于HCl。","options":["正确","错误"],"correct_option":0,"explanation":"正确。F—H键强于Cl—H键，卤化氢热稳定性向下总体降低。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_13","mother_id":"M5R_H1_PERIODIC_13","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__periodic_structure","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.所有主族元素的最高正化合价都等于其主族序数。 Ⅱ.O、F等元素存在常见例外，不能机械套用。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。O、F等元素存在常见例外，不能机械套用。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_14","mother_id":"M5R_H1_PERIODIC_14","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__periodic_structure","level":2,"grade_band":"高一","stem":"判断：元素性质随原子序数递增呈周期性变化。","options":["正确","错误"],"correct_option":0,"explanation":"正确。核外电子排布的周期性导致性质的周期性。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_15","mother_id":"M5R_H1_PERIODIC_15","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__periodic_structure","level":2,"grade_band":"高一","stem":"判断：同主族元素的化学性质完全相同。","options":["正确","错误"],"correct_option":1,"explanation":"错误。价电子结构相似使性质相似，但原子半径等不同会造成差异。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_16","mother_id":"M5R_H1_PERIODIC_16","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__periodic_structure","level":2,"grade_band":"高一","stem":"判断：所有稀有气体原子的最外层都有8个电子。","options":["正确","错误"],"correct_option":1,"explanation":"错误。He的最外层只有2个电子，已达到稳定结构。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_17","mother_id":"M5R_H1_PERIODIC_17","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__particle_radius","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.Na⁺的半径小于Na原子的半径。 Ⅱ.Na失去最外层电子后电子层数减少，半径明显变小。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。Na失去最外层电子后电子层数减少，半径明显变小。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_18","mother_id":"M5R_H1_PERIODIC_18","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__particle_radius","level":3,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.Cl⁻的半径小于Cl原子的半径。 Ⅱ.Cl得到电子后电子间排斥增强，阴离子半径大于相应原子。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。Cl得到电子后电子间排斥增强，阴离子半径大于相应原子。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_19","mother_id":"M5R_H1_PERIODIC_19","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__particle_radius","level":3,"grade_band":"高一","stem":"判断：O²⁻、F⁻、Na⁺、Mg²⁺核外电子数相同，其中O²⁻半径最大。","options":["正确","错误"],"correct_option":0,"explanation":"正确。等电子粒子中核电荷数越小，对电子吸引越弱，半径越大。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_20","mother_id":"M5R_H1_PERIODIC_20","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_period_trend","level":3,"grade_band":"高一","stem":"判断：元素金属性越强，其原子通常越容易失去电子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。金属性可从原子失电子能力理解。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_21","mother_id":"M5R_H1_PERIODIC_21","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_period_trend","level":3,"grade_band":"高一","stem":"判断：元素非金属性越强，其原子通常越容易得到电子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。非金属性可从原子得电子能力理解。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_22","mother_id":"M5R_H1_PERIODIC_22","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__compound_property_trend","level":3,"grade_band":"高一","stem":"判断：第三周期最高价氧化物对应水化物的酸性总体从左到右增强。","options":["正确","错误"],"correct_option":0,"explanation":"正确。随中心元素非金属性增强，最高价含氧酸酸性总体增强。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_23","mother_id":"M5R_H1_PERIODIC_23","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__same_group_trend","level":3,"grade_band":"高一","stem":"判断：第ⅦA族气态氢化物的热稳定性从HF到HI总体降低。","options":["正确","错误"],"correct_option":0,"explanation":"正确。向下原子半径增大，H—X键能总体降低。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_24","mother_id":"M5R_H1_PERIODIC_24","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__particle_radius","level":3,"grade_band":"高一","stem":"判断：S²⁻、Cl⁻、K⁺、Ca²⁺核外电子数相同，其中Ca²⁺半径最大。","options":["正确","错误"],"correct_option":1,"explanation":"错误。这些粒子核外都有18个电子，核电荷数越大半径越小，因此S²⁻最大、Ca²⁺最小。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_PERIODIC_25","mother_id":"M5R_H1_PERIODIC_25","skill_id":"H1_PERIODIC","concept_key":"H1_PERIODIC__particle_radius","level":3,"grade_band":"高一","stem":"判断：Mg²⁺的半径大于Mg原子的半径。","options":["正确","错误"],"correct_option":1,"explanation":"错误。Mg失去最外层两个电子形成Mg²⁺后电子层数减少，半径变小。","scaffold":"先确定同周期或同主族，再从层数、核吸引和半径解释。"},{"id":"Q5R_H1_REDOX_01","mother_id":"M5R_H1_REDOX_01","skill_id":"H1_REDOX","concept_key":"H1_REDOX__redox_identification","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.有元素化合价发生变化的反应属于氧化还原反应。 Ⅱ.化合价变化是高中判断氧化还原反应的直接标志。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。化合价变化是高中判断氧化还原反应的直接标志。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_02","mother_id":"M5R_H1_REDOX_02","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_and_reagent_roles","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.某元素化合价升高，表示该元素得到电子。 Ⅱ.化合价升高对应失去电子，发生氧化反应。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。化合价升高对应失去电子，发生氧化反应。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_03","mother_id":"M5R_H1_REDOX_03","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_and_reagent_roles","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.某元素化合价降低，表示该元素得到电子。 Ⅱ.得到电子使有效正价降低，发生还原反应。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。得到电子使有效正价降低，发生还原反应。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_04","mother_id":"M5R_H1_REDOX_04","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_and_reagent_roles","level":1,"grade_band":"高一","stem":"判断：氧化剂在反应中自身被还原。","options":["正确","错误"],"correct_option":0,"explanation":"正确。氧化剂得到电子、所含元素化合价降低。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_05","mother_id":"M5R_H1_REDOX_05","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_and_reagent_roles","level":1,"grade_band":"高一","stem":"判断：还原剂在反应中自身被还原。","options":["正确","错误"],"correct_option":1,"explanation":"错误。还原剂失去电子、自身被氧化。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_06","mother_id":"M5R_H1_REDOX_06","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_conservation","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.同一氧化还原反应中，氧化过程和还原过程必然同时发生。 Ⅱ.电子有失必有得，两个过程不可分开。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。电子有失必有得，两个过程不可分开。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_07","mother_id":"M5R_H1_REDOX_07","skill_id":"H1_REDOX","concept_key":"H1_REDOX__oxidation_number","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.单质中元素的化合价一定为0。 Ⅱ.未化合单质中各元素按0价处理。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。未化合单质中各元素按0价处理。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_08","mother_id":"M5R_H1_REDOX_08","skill_id":"H1_REDOX","concept_key":"H1_REDOX__oxidation_number","level":1,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.单原子离子的化合价在数值和符号上等于其所带电荷。 Ⅱ.如Fe³⁺中Fe为+3价，Cl⁻中Cl为−1价。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。如Fe³⁺中Fe为+3价，Cl⁻中Cl为−1价。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_09","mother_id":"M5R_H1_REDOX_09","skill_id":"H1_REDOX","concept_key":"H1_REDOX__oxidation_number","level":2,"grade_band":"高一","stem":"判断：H₂O₂中O元素的化合价为−2价。","options":["正确","错误"],"correct_option":1,"explanation":"错误。过氧化物H₂O₂中O元素为−1价。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_10","mother_id":"M5R_H1_REDOX_10","skill_id":"H1_REDOX","concept_key":"H1_REDOX__reagent_judgement_in_reaction","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.Cl₂+2OH⁻=Cl⁻+ClO⁻+H₂O中Cl₂只作氧化剂。 Ⅱ.Cl由0价同时降到−1价、升到+1价，Cl₂既作氧化剂又作还原剂。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。Cl由0价同时降到−1价、升到+1价，Cl₂既作氧化剂又作还原剂。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_11","mother_id":"M5R_H1_REDOX_11","skill_id":"H1_REDOX","concept_key":"H1_REDOX__reagent_judgement_in_reaction","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.同一种元素的不同价态生成中间价态的反应可能是归中反应。 Ⅱ.高、低价态相互靠近形成中间价态，体现电子转移。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。高、低价态相互靠近形成中间价态，体现电子转移。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_12","mother_id":"M5R_H1_REDOX_12","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_conservation","level":2,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.Fe²⁺转化为Fe³⁺时，每个Fe²⁺失去1个电子。 Ⅱ.Fe由+2价升到+3价，失去1e⁻。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。Fe由+2价升到+3价，失去1e⁻。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_13","mother_id":"M5R_H1_REDOX_13","skill_id":"H1_REDOX","concept_key":"H1_REDOX__oxidation_number","level":2,"grade_band":"高一","stem":"判断：MnO₄⁻中Mn元素的化合价为+7价。","options":["正确","错误"],"correct_option":0,"explanation":"正确。设Mn为x，有x+4×(−2)=−1，得x=+7。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_14","mother_id":"M5R_H1_REDOX_14","skill_id":"H1_REDOX","concept_key":"H1_REDOX__oxidation_number","level":2,"grade_band":"高一","stem":"判断：SO₃²⁻中S元素的化合价为+6价。","options":["正确","错误"],"correct_option":1,"explanation":"错误。设S为x，有x+3×(−2)=−2，得x=+4。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_15","mother_id":"M5R_H1_REDOX_15","skill_id":"H1_REDOX","concept_key":"H1_REDOX__reagent_judgement_in_reaction","level":2,"grade_band":"高一","stem":"判断：H₂O₂只能表现氧化性，不能表现还原性。","options":["正确","错误"],"correct_option":1,"explanation":"错误。H₂O₂中O为中间价态，遇不同反应物可表现氧化性或还原性。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_16","mother_id":"M5R_H1_REDOX_16","skill_id":"H1_REDOX","concept_key":"H1_REDOX__reagent_judgement_in_reaction","level":2,"grade_band":"高一","stem":"判断：2Na+Cl₂=2NaCl中Na是还原剂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Na由0价升到+1价，失电子并还原Cl₂。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_17","mother_id":"M5R_H1_REDOX_17","skill_id":"H1_REDOX","concept_key":"H1_REDOX__reagent_judgement_in_reaction","level":2,"grade_band":"高一","stem":"判断：CuO+H₂=Cu+H₂O中CuO是氧化剂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Cu由+2价降到0价，CuO得到电子并氧化H₂。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_18","mother_id":"M5R_H1_REDOX_18","skill_id":"H1_REDOX","concept_key":"H1_REDOX__redox_identification","level":3,"grade_band":"高一","stem":"组合判断：判断下列两项：Ⅰ.HCl+NaOH=NaCl+H₂O属于氧化还原反应。 Ⅱ.各元素反应前后化合价不变，这是酸碱中和反应。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。各元素反应前后化合价不变，这是酸碱中和反应。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_19","mother_id":"M5R_H1_REDOX_19","skill_id":"H1_REDOX","concept_key":"H1_REDOX__redox_identification","level":3,"grade_band":"高一","stem":"判断：AgNO₃+NaCl=AgCl↓+NaNO₃属于氧化还原反应。","options":["正确","错误"],"correct_option":1,"explanation":"错误。反应只发生离子交换和沉淀生成，没有化合价变化。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_20","mother_id":"M5R_H1_REDOX_20","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_conservation","level":3,"grade_band":"高一","stem":"判断：配平氧化还原反应时，电子得失总数必须相等。","options":["正确","错误"],"correct_option":0,"explanation":"正确。电子守恒是确定氧化剂、还原剂计量关系的核心约束。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_21","mother_id":"M5R_H1_REDOX_21","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_conservation","level":3,"grade_band":"高一","stem":"判断：电子守恒成立后，不必再检查原子守恒。","options":["正确","错误"],"correct_option":1,"explanation":"错误。配平还必须同时满足各元素原子数守恒，离子方程式还需满足电荷守恒。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_22","mother_id":"M5R_H1_REDOX_22","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_and_reagent_roles","level":3,"grade_band":"高一","stem":"判断：还原剂失电子后形成的物质称为氧化产物。","options":["正确","错误"],"correct_option":0,"explanation":"正确。还原剂发生氧化，其生成物是氧化产物。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_23","mother_id":"M5R_H1_REDOX_23","skill_id":"H1_REDOX","concept_key":"H1_REDOX__redox_identification","level":3,"grade_band":"高一","stem":"判断：没有氧元素参加的反应一定不是氧化还原反应。","options":["正确","错误"],"correct_option":1,"explanation":"错误。氧化还原的本质是电子转移，如H₂与Cl₂反应不含氧仍是氧化还原。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_24","mother_id":"M5R_H1_REDOX_24","skill_id":"H1_REDOX","concept_key":"H1_REDOX__redox_identification","level":3,"grade_band":"高一","stem":"判断：只要反应物中含有O₂，该反应就一定是氧化还原反应。","options":["正确","错误"],"correct_option":1,"explanation":"错误。仍应检查化合价是否变化，不能只凭物质中含氧作判断。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H1_REDOX_25","mother_id":"M5R_H1_REDOX_25","skill_id":"H1_REDOX","concept_key":"H1_REDOX__electron_conservation","level":3,"grade_band":"高一","stem":"判断：2KClO₃=2KCl+3O₂↑中，Cl由+5价降为−1价，O由−2价升为0价。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Cl得到电子、O失去电子，反应中同时存在化合价升高和降低。","scaffold":"标出变化元素的反应前后化合价，再核对电子得失。"},{"id":"Q5R_H2_ELECTRO_01","mother_id":"M5R_H2_ELECTRO_01","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrode_definition_and_polarity","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.所有电化学装置中，阳极都发生氧化反应。 Ⅱ.阳极、阴极按反应类型命名，与正负极号无关。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。阳极、阴极按反应类型命名，与正负极号无关。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_02","mother_id":"M5R_H2_ELECTRO_02","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrode_definition_and_polarity","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.所有电化学装置中，阴极都发生还原反应。 Ⅱ.阴极接受电子，发生还原。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。阴极接受电子，发生还原。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_03","mother_id":"M5R_H2_ELECTRO_03","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrode_definition_and_polarity","level":1,"grade_band":"高二","stem":"判断：原电池中负极是阳极，发生氧化反应。","options":["正确","错误"],"correct_option":0,"explanation":"正确。负极材料或反应物失电子，电子流向正极。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_04","mother_id":"M5R_H2_ELECTRO_04","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrode_definition_and_polarity","level":1,"grade_band":"高二","stem":"判断：原电池中正极发生氧化反应。","options":["正确","错误"],"correct_option":1,"explanation":"错误。原电池正极是阴极，发生还原反应。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_05","mother_id":"M5R_H2_ELECTRO_05","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrode_definition_and_polarity","level":1,"grade_band":"高二","stem":"判断：电解池中与电源正极相连的电极是阳极。","options":["正确","错误"],"correct_option":0,"explanation":"正确。电源正极从该电极抽走电子，使其发生氧化。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_06","mother_id":"M5R_H2_ELECTRO_06","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrolysis_and_refining","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.电解池中与电源负极相连的电极发生氧化反应。 Ⅱ.负接阴极，阴极得到电子并发生还原。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。负接阴极，阴极得到电子并发生还原。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_07","mother_id":"M5R_H2_ELECTRO_07","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_and_ion_path","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.电子在外电路中由原电池负极流向正极。 Ⅱ.负极释放电子，正极消耗电子。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。负极释放电子，正极消耗电子。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_08","mother_id":"M5R_H2_ELECTRO_08","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_and_ion_path","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.盐桥中的电子会从负极溶液迁移到正极溶液。 Ⅱ.电子走外导线，盐桥中迁移的是阴、阳离子。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。电子走外导线，盐桥中迁移的是阴、阳离子。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_09","mother_id":"M5R_H2_ELECTRO_09","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_and_ion_path","level":2,"grade_band":"高二","stem":"判断：盐桥可维持两半电池溶液的电中性并构成离子通路。","options":["正确","错误"],"correct_option":0,"explanation":"正确。离子迁移补偿电荷积累，使电路持续工作。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_10","mother_id":"M5R_H2_ELECTRO_10","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_and_ion_path","level":2,"grade_band":"高二","stem":"判断：原电池工作时，阴离子通常向负极区迁移。","options":["正确","错误"],"correct_option":0,"explanation":"正确。负极氧化常产生阳离子，阴离子迁入以维持电中性。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_11","mother_id":"M5R_H2_ELECTRO_11","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_and_ion_path","level":2,"grade_band":"高二","stem":"判断：原电池工作时，电流方向与电子定向移动方向相同。","options":["正确","错误"],"correct_option":1,"explanation":"错误。约定电流方向与电子移动方向相反。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_12","mother_id":"M5R_H2_ELECTRO_12","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__corrosion_and_protection","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.锌—铜原电池中若Zn作负极，则Zn电极质量通常减小。 Ⅱ.Zn失电子形成Zn²⁺进入溶液。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。Zn失电子形成Zn²⁺进入溶液。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_13","mother_id":"M5R_H2_ELECTRO_13","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrolysis_and_refining","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.电解CuSO₄溶液时，阴极若析出Cu，阴极质量会增加。 Ⅱ.Cu²⁺得到电子沉积为Cu。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。Cu²⁺得到电子沉积为Cu。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_14","mother_id":"M5R_H2_ELECTRO_14","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrolysis_and_refining","level":2,"grade_band":"高二","stem":"判断：用惰性电极电解NaCl水溶液时，阴极一定析出Na。","options":["正确","错误"],"correct_option":1,"explanation":"错误。水溶液中水比Na⁺更易在阴极还原，通常生成H₂。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_15","mother_id":"M5R_H2_ELECTRO_15","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrolysis_and_refining","level":2,"grade_band":"高二","stem":"判断：铜的电解精炼中，粗铜通常作阳极。","options":["正确","错误"],"correct_option":0,"explanation":"正确。阳极粗铜失电子溶解，纯铜在阴极析出。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_16","mother_id":"M5R_H2_ELECTRO_16","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electrolysis_and_refining","level":2,"grade_band":"高二","stem":"判断：铜的电解精炼中，纯铜薄片作阳极。","options":["正确","错误"],"correct_option":1,"explanation":"错误。纯铜薄片作阴极以沉积更纯的铜。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_17","mother_id":"M5R_H2_ELECTRO_17","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.在钢铁上连接更活泼的锌块可实现牺牲阳极保护。 Ⅱ.Zn优先氧化，钢铁作为阴极受到保护。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。Zn优先氧化，钢铁作为阴极受到保护。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_18","mother_id":"M5R_H2_ELECTRO_18","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高二","stem":"判断：外加电流阴极保护法中，被保护金属应连接直流电源正极。","options":["正确","错误"],"correct_option":1,"explanation":"错误。被保护金属接电源负极成为阴极。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_19","mother_id":"M5R_H2_ELECTRO_19","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高二","stem":"判断：金属发生吸氧腐蚀时，正极反应可为O₂+2H₂O+4e⁻=4OH⁻。","options":["正确","错误"],"correct_option":0,"explanation":"正确。中性或弱碱性含氧水膜中常发生氧的还原。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_20","mother_id":"M5R_H2_ELECTRO_20","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高二","stem":"判断：析氢腐蚀和吸氧腐蚀中，负极都发生金属氧化。","options":["正确","错误"],"correct_option":0,"explanation":"正确。两者的主要区别在正极反应，负极均为较活泼金属失电子。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_21","mother_id":"M5R_H2_ELECTRO_21","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_stoichiometry_and_battery","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.通过电路转移1 mol电子时，电子数为N_A。 Ⅱ.电子的物质的量同样满足N=nN_A。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。电子的物质的量同样满足N=nN_A。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_22","mother_id":"M5R_H2_ELECTRO_22","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_stoichiometry_and_battery","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.电极上生成1 mol Cu需要转移1 mol电子。 Ⅱ.Cu²⁺+2e⁻=Cu，生成1 mol Cu需2 mol电子。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。Cu²⁺+2e⁻=Cu，生成1 mol Cu需2 mol电子。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_23","mother_id":"M5R_H2_ELECTRO_23","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_stoichiometry_and_battery","level":3,"grade_band":"高二","stem":"判断：电极上生成1 mol Cl₂需要Cl⁻失去2 mol电子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。2Cl⁻−2e⁻=Cl₂。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_24","mother_id":"M5R_H2_ELECTRO_24","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_stoichiometry_and_battery","level":3,"grade_band":"高二","stem":"判断：可充电电池充电时，外加电源迫使放电总反应逆向进行。","options":["正确","错误"],"correct_option":0,"explanation":"正确。充电把电能转化为化学能，电极反应方向与放电相反。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_ELECTRO_25","mother_id":"M5R_H2_ELECTRO_25","skill_id":"H2_ELECTRO","concept_key":"H2_ELECTRO__electron_stoichiometry_and_battery","level":3,"grade_band":"高二","stem":"判断：燃料电池把燃料燃烧的化学能先全部转化为热能再转化为电能。","options":["正确","错误"],"correct_option":1,"explanation":"错误。燃料电池通过电化学反应直接把化学能转化为电能。","scaffold":"先定阳极氧化、阴极还原，再画电子和离子通道。"},{"id":"Q5R_H2_EQUIL_01","mother_id":"M5R_H2_EQUIL_01","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__dynamic_equilibrium_features","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.可逆反应在一定条件下达到平衡时，正反应速率等于逆反应速率。 Ⅱ.速率相等使各组分浓度保持不变。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。速率相等使各组分浓度保持不变。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_02","mother_id":"M5R_H2_EQUIL_02","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__dynamic_equilibrium_features","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.达到化学平衡后，反应物和生成物的浓度一定相等。 Ⅱ.平衡要求浓度不再变化，不要求各物质浓度数值相等。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。平衡要求浓度不再变化，不要求各物质浓度数值相等。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_03","mother_id":"M5R_H2_EQUIL_03","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__dynamic_equilibrium_features","level":1,"grade_band":"高二","stem":"判断：化学平衡是一种动态平衡。","options":["正确","错误"],"correct_option":0,"explanation":"正确。平衡时正、逆反应仍持续进行，只是宏观组成不变。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_04","mother_id":"M5R_H2_EQUIL_04","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__dynamic_equilibrium_features","level":1,"grade_band":"高二","stem":"判断：密闭容器内所有反应最终都能建立化学平衡。","options":["正确","错误"],"correct_option":1,"explanation":"错误。只有一定条件下的可逆反应才可能建立化学平衡。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_05","mother_id":"M5R_H2_EQUIL_05","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__dynamic_equilibrium_features","level":1,"grade_band":"高二","stem":"判断：一定温度下达到平衡后，各组分浓度保持不变。","options":["正确","错误"],"correct_option":0,"explanation":"正确。宏观量不再随时间改变是平衡标志之一。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_06","mother_id":"M5R_H2_EQUIL_06","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__temperature_and_catalyst_shift","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.加入催化剂能使化学平衡向生成物方向移动。 Ⅱ.催化剂同倍加快正、逆反应，只缩短达到平衡的时间。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。催化剂同倍加快正、逆反应，只缩短达到平衡的时间。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_07","mother_id":"M5R_H2_EQUIL_07","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__temperature_and_catalyst_shift","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.升高温度，平衡总向吸热反应方向移动。 Ⅱ.温度改变时，体系通过增强吸热方向来减弱升温影响。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。温度改变时，体系通过增强吸热方向来减弱升温影响。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_08","mother_id":"M5R_H2_EQUIL_08","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__temperature_and_catalyst_shift","level":2,"grade_band":"高二","stem":"判断：降低温度，平衡总向吸热反应方向移动。","options":["正确","错误"],"correct_option":1,"explanation":"错误。降温时平衡向放热方向移动。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_09","mother_id":"M5R_H2_EQUIL_09","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__concentration_disturbance","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.增大某反应物浓度，平衡通常向消耗该反应物的方向移动。 Ⅱ.体系通过移动来减弱该浓度增大的影响。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。体系通过移动来减弱该浓度增大的影响。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_10","mother_id":"M5R_H2_EQUIL_10","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__concentration_disturbance","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.移去部分生成物，平衡通常向生成物方向移动。 Ⅱ.正向反应补充被移去的生成物。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。正向反应补充被移去的生成物。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_11","mother_id":"M5R_H2_EQUIL_11","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__pressure_inert_gas_and_solid","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.对于有气体参加且两侧气体总物质的量不同的平衡，增压会向气体物质的量较少一侧移动。 Ⅱ.减小体积增压时，移动方向倾向减小气体总物质的量。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。减小体积增压时，移动方向倾向减小气体总物质的量。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_12","mother_id":"M5R_H2_EQUIL_12","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__pressure_inert_gas_and_solid","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.对气体总物质的量反应前后相等的平衡，恒温压缩一定使平衡移动。 Ⅱ.各气体浓度按相同比例改变时反应商可保持与K相等，平衡可不移动。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。各气体浓度按相同比例改变时反应商可保持与K相等，平衡可不移动。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_13","mother_id":"M5R_H2_EQUIL_13","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__pressure_inert_gas_and_solid","level":2,"grade_band":"高二","stem":"判断：恒温恒容加入惰性气体时，原反应平衡一定移动。","options":["正确","错误"],"correct_option":1,"explanation":"错误。反应组分浓度和分压不变，反应商不变。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_14","mother_id":"M5R_H2_EQUIL_14","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__pressure_inert_gas_and_solid","level":2,"grade_band":"高二","stem":"判断：纯固体的用量发生少量改变，只要仍有固体存在，通常不引起平衡移动。","options":["正确","错误"],"correct_option":0,"explanation":"正确。纯固体活度视为常数，不进入常见平衡常数表达式。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_15","mother_id":"M5R_H2_EQUIL_15","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__equilibrium_path_and_new_state","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.平衡移动能完全抵消外界条件的改变。 Ⅱ.勒夏特列原理强调减弱改变，而不是完全消除。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。勒夏特列原理强调减弱改变，而不是完全消除。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_16","mother_id":"M5R_H2_EQUIL_16","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__equilibrium_path_and_new_state","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.达到同一温度下的同一平衡状态，可以从正反应方向或逆反应方向建立。 Ⅱ.平衡状态不取决于接近平衡的路径。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。平衡状态不取决于接近平衡的路径。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_17","mother_id":"M5R_H2_EQUIL_17","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__equilibrium_path_and_new_state","level":3,"grade_band":"高二","stem":"判断：同温下同一反应的平衡常数相同，但平衡组成可因初始投料不同而不同。","options":["正确","错误"],"correct_option":0,"explanation":"正确。K固定的是组成之间的关系，不唯一规定每个浓度。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_18","mother_id":"M5R_H2_EQUIL_18","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__equilibrium_path_and_new_state","level":3,"grade_band":"高二","stem":"判断：改变浓度使平衡移动时，平衡常数K随之改变。","options":["正确","错误"],"correct_option":1,"explanation":"错误。同一反应的K只随温度改变。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_19","mother_id":"M5R_H2_EQUIL_19","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__concentration_disturbance","level":3,"grade_band":"高二","stem":"判断：增大反应物浓度的瞬间，正反应速率通常先增大，而逆反应速率可暂时不变。","options":["正确","错误"],"correct_option":0,"explanation":"正确。瞬间只有与该反应物有关的速率项直接变化。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_20","mother_id":"M5R_H2_EQUIL_20","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__temperature_and_catalyst_shift","level":3,"grade_band":"高二","stem":"判断：升高温度的瞬间，正、逆反应速率通常都会增大。","options":["正确","错误"],"correct_option":0,"explanation":"正确。升温同时加快两个方向，之后根据增大倍数不同决定移动方向。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_21","mother_id":"M5R_H2_EQUIL_21","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__concentration_disturbance","level":3,"grade_band":"高二","stem":"判断：平衡正向移动后，反应物浓度一定低于改变条件前的浓度。","options":["正确","错误"],"correct_option":1,"explanation":"错误。若先加入反应物再正向移动，新平衡浓度仍可能高于原平衡。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_22","mother_id":"M5R_H2_EQUIL_22","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__concentration_disturbance","level":3,"grade_band":"高二","stem":"判断：判断平衡移动方向时，可以比较改变后瞬间的反应商Q与平衡常数K。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Q<K向正向进行，Q>K向逆向进行。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_23","mother_id":"M5R_H2_EQUIL_23","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__temperature_and_catalyst_shift","level":3,"grade_band":"高二","stem":"判断：对于放热正反应，升温会降低其平衡转化率。","options":["正确","错误"],"correct_option":0,"explanation":"正确。升温使平衡向吸热的逆反应方向移动。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_24","mother_id":"M5R_H2_EQUIL_24","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__pressure_inert_gas_and_solid","level":3,"grade_band":"高二","stem":"判断：对于气体物质的量减小的正反应，增压有利于提高平衡转化率。","options":["正确","错误"],"correct_option":0,"explanation":"正确。增压使平衡向气体总量较少的正向移动。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_EQUIL_25","mother_id":"M5R_H2_EQUIL_25","skill_id":"H2_EQUIL","concept_key":"H2_EQUIL__equilibrium_path_and_new_state","level":3,"grade_band":"高二","stem":"判断：化学平衡移动后建立新平衡时，正、逆反应速率再次相等。","options":["正确","错误"],"correct_option":0,"explanation":"正确。新平衡仍满足动态平衡的速率条件。","scaffold":"写出外界改变后瞬间Q、K或正逆速率的相对关系。"},{"id":"Q5R_H2_K_01","mother_id":"M5R_H2_K_01","skill_id":"H2_K","concept_key":"H2_K__equilibrium_constant_expression","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.一定温度下，可逆反应达到平衡时生成物浓度幂之积与反应物浓度幂之积的比值为常数。 Ⅱ.按化学计量数作指数可得到浓度平衡常数表达式。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。按化学计量数作指数可得到浓度平衡常数表达式。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_02","mother_id":"M5R_H2_K_02","skill_id":"H2_K","concept_key":"H2_K__equilibrium_constant_expression","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.平衡常数表达式中各浓度的指数等于相应化学计量数。 Ⅱ.指数来自配平后的反应方程式系数。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。指数来自配平后的反应方程式系数。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_03","mother_id":"M5R_H2_K_03","skill_id":"H2_K","concept_key":"H2_K__equilibrium_constant_expression","level":1,"grade_band":"高二","stem":"判断：纯固体和纯液体通常不写入浓度平衡常数表达式。","options":["正确","错误"],"correct_option":0,"explanation":"正确。其活度在一定条件下视为常数，已并入K。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_04","mother_id":"M5R_H2_K_04","skill_id":"H2_K","concept_key":"H2_K__equation_change_and_constant","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.同一反应的平衡常数只与温度有关。 Ⅱ.改变浓度、压强或催化剂不改变给定温度下的K。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。改变浓度、压强或催化剂不改变给定温度下的K。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_05","mother_id":"M5R_H2_K_05","skill_id":"H2_K","concept_key":"H2_K__equation_change_and_constant","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.加入催化剂会增大平衡常数。 Ⅱ.催化剂不改变热力学平衡状态，因此K不变。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。催化剂不改变热力学平衡状态，因此K不变。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_06","mother_id":"M5R_H2_K_06","skill_id":"H2_K","concept_key":"H2_K__equation_change_and_constant","level":1,"grade_band":"高二","stem":"判断：反应方程式反向书写时，新平衡常数等于原平衡常数的倒数。","options":["正确","错误"],"correct_option":0,"explanation":"正确。生成物和反应物在表达式中互换。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_07","mother_id":"M5R_H2_K_07","skill_id":"H2_K","concept_key":"H2_K__equation_change_and_constant","level":2,"grade_band":"高二","stem":"判断：反应方程式各系数扩大2倍时，新平衡常数等于原K的2倍。","options":["正确","错误"],"correct_option":1,"explanation":"错误。浓度幂的指数都扩大2倍，新常数为K²。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_08","mother_id":"M5R_H2_K_08","skill_id":"H2_K","concept_key":"H2_K__equation_change_and_constant","level":2,"grade_band":"高二","stem":"判断：两个反应方程式相加得到目标反应时，目标平衡常数等于分步平衡常数之积。","options":["正确","错误"],"correct_option":0,"explanation":"正确。反应相加对应自由能变化相加，K按乘法组合。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_09","mother_id":"M5R_H2_K_09","skill_id":"H2_K","concept_key":"H2_K__reaction_quotient_direction","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.平衡常数很大说明该温度下反应进行得快。 Ⅱ.K反映平衡进行程度，不反映达到平衡的速率。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。K反映平衡进行程度，不反映达到平衡的速率。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_10","mother_id":"M5R_H2_K_10","skill_id":"H2_K","concept_key":"H2_K__reaction_quotient_direction","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.平衡常数越大，通常表示平衡时生成物相对更占优势。 Ⅱ.K大意味着生成物浓度幂之积相对较大。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。K大意味着生成物浓度幂之积相对较大。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_11","mother_id":"M5R_H2_K_11","skill_id":"H2_K","concept_key":"H2_K__reaction_quotient_direction","level":2,"grade_band":"高二","stem":"判断：反应商Q的表达式形式与平衡常数K相同，但可使用任意时刻浓度。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Q用于判断当前组成相对平衡的位置。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_12","mother_id":"M5R_H2_K_12","skill_id":"H2_K","concept_key":"H2_K__reaction_quotient_direction","level":2,"grade_band":"高二","stem":"判断：当Q<K时，反应将净向正反应方向进行。","options":["正确","错误"],"correct_option":0,"explanation":"正确。当前生成物相对不足，体系向右建立平衡。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_13","mother_id":"M5R_H2_K_13","skill_id":"H2_K","concept_key":"H2_K__reaction_quotient_direction","level":2,"grade_band":"高二","stem":"判断：某温度下H₂(g)+I₂(g)⇌2HI(g)的Kc=50；某时刻c(H₂)=c(I₂)=0.20 mol·L⁻¹、c(HI)=0.40 mol·L⁻¹，此时反应将净向逆反应方向进行。","options":["正确","错误"],"correct_option":1,"explanation":"错误。此时Qc=0.40²÷(0.20×0.20)=4.0<Kc，体系将净向正反应方向进行。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_14","mother_id":"M5R_H2_K_14","skill_id":"H2_K","concept_key":"H2_K__equilibrium_composition_calculation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.当Q=K时，体系一定处于该温度下的平衡状态。 Ⅱ.组成满足平衡关系，正、逆反应速率相等。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。组成满足平衡关系，正、逆反应速率相等。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_15","mother_id":"M5R_H2_K_15","skill_id":"H2_K","concept_key":"H2_K__constant_constraints_and_temperature","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.一定温度下某反应的K=4.0，改变各物质初始浓度后该温度下K仍为4.0。 Ⅱ.同一反应的平衡常数只由温度决定，不随初始浓度改变。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。同一反应的平衡常数只由温度决定，不随初始浓度改变。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_16","mother_id":"M5R_H2_K_16","skill_id":"H2_K","concept_key":"H2_K__equilibrium_constant_expression","level":2,"grade_band":"高二","stem":"判断：N₂(g)+3H₂(g)⇌2NH₃(g)的Kc可写为c²(NH₃)/[c(N₂)c³(H₂)]。","options":["正确","错误"],"correct_option":0,"explanation":"正确。各浓度指数分别对应方程式系数2、1、3。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_17","mother_id":"M5R_H2_K_17","skill_id":"H2_K","concept_key":"H2_K__equilibrium_constant_expression","level":3,"grade_band":"高二","stem":"判断：C(s)+CO₂(g)⇌2CO(g)的Kc表达式中应写入c(C)。","options":["正确","错误"],"correct_option":1,"explanation":"错误。C为纯固体，不写入常见Kc表达式。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_18","mother_id":"M5R_H2_K_18","skill_id":"H2_K","concept_key":"H2_K__equilibrium_composition_calculation","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.若某反应平衡时反应物和生成物浓度都乘2，原组成一定仍满足同一K。 Ⅱ.除特殊系数关系外，反应商会改变，不能只看同比放大。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。除特殊系数关系外，反应商会改变，不能只看同比放大。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_19","mother_id":"M5R_H2_K_19","skill_id":"H2_K","concept_key":"H2_K__equilibrium_composition_calculation","level":3,"grade_band":"高二","stem":"判断：用“起始—变化—平衡”三段式计算时，各物质浓度变化量之比等于化学计量数之比。","options":["正确","错误"],"correct_option":0,"explanation":"正确。同一反应进度决定各组分变化量。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_20","mother_id":"M5R_H2_K_20","skill_id":"H2_K","concept_key":"H2_K__equilibrium_composition_calculation","level":3,"grade_band":"高二","stem":"判断：平衡转化率等于已转化的反应物量与其起始量之比。","options":["正确","错误"],"correct_option":0,"explanation":"正确。分母应使用该反应物的起始量。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_21","mother_id":"M5R_H2_K_21","skill_id":"H2_K","concept_key":"H2_K__constant_constraints_and_temperature","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.增加反应物起始量后，平衡常数一定增大。 Ⅱ.温度不变时K不变，起始量只影响平衡组成和转化率。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。温度不变时K不变，起始量只影响平衡组成和转化率。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_22","mother_id":"M5R_H2_K_22","skill_id":"H2_K","concept_key":"H2_K__equilibrium_composition_calculation","level":3,"grade_band":"高二","stem":"判断：同温下已知K和各物质起始浓度，可结合变化量列方程求平衡组成。","options":["正确","错误"],"correct_option":0,"explanation":"正确。三段式给出平衡浓度，再代入K表达式。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_23","mother_id":"M5R_H2_K_23","skill_id":"H2_K","concept_key":"H2_K__constant_constraints_and_temperature","level":3,"grade_band":"高二","stem":"判断：平衡浓度可以为负数，只要代入K能得到正值。","options":["正确","错误"],"correct_option":1,"explanation":"错误。浓度必须满足非负和物料约束，负根应舍去。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_24","mother_id":"M5R_H2_K_24","skill_id":"H2_K","concept_key":"H2_K__constant_constraints_and_temperature","level":3,"grade_band":"高二","stem":"判断：若正反应吸热，升高温度后正反应的平衡常数通常增大。","options":["正确","错误"],"correct_option":0,"explanation":"正确。升温有利于吸热方向，生成物相对增多，K增大。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_K_25","mother_id":"M5R_H2_K_25","skill_id":"H2_K","concept_key":"H2_K__constant_constraints_and_temperature","level":3,"grade_band":"高二","stem":"判断：某反应的平衡常数由400 K时的6.2×10³降至500 K时的1.1×10³，据此可判断该正反应通常为放热反应。","options":["正确","错误"],"correct_option":0,"explanation":"正确。升温后K减小，说明升温有利于吸热的逆反应方向，因此正反应通常放热。","scaffold":"先配平方程式，再写Q或K表达式并检查固液项。"},{"id":"Q5R_H2_KSP_01","mother_id":"M5R_H2_KSP_01","skill_id":"H2_KSP","concept_key":"H2_KSP__dissolution_equilibrium_expression","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.难溶电解质在水中也存在微量溶解并建立动态平衡。 Ⅱ.难溶不等于绝对不溶，饱和溶液中溶解与沉淀速率相等。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。难溶不等于绝对不溶，饱和溶液中溶解与沉淀速率相等。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_02","mother_id":"M5R_H2_KSP_02","skill_id":"H2_KSP","concept_key":"H2_KSP__dissolution_equilibrium_expression","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.AgCl(s)⇌Ag⁺(aq)+Cl⁻(aq)的Ksp=c(Ag⁺)c(Cl⁻)。 Ⅱ.纯固体AgCl不写入表达式。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。纯固体AgCl不写入表达式。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_03","mother_id":"M5R_H2_KSP_03","skill_id":"H2_KSP","concept_key":"H2_KSP__dissolution_equilibrium_expression","level":1,"grade_band":"高二","stem":"判断：CaF₂(s)⇌Ca²⁺+2F⁻的Ksp=c(Ca²⁺)c(F⁻)。","options":["正确","错误"],"correct_option":1,"explanation":"错误。F⁻浓度的指数应为2，Ksp=c(Ca²⁺)c²(F⁻)。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_04","mother_id":"M5R_H2_KSP_04","skill_id":"H2_KSP","concept_key":"H2_KSP__dissolution_equilibrium_expression","level":1,"grade_band":"高二","stem":"判断：同一难溶电解质的Ksp只与温度有关。","options":["正确","错误"],"correct_option":0,"explanation":"正确。温度一定时Ksp不随沉淀量或离子初始浓度改变。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_05","mother_id":"M5R_H2_KSP_05","skill_id":"H2_KSP","concept_key":"H2_KSP__common_ion_and_solubility","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.向AgCl饱和溶液中加入NaCl会增大AgCl的溶解度。 Ⅱ.Cl⁻同离子使溶解平衡左移，AgCl溶解度减小。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。Cl⁻同离子使溶解平衡左移，AgCl溶解度减小。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_06","mother_id":"M5R_H2_KSP_06","skill_id":"H2_KSP","concept_key":"H2_KSP__common_ion_and_solubility","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.向AgCl饱和溶液中移去Ag⁺会促进AgCl溶解。 Ⅱ.移去溶解产物使平衡向右移动。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。移去溶解产物使平衡向右移动。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_07","mother_id":"M5R_H2_KSP_07","skill_id":"H2_KSP","concept_key":"H2_KSP__ion_product_and_precipitation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.离子积Qsp<Ksp时，溶液中一定会立即生成沉淀。 Ⅱ.Qsp<Ksp表示未饱和，若有固体则继续溶解，不会析出沉淀。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。Qsp<Ksp表示未饱和，若有固体则继续溶解，不会析出沉淀。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_08","mother_id":"M5R_H2_KSP_08","skill_id":"H2_KSP","concept_key":"H2_KSP__ion_product_and_precipitation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.离子积Qsp>Ksp时，从平衡角度看有生成沉淀的趋势。 Ⅱ.体系需降低相关离子浓度，使Qsp回到Ksp。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。体系需降低相关离子浓度，使Qsp回到Ksp。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_09","mother_id":"M5R_H2_KSP_09","skill_id":"H2_KSP","concept_key":"H2_KSP__ion_product_and_precipitation","level":2,"grade_band":"高二","stem":"判断：离子积Qsp=Ksp时，体系处于相应难溶电解质的溶解平衡。","options":["正确","错误"],"correct_option":0,"explanation":"正确。此时溶液达到饱和，若有固体则宏观量保持不变。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_10","mother_id":"M5R_H2_KSP_10","skill_id":"H2_KSP","concept_key":"H2_KSP__solubility_calculation_and_residual","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.比较两种难溶物的Ksp大小即可直接比较其摩尔溶解度大小。 Ⅱ.化学式中离子计量关系不同时，Ksp与溶解度关系不同。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。化学式中离子计量关系不同时，Ksp与溶解度关系不同。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_11","mother_id":"M5R_H2_KSP_11","skill_id":"H2_KSP","concept_key":"H2_KSP__solubility_calculation_and_residual","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.在纯水中AgCl的摩尔溶解度为s时，Ksp=s²。 Ⅱ.Ag⁺和Cl⁻浓度均为s。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。Ag⁺和Cl⁻浓度均为s。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_12","mother_id":"M5R_H2_KSP_12","skill_id":"H2_KSP","concept_key":"H2_KSP__solubility_calculation_and_residual","level":2,"grade_band":"高二","stem":"判断：在纯水中CaF₂的摩尔溶解度为s时，Ksp=2s²。","options":["正确","错误"],"correct_option":1,"explanation":"错误。c(Ca²⁺)=s、c(F⁻)=2s，所以Ksp=s(2s)²=4s³。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_13","mother_id":"M5R_H2_KSP_13","skill_id":"H2_KSP","concept_key":"H2_KSP__solubility_calculation_and_residual","level":2,"grade_band":"高二","stem":"判断：沉淀反应达到平衡后，溶液中相关离子浓度都等于0。","options":["正确","错误"],"correct_option":1,"explanation":"错误。难溶物仍有有限溶解度，平衡溶液中离子浓度不为0。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_14","mother_id":"M5R_H2_KSP_14","skill_id":"H2_KSP","concept_key":"H2_KSP__solubility_calculation_and_residual","level":2,"grade_band":"高二","stem":"判断：沉淀完全通常是近似说法，不表示被沉淀离子绝对为0。","options":["正确","错误"],"correct_option":0,"explanation":"正确。只要Ksp有限，平衡时通常仍残留少量离子。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_15","mother_id":"M5R_H2_KSP_15","skill_id":"H2_KSP","concept_key":"H2_KSP__precipitation_conversion_and_separation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.用含共同离子的溶液洗涤沉淀，有时可减少沉淀溶解损失。 Ⅱ.共同离子效应能抑制沉淀溶解。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。共同离子效应能抑制沉淀溶解。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_16","mother_id":"M5R_H2_KSP_16","skill_id":"H2_KSP","concept_key":"H2_KSP__precipitation_conversion_and_separation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.向含等浓度Cl⁻和I⁻的溶液中逐滴加AgNO₃，Ksp更小的银盐通常先沉淀。 Ⅱ.在离子初始浓度相同的前提下，达到较小Ksp所需Ag⁺浓度更低。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。在离子初始浓度相同的前提下，达到较小Ksp所需Ag⁺浓度更低。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_17","mother_id":"M5R_H2_KSP_17","skill_id":"H2_KSP","concept_key":"H2_KSP__precipitation_conversion_and_separation","level":3,"grade_band":"高二","stem":"判断：发生沉淀转化时，通常趋向生成更难溶的物质。","options":["正确","错误"],"correct_option":0,"explanation":"正确。更难溶产物的形成可使转化反应具有更大趋势。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_18","mother_id":"M5R_H2_KSP_18","skill_id":"H2_KSP","concept_key":"H2_KSP__common_ion_and_solubility","level":3,"grade_band":"高二","stem":"判断：向Mg(OH)₂悬浊液中加酸会抑制其溶解。","options":["正确","错误"],"correct_option":1,"explanation":"错误。H⁺消耗OH⁻，使溶解平衡向右移动，促进溶解。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_19","mother_id":"M5R_H2_KSP_19","skill_id":"H2_KSP","concept_key":"H2_KSP__common_ion_and_solubility","level":3,"grade_band":"高二","stem":"判断：向Mg(OH)₂悬浊液中加NaOH会促进其溶解。","options":["正确","错误"],"correct_option":1,"explanation":"错误。OH⁻为共同离子，使溶解平衡左移。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_20","mother_id":"M5R_H2_KSP_20","skill_id":"H2_KSP","concept_key":"H2_KSP__dissolution_equilibrium_expression","level":3,"grade_band":"高二","stem":"判断：改变溶液体积但温度不变时，Ksp数值不变。","options":["正确","错误"],"correct_option":0,"explanation":"正确。体积改变可使平衡移动，但平衡常数不变。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_21","mother_id":"M5R_H2_KSP_21","skill_id":"H2_KSP","concept_key":"H2_KSP__ion_product_and_precipitation","level":3,"grade_band":"高二","stem":"判断：计算Qsp时，应使用混合或反应后瞬间相关离子的实际浓度。","options":["正确","错误"],"correct_option":0,"explanation":"正确。先考虑体积变化和已发生的强反应，再与Ksp比较。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_22","mother_id":"M5R_H2_KSP_22","skill_id":"H2_KSP","concept_key":"H2_KSP__precipitation_conversion_and_separation","level":3,"grade_band":"高二","stem":"判断：两溶液等体积混合后，各离子浓度仍等于混合前浓度。","options":["正确","错误"],"correct_option":1,"explanation":"错误。若不反应，等体积混合也会使各自浓度先减半。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_23","mother_id":"M5R_H2_KSP_23","skill_id":"H2_KSP","concept_key":"H2_KSP__precipitation_conversion_and_separation","level":3,"grade_band":"高二","stem":"判断：选择性沉淀要求控制沉淀剂浓度，使一种离子先沉淀而另一种尽量留在溶液中。","options":["正确","错误"],"correct_option":0,"explanation":"正确。需比较各沉淀开始形成所需的临界离子浓度。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_24","mother_id":"M5R_H2_KSP_24","skill_id":"H2_KSP","concept_key":"H2_KSP__common_ion_and_solubility","level":3,"grade_band":"高二","stem":"判断：Ksp越小的物质在任何溶液中的溶解度都一定越小。","options":["正确","错误"],"correct_option":1,"explanation":"错误。溶解度还受离子计量、共同离子、酸碱反应和配位等环境影响。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_KSP_25","mother_id":"M5R_H2_KSP_25","skill_id":"H2_KSP","concept_key":"H2_KSP__ion_product_and_precipitation","level":3,"grade_band":"高二","stem":"判断：等体积1.0×10⁻⁴ mol·L⁻¹ AgNO₃与NaCl溶液混合后，若Ksp(AgCl)=1.8×10⁻¹⁰，则会生成AgCl沉淀。","options":["正确","错误"],"correct_option":0,"explanation":"正确。混合后两离子浓度均为5.0×10⁻⁵ mol·L⁻¹，Qsp=2.5×10⁻⁹>Ksp。","scaffold":"写溶解平衡并计算Qsp，再与Ksp比较。"},{"id":"Q5R_H2_PH_HYDRO_01","mother_id":"M5R_H2_PH_HYDRO_01","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__water_ion_product_and_neutrality","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.25 ℃时水的离子积Kw=c(H⁺)c(OH⁻)=1.0×10⁻¹⁴。 Ⅱ.Kw只与温度有关，25 ℃常用值为1.0×10⁻¹⁴。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。Kw只与温度有关，25 ℃常用值为1.0×10⁻¹⁴。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_02","mother_id":"M5R_H2_PH_HYDRO_02","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__water_ion_product_and_neutrality","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.任何温度下中性水溶液的pH都等于7。 Ⅱ.中性条件是c(H⁺)=c(OH⁻)，pH=7只对应25 ℃的常用情形。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。中性条件是c(H⁺)=c(OH⁻)，pH=7只对应25 ℃的常用情形。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_03","mother_id":"M5R_H2_PH_HYDRO_03","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__ph_calculation","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.25 ℃时c(H⁺)=1.0×10⁻³ mol·L⁻¹的溶液pH=3。 Ⅱ.pH=−lg c(H⁺)=3。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。pH=−lg c(H⁺)=3。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_04","mother_id":"M5R_H2_PH_HYDRO_04","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__ph_calculation","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.25 ℃时pH=11的溶液中c(OH⁻)=1.0×10⁻¹¹ mol·L⁻¹。 Ⅱ.pOH=14−11=3，所以c(OH⁻)=1.0×10⁻³ mol·L⁻¹。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。pOH=14−11=3，所以c(OH⁻)=1.0×10⁻³ mol·L⁻¹。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_05","mother_id":"M5R_H2_PH_HYDRO_05","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__water_ion_product_and_neutrality","level":1,"grade_band":"高二","stem":"判断：酸性溶液中不存在OH⁻。","options":["正确","错误"],"correct_option":1,"explanation":"错误。水的电离使任何水溶液中都同时存在H⁺和OH⁻，只是浓度大小不同。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_06","mother_id":"M5R_H2_PH_HYDRO_06","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__acid_base_titration_indicator","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.25 ℃时用0.100 mol·L⁻¹ HCl滴定等物质的量NaOH，恰好完全反应时溶液pH约为7。 Ⅱ.强酸强碱恰好中和后主要含NaCl和水，25 ℃时溶液近中性。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。强酸强碱恰好中和后主要含NaCl和水，25 ℃时溶液近中性。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_07","mother_id":"M5R_H2_PH_HYDRO_07","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__ph_calculation","level":2,"grade_band":"高二","stem":"判断：将pH=2的强酸溶液等体积稀释10倍后，pH一定变为12。","options":["正确","错误"],"correct_option":1,"explanation":"错误。稀释酸使pH增大；在常规范围内约增大1，不会变为碱性12。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_08","mother_id":"M5R_H2_PH_HYDRO_08","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__ph_calculation","level":2,"grade_band":"高二","stem":"判断：两种强酸溶液混合求pH时，应先求H⁺总物质的量再除以总体积。","options":["正确","错误"],"correct_option":0,"explanation":"正确。先按物质的量守恒合并，再换算混合后浓度。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_09","mother_id":"M5R_H2_PH_HYDRO_09","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__ph_calculation","level":2,"grade_band":"高二","stem":"判断：强酸与强碱混合求pH时，可直接把两个pH数值相减。","options":["正确","错误"],"correct_option":1,"explanation":"错误。必须先由pH换算H⁺、OH⁻物质的量，反应后再求剩余量。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_10","mother_id":"M5R_H2_PH_HYDRO_10","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__salt_hydrolysis_acidity","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.NaCl是强酸强碱盐，其水溶液在25 ℃时通常近中性。 Ⅱ.Na⁺和Cl⁻均不发生明显水解。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。Na⁺和Cl⁻均不发生明显水解。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_11","mother_id":"M5R_H2_PH_HYDRO_11","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__salt_hydrolysis_acidity","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.NH₄Cl水溶液通常呈酸性。 Ⅱ.NH₄⁺水解生成H⁺，Cl⁻基本不水解。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。NH₄⁺水解生成H⁺，Cl⁻基本不水解。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_12","mother_id":"M5R_H2_PH_HYDRO_12","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__salt_hydrolysis_acidity","level":2,"grade_band":"高二","stem":"判断：CH₃COONa水溶液通常呈酸性。","options":["正确","错误"],"correct_option":1,"explanation":"错误。CH₃COO⁻水解生成OH⁻，溶液通常呈碱性。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_13","mother_id":"M5R_H2_PH_HYDRO_13","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__salt_hydrolysis_acidity","level":2,"grade_band":"高二","stem":"判断：AlCl₃水溶液可因Al³⁺水解而呈酸性。","options":["正确","错误"],"correct_option":0,"explanation":"正确。高电荷小半径金属离子水解可释放H⁺。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_14","mother_id":"M5R_H2_PH_HYDRO_14","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__solution_conservation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.NaCl溶液的电荷守恒式可写为c(Na⁺)+c(H⁺)=c(Cl⁻)+c(OH⁻)。 Ⅱ.溶液中总正电荷浓度必须等于总负电荷浓度。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。溶液中总正电荷浓度必须等于总负电荷浓度。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_15","mother_id":"M5R_H2_PH_HYDRO_15","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__solution_conservation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.0.10 mol·L⁻¹ Na₂CO₃溶液中，含碳粒子的物料守恒为c(CO₃²⁻)+c(HCO₃⁻)+c(H₂CO₃)=0.10 mol·L⁻¹。 Ⅱ.一个Na₂CO₃化学式单位只提供一个碳，各含碳形态浓度之和等于分析浓度。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。一个Na₂CO₃化学式单位只提供一个碳，各含碳形态浓度之和等于分析浓度。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_16","mother_id":"M5R_H2_PH_HYDRO_16","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__solution_conservation","level":2,"grade_band":"高二","stem":"判断：CH₃COONa溶液中可写物料守恒c(CH₃COOH)+c(CH₃COO⁻)=c(Na⁺)。","options":["正确","错误"],"correct_option":0,"explanation":"正确。醋酸根虽可水解，但含乙酸根骨架的总量与Na⁺投料量相等。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_17","mother_id":"M5R_H2_PH_HYDRO_17","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__water_ion_product_and_neutrality","level":3,"grade_band":"高二","stem":"判断：加热纯水时若Kw增大，中性水的pH可小于7。","options":["正确","错误"],"correct_option":0,"explanation":"正确。中性仍满足c(H⁺)=c(OH⁻)，但二者都增大，pH相应降低。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_18","mother_id":"M5R_H2_PH_HYDRO_18","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__water_ion_product_and_neutrality","level":3,"grade_band":"高二","stem":"判断：中性溶液一定满足c(H⁺)=1.0×10⁻⁷ mol·L⁻¹。","options":["正确","错误"],"correct_option":1,"explanation":"错误。该数值只适用于25 ℃；中性的本质是c(H⁺)=c(OH⁻)。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_19","mother_id":"M5R_H2_PH_HYDRO_19","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__solution_conservation","level":3,"grade_band":"高二","stem":"判断：电荷守恒式中各种离子浓度需乘以所带电荷数。","options":["正确","错误"],"correct_option":0,"explanation":"正确。溶液总正电荷浓度等于总负电荷浓度。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_20","mother_id":"M5R_H2_PH_HYDRO_20","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__solution_conservation","level":3,"grade_band":"高二","stem":"判断：Na₂CO₃溶液的电荷守恒可忽略CO₃²⁻前的系数2。","options":["正确","错误"],"correct_option":1,"explanation":"错误。一个CO₃²⁻带两个单位负电荷，必须写2c(CO₃²⁻)。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_21","mother_id":"M5R_H2_PH_HYDRO_21","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__acid_base_titration_indicator","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.强酸滴定弱碱的等量点通常显酸性。 Ⅱ.等量点主要含弱碱的共轭酸，该离子水解生成H⁺。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。等量点主要含弱碱的共轭酸，该离子水解生成H⁺。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_22","mother_id":"M5R_H2_PH_HYDRO_22","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__acid_base_titration_indicator","level":3,"grade_band":"高二","stem":"判断：酸碱指示剂的变色范围通常是一个pH区间，而不是单一数值。","options":["正确","错误"],"correct_option":0,"explanation":"正确。指示剂两种颜色形式的比例在一定pH范围内逐渐变化。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_23","mother_id":"M5R_H2_PH_HYDRO_23","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__acid_base_titration_indicator","level":3,"grade_band":"高二","stem":"判断：酚酞适合用来指示所有强酸滴定弱碱的终点。","options":["正确","错误"],"correct_option":1,"explanation":"错误。终点附近pH和指示剂变色范围必须匹配，不能机械选用。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_24","mother_id":"M5R_H2_PH_HYDRO_24","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__acid_base_titration_indicator","level":3,"grade_band":"高二","stem":"判断：25 ℃时用NaOH滴定HCl，可选择酚酞作为终点指示剂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。强酸强碱滴定的pH突跃范围较宽，包含酚酞的变色范围。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_PH_HYDRO_25","mother_id":"M5R_H2_PH_HYDRO_25","skill_id":"H2_PH_HYDRO","concept_key":"H2_PH_HYDRO__salt_hydrolysis_acidity","level":3,"grade_band":"高二","stem":"判断：同为0.10 mol·L⁻¹时，NH₄Cl溶液通常显酸性，而NaCl溶液通常接近中性。","options":["正确","错误"],"correct_option":0,"explanation":"正确。NH₄⁺会水解生成H⁺，Na⁺和Cl⁻均不发生明显水解。","scaffold":"先列溶液粒子，再用Kw、水解和守恒关系判断。"},{"id":"Q5R_H2_RATE_01","mother_id":"M5R_H2_RATE_01","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_definition_and_stoichiometry","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.化学反应速率可用单位时间内反应物浓度的减少量或生成物浓度的增加量表示。 Ⅱ.平均速率本质上是浓度变化量与时间间隔之比。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。平均速率本质上是浓度变化量与时间间隔之比。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_02","mother_id":"M5R_H2_RATE_02","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_definition_and_stoichiometry","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.用反应物浓度表示反应速率时，可直接写成Δc/Δt而不考虑正负。 Ⅱ.反应物浓度减少，通常加负号或取减少量的正值以保证速率为正。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。反应物浓度减少，通常加负号或取减少量的正值以保证速率为正。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_03","mother_id":"M5R_H2_RATE_03","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_definition_and_stoichiometry","level":1,"grade_band":"高二","stem":"判断：化学反应速率的常用单位之一是mol·L⁻¹·s⁻¹。","options":["正确","错误"],"correct_option":0,"explanation":"正确。浓度单位除以时间单位即可得到该速率单位。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_04","mother_id":"M5R_H2_RATE_04","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_definition_and_stoichiometry","level":1,"grade_band":"高二","stem":"判断：同一反应中，用不同物质表示的反应速率数值一定相等。","options":["正确","错误"],"correct_option":1,"explanation":"错误。未经化学计量数归一化时，各物质速率之比等于相应系数之比。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_05","mother_id":"M5R_H2_RATE_05","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_definition_and_stoichiometry","level":1,"grade_band":"高二","stem":"判断：对反应2A→B，若v(A)=0.20 mol·L⁻¹·s⁻¹，则v(B)=0.10 mol·L⁻¹·s⁻¹。","options":["正确","错误"],"correct_option":0,"explanation":"正确。A的消耗速率与B的生成速率之比为2∶1。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_06","mother_id":"M5R_H2_RATE_06","skill_id":"H2_RATE","concept_key":"H2_RATE__concentration_and_pressure_factor","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.一定条件下增大反应物浓度，通常能增大反应速率。 Ⅱ.单位体积内反应物粒子数增多，有效碰撞次数通常增加。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。单位体积内反应物粒子数增多，有效碰撞次数通常增加。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_07","mother_id":"M5R_H2_RATE_07","skill_id":"H2_RATE","concept_key":"H2_RATE__concentration_and_pressure_factor","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.对于有气体参加的反应，恒温压缩容器通常会增大反应速率。 Ⅱ.体积减小使气体浓度增大，碰撞频率提高。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。体积减小使气体浓度增大，碰撞频率提高。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_08","mother_id":"M5R_H2_RATE_08","skill_id":"H2_RATE","concept_key":"H2_RATE__concentration_and_pressure_factor","level":2,"grade_band":"高二","stem":"判断：恒温恒容条件下加入不参加反应的惰性气体，会增大原反应各气体浓度。","options":["正确","错误"],"correct_option":1,"explanation":"错误。容积不变时反应气体的物质的量和浓度均不变。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_09","mother_id":"M5R_H2_RATE_09","skill_id":"H2_RATE","concept_key":"H2_RATE__temperature_and_catalyst","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.升高温度通常会增大反应速率。 Ⅱ.升温既提高碰撞频率，也显著增大能量达到活化能的粒子比例。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。升温既提高碰撞频率，也显著增大能量达到活化能的粒子比例。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_10","mother_id":"M5R_H2_RATE_10","skill_id":"H2_RATE","concept_key":"H2_RATE__temperature_and_catalyst","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.温度升高后，所有分子碰撞都会成为有效碰撞。 Ⅱ.碰撞仍需满足足够能量和合适取向，只有一部分是有效碰撞。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。碰撞仍需满足足够能量和合适取向，只有一部分是有效碰撞。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_11","mother_id":"M5R_H2_RATE_11","skill_id":"H2_RATE","concept_key":"H2_RATE__temperature_and_catalyst","level":2,"grade_band":"高二","stem":"判断：催化剂通过降低反应的活化能来加快速率。","options":["正确","错误"],"correct_option":0,"explanation":"正确。催化剂提供另一条能垒较低的反应路径。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_12","mother_id":"M5R_H2_RATE_12","skill_id":"H2_RATE","concept_key":"H2_RATE__temperature_and_catalyst","level":2,"grade_band":"高二","stem":"判断：催化剂能提高活化分子的百分数，但不改变反应热。","options":["正确","错误"],"correct_option":0,"explanation":"正确。降低活化能使更多粒子达到反应门槛，始末状态不变。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_13","mother_id":"M5R_H2_RATE_13","skill_id":"H2_RATE","concept_key":"H2_RATE__temperature_and_catalyst","level":2,"grade_band":"高二","stem":"判断：催化剂一定能使所有反应都明显加快。","options":["正确","错误"],"correct_option":1,"explanation":"错误。催化剂有选择性，且需与具体反应、条件相匹配。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_14","mother_id":"M5R_H2_RATE_14","skill_id":"H2_RATE","concept_key":"H2_RATE__experimental_factor_comparison","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.块状CaCO₃与同质量粉末状CaCO₃分别和同浓度盐酸反应，粉末状反应通常更快。 Ⅱ.粉末的接触面积更大，单位时间有效碰撞更多。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。粉末的接触面积更大，单位时间有效碰撞更多。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_15","mother_id":"M5R_H2_RATE_15","skill_id":"H2_RATE","concept_key":"H2_RATE__experimental_factor_comparison","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.增大固体反应物质量而保持表面积完全不变，初始反应速率一定增大。 Ⅱ.多出的固体若未增加有效接触面积，初始速率可能不变。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。多出的固体若未增加有效接触面积，初始速率可能不变。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_16","mother_id":"M5R_H2_RATE_16","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_graph_and_kinetic_meaning","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.反应物浓度—时间图像上某时刻切线斜率的绝对值可反映瞬时速率。 Ⅱ.切线斜率对应该时刻浓度变化率。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。切线斜率对应该时刻浓度变化率。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_17","mother_id":"M5R_H2_RATE_17","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_graph_and_kinetic_meaning","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.一段时间内算得的平均速率等于该时间段每一时刻的瞬时速率。 Ⅱ.速率常随浓度变化，平均值不能代表每一时刻。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。速率常随浓度变化，平均值不能代表每一时刻。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_18","mother_id":"M5R_H2_RATE_18","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_graph_and_kinetic_meaning","level":3,"grade_band":"高二","stem":"判断：可逆反应达到化学平衡后，正、逆反应速率都变为0。","options":["正确","错误"],"correct_option":1,"explanation":"错误。平衡是动态平衡，正、逆反应仍进行且速率相等。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_19","mother_id":"M5R_H2_RATE_19","skill_id":"H2_RATE","concept_key":"H2_RATE__concentration_and_pressure_factor","level":3,"grade_band":"高二","stem":"判断：反应开始后反应物浓度通常降低，因此反应速率往往逐渐减小。","options":["正确","错误"],"correct_option":0,"explanation":"正确。其他条件不变时，浓度下降使碰撞频率降低。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_20","mother_id":"M5R_H2_RATE_20","skill_id":"H2_RATE","concept_key":"H2_RATE__experimental_factor_comparison","level":3,"grade_band":"高二","stem":"判断：向一定浓度盐酸中加水稀释后，与锌反应的初始速率通常减小。","options":["正确","错误"],"correct_option":0,"explanation":"正确。稀释使H⁺浓度降低。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_21","mother_id":"M5R_H2_RATE_21","skill_id":"H2_RATE","concept_key":"H2_RATE__experimental_factor_comparison","level":3,"grade_band":"高二","stem":"判断：光照可能影响某些光化学反应的速率。","options":["正确","错误"],"correct_option":0,"explanation":"正确。光可为特定反应提供能量或产生反应活性粒子。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_22","mother_id":"M5R_H2_RATE_22","skill_id":"H2_RATE","concept_key":"H2_RATE__experimental_factor_comparison","level":3,"grade_band":"高二","stem":"判断：增加催化剂用量后，反应速率必然无限增大。","options":["正确","错误"],"correct_option":1,"explanation":"错误。速率还受反应物供给、催化表面利用等限制，不会无限增长。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_23","mother_id":"M5R_H2_RATE_23","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_graph_and_kinetic_meaning","level":3,"grade_band":"高二","stem":"判断：有效碰撞必须同时满足能量条件和适当取向。","options":["正确","错误"],"correct_option":0,"explanation":"正确。只有能导致旧键断裂、新键形成的碰撞才有效。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_24","mother_id":"M5R_H2_RATE_24","skill_id":"H2_RATE","concept_key":"H2_RATE__rate_graph_and_kinetic_meaning","level":3,"grade_band":"高二","stem":"判断：反应速率越大，反应物的平衡转化率一定越高。","options":["正确","错误"],"correct_option":1,"explanation":"错误。速率决定达到平衡的快慢，平衡转化率由平衡条件决定。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_RATE_25","mother_id":"M5R_H2_RATE_25","skill_id":"H2_RATE","concept_key":"H2_RATE__concentration_and_pressure_factor","level":3,"grade_band":"高二","stem":"判断：用等质量、表面积相近的Mg片分别与等体积0.50 mol·L⁻¹和1.00 mol·L⁻¹盐酸反应，后者开始时放出H₂更快。","options":["正确","错误"],"correct_option":0,"explanation":"正确。金属条件相近时，盐酸浓度更大使有效碰撞频率更高，初始速率更大。","scaffold":"只比较被改变的条件，并从浓度、碰撞或活化能解释。"},{"id":"Q5R_H2_THERMO_01","mother_id":"M5R_H2_THERMO_01","skill_id":"H2_THERMO","concept_key":"H2_THERMO__enthalpy_definition_and_sign","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.反应焓变可表示为ΔH=H(生成物)−H(反应物)。 Ⅱ.焓变按终态减始态计算，生成物是终态、反应物是始态。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。焓变按终态减始态计算，生成物是终态、反应物是始态。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_02","mother_id":"M5R_H2_THERMO_02","skill_id":"H2_THERMO","concept_key":"H2_THERMO__enthalpy_definition_and_sign","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.放热反应的ΔH大于0。 Ⅱ.放热时体系焓降低，H(生成物)<H(反应物)，所以ΔH<0。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。放热时体系焓降低，H(生成物)<H(反应物)，所以ΔH<0。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_03","mother_id":"M5R_H2_THERMO_03","skill_id":"H2_THERMO","concept_key":"H2_THERMO__enthalpy_definition_and_sign","level":1,"grade_band":"高二","stem":"判断：吸热反应的生成物总焓通常高于反应物总焓。","options":["正确","错误"],"correct_option":0,"explanation":"正确。吸热反应ΔH>0，因此终态焓高于始态焓。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_04","mother_id":"M5R_H2_THERMO_04","skill_id":"H2_THERMO","concept_key":"H2_THERMO__reaction_heat_calculation","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.断裂化学键会释放能量。 Ⅱ.断键需要吸收能量，形成化学键才释放能量。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。断键需要吸收能量，形成化学键才释放能量。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_05","mother_id":"M5R_H2_THERMO_05","skill_id":"H2_THERMO","concept_key":"H2_THERMO__reaction_heat_calculation","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.形成化学键通常会释放能量。 Ⅱ.成键后体系能量降低，能量以热等形式释放。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。成键后体系能量降低，能量以热等形式释放。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_06","mother_id":"M5R_H2_THERMO_06","skill_id":"H2_THERMO","concept_key":"H2_THERMO__reaction_heat_calculation","level":1,"grade_band":"高二","stem":"判断：用键能估算反应焓变时，可用ΔH≈反应物断键吸收能量之和−生成物成键释放能量之和。","options":["正确","错误"],"correct_option":0,"explanation":"正确。计算顺序是断键吸能减去成键放能的绝对数值。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_07","mother_id":"M5R_H2_THERMO_07","skill_id":"H2_THERMO","concept_key":"H2_THERMO__catalyst_and_activation_energy","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.催化剂能降低反应焓变ΔH。 Ⅱ.催化剂改变反应路径和活化能，但始态、终态不变，ΔH不变。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。催化剂改变反应路径和活化能，但始态、终态不变，ΔH不变。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_08","mother_id":"M5R_H2_THERMO_08","skill_id":"H2_THERMO","concept_key":"H2_THERMO__catalyst_and_activation_energy","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.催化剂通常同时降低正、逆反应的活化能。 Ⅱ.同一催化路径对正、逆反应都提供较低能垒。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。同一催化路径对正、逆反应都提供较低能垒。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_09","mother_id":"M5R_H2_THERMO_09","skill_id":"H2_THERMO","concept_key":"H2_THERMO__thermochemical_equation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.将热化学方程式反向书写时，ΔH的符号应改变。 Ⅱ.始态与终态互换，终态减始态的结果变号。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。始态与终态互换，终态减始态的结果变号。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_10","mother_id":"M5R_H2_THERMO_10","skill_id":"H2_THERMO","concept_key":"H2_THERMO__thermochemical_equation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.热化学方程式的各物质系数扩大2倍时，ΔH保持不变。 Ⅱ.焓变与方程式所表示的反应进度对应，系数扩大2倍，ΔH也扩大2倍。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。焓变与方程式所表示的反应进度对应，系数扩大2倍，ΔH也扩大2倍。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_11","mother_id":"M5R_H2_THERMO_11","skill_id":"H2_THERMO","concept_key":"H2_THERMO__thermochemical_equation","level":2,"grade_band":"高二","stem":"判断：热化学方程式中物质的聚集状态不会影响ΔH。","options":["正确","错误"],"correct_option":1,"explanation":"错误。同一物质不同状态的焓不同，书写热化学方程式必须标明状态。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_12","mother_id":"M5R_H2_THERMO_12","skill_id":"H2_THERMO","concept_key":"H2_THERMO__thermochemical_equation","level":2,"grade_band":"高二","stem":"判断：H₂(g)+1/2O₂(g)=H₂O(l)与生成H₂O(g)的反应焓变相同。","options":["正确","错误"],"correct_option":1,"explanation":"错误。液态水与气态水的焓不同，凝结过程还会放热。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_13","mother_id":"M5R_H2_THERMO_13","skill_id":"H2_THERMO","concept_key":"H2_THERMO__hess_law_and_enthalpy_interpretation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.盖斯定律成立的依据是反应焓变只由始态和终态决定。 Ⅱ.焓是状态函数，反应路径不同不改变总焓变。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。焓是状态函数，反应路径不同不改变总焓变。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_14","mother_id":"M5R_H2_THERMO_14","skill_id":"H2_THERMO","concept_key":"H2_THERMO__hess_law_and_enthalpy_interpretation","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.若目标反应由两个分步反应相加得到，则目标ΔH等于两个分步ΔH之和。 Ⅱ.方程式相加时相应焓变也按代数相加。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。方程式相加时相应焓变也按代数相加。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_15","mother_id":"M5R_H2_THERMO_15","skill_id":"H2_THERMO","concept_key":"H2_THERMO__hess_law_and_enthalpy_interpretation","level":2,"grade_band":"高二","stem":"判断：若某分步反应方程式乘以1/2，则该步ΔH也应乘以1/2。","options":["正确","错误"],"correct_option":0,"explanation":"正确。焓变与热化学方程式表示的物质的量成比例。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_16","mother_id":"M5R_H2_THERMO_16","skill_id":"H2_THERMO","concept_key":"H2_THERMO__enthalpy_definition_and_sign","level":2,"grade_band":"高二","stem":"判断：反应物总能量高于生成物总能量时，该反应一定吸热。","options":["正确","错误"],"correct_option":1,"explanation":"错误。终态能量更低，体系释放能量，反应应为放热。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_17","mother_id":"M5R_H2_THERMO_17","skill_id":"H2_THERMO","concept_key":"H2_THERMO__catalyst_and_activation_energy","level":3,"grade_band":"高二","stem":"判断：在能量—反应过程图中，峰值与反应物能量之差可表示正反应活化能。","options":["正确","错误"],"correct_option":0,"explanation":"正确。活化能是反应物达到过渡状态所需跨越的能垒。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_18","mother_id":"M5R_H2_THERMO_18","skill_id":"H2_THERMO","concept_key":"H2_THERMO__catalyst_and_activation_energy","level":3,"grade_band":"高二","stem":"判断：放热反应的正反应活化能一定为0。","options":["正确","错误"],"correct_option":1,"explanation":"错误。放热只说明始末能量差，正反应通常仍需跨越能垒。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_19","mother_id":"M5R_H2_THERMO_19","skill_id":"H2_THERMO","concept_key":"H2_THERMO__catalyst_and_activation_energy","level":3,"grade_band":"高二","stem":"判断：同一反应有催化剂时达到峰值所需能量较低，但反应物和生成物能量位置不变。","options":["正确","错误"],"correct_option":0,"explanation":"正确。催化剂只改变路径，不改变始态和终态。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_20","mother_id":"M5R_H2_THERMO_20","skill_id":"H2_THERMO","concept_key":"H2_THERMO__reaction_heat_calculation","level":3,"grade_band":"高二","stem":"判断：强酸与强碱稀溶液发生中和时，若都生成1 mol H₂O，焓变通常近似相同。","options":["正确","错误"],"correct_option":0,"explanation":"正确。其共同实质是H⁺(aq)+OH⁻(aq)=H₂O(l)。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_21","mother_id":"M5R_H2_THERMO_21","skill_id":"H2_THERMO","concept_key":"H2_THERMO__reaction_heat_calculation","level":3,"grade_band":"高二","stem":"判断：弱酸与强碱中和生成1 mol水的焓变一定与强酸强碱中和完全相同。","options":["正确","错误"],"correct_option":1,"explanation":"错误。弱酸电离需要能量，中和总焓变还包含弱酸电离过程。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_22","mother_id":"M5R_H2_THERMO_22","skill_id":"H2_THERMO","concept_key":"H2_THERMO__enthalpy_definition_and_sign","level":3,"grade_band":"高二","stem":"判断：燃烧反应都是放热反应，因此其ΔH通常小于0。","options":["正确","错误"],"correct_option":0,"explanation":"正确。完全燃烧生成稳定氧化物时体系通常释放能量。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_23","mother_id":"M5R_H2_THERMO_23","skill_id":"H2_THERMO","concept_key":"H2_THERMO__hess_law_and_enthalpy_interpretation","level":3,"grade_band":"高二","stem":"判断：由C(s,石墨)=C(s,金刚石)的ΔH>0可知金刚石的焓高于石墨。","options":["正确","错误"],"correct_option":0,"explanation":"正确。正向吸热说明终态金刚石的焓更高。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_24","mother_id":"M5R_H2_THERMO_24","skill_id":"H2_THERMO","concept_key":"H2_THERMO__thermochemical_equation","level":3,"grade_band":"高二","stem":"判断：比较两个热化学方程式的ΔH数值时，可以忽略方程式系数和物质状态。","options":["正确","错误"],"correct_option":1,"explanation":"错误。必须先统一反应物、生成物、系数和聚集状态后才可比较。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_THERMO_25","mother_id":"M5R_H2_THERMO_25","skill_id":"H2_THERMO","concept_key":"H2_THERMO__hess_law_and_enthalpy_interpretation","level":3,"grade_band":"高二","stem":"判断：ΔH的正负反映体系吸放热方向，不等同于反应速率快慢。","options":["正确","错误"],"correct_option":0,"explanation":"正确。热效应属于热力学量，速率由活化能、温度等动力学因素决定。","scaffold":"区分始态、终态、反应路径，注意方程式倍乘和物态。"},{"id":"Q5R_H2_WEAK_01","mother_id":"M5R_H2_WEAK_01","skill_id":"H2_WEAK","concept_key":"H2_WEAK__weak_electrolyte_definition","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.弱电解质在水溶液中只发生部分电离。 Ⅱ.弱电解质分子与离子之间建立动态电离平衡。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。弱电解质分子与离子之间建立动态电离平衡。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_02","mother_id":"M5R_H2_WEAK_02","skill_id":"H2_WEAK","concept_key":"H2_WEAK__weak_electrolyte_definition","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.弱电解质溶液中不存在未电离的溶质分子。 Ⅱ.部分电离意味着溶液中同时存在分子和相应离子。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。部分电离意味着溶液中同时存在分子和相应离子。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_03","mother_id":"M5R_H2_WEAK_03","skill_id":"H2_WEAK","concept_key":"H2_WEAK__weak_electrolyte_definition","level":1,"grade_band":"高二","stem":"判断：CH₃COOH(aq)⇌H⁺(aq)+CH₃COO⁻(aq)应使用可逆符号。","options":["正确","错误"],"correct_option":0,"explanation":"正确。醋酸是弱酸，只部分电离。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_04","mother_id":"M5R_H2_WEAK_04","skill_id":"H2_WEAK","concept_key":"H2_WEAK__weak_electrolyte_definition","level":1,"grade_band":"高二","stem":"判断：强电解质与弱电解质的区别在于溶解度大小。","options":["正确","错误"],"correct_option":1,"explanation":"错误。强弱依据电离程度，溶解度是另一性质。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_05","mother_id":"M5R_H2_WEAK_05","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_constant","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.同温下电离常数Ka越大，通常表示该弱酸越强。 Ⅱ.Ka越大说明平衡更偏向离子一侧。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。Ka越大说明平衡更偏向离子一侧。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_06","mother_id":"M5R_H2_WEAK_06","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_constant","level":1,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.同一弱酸的Ka随其初始浓度改变。 Ⅱ.一定温度下Ka是该弱酸的平衡常数，不随初始浓度改变。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。一定温度下Ka是该弱酸的平衡常数，不随初始浓度改变。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_07","mother_id":"M5R_H2_WEAK_07","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_constant","level":2,"grade_band":"高二","stem":"判断：升高温度时弱酸的Ka一定不变。","options":["正确","错误"],"correct_option":1,"explanation":"错误。平衡常数随温度改变，具体增减取决于电离热效应。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_08","mother_id":"M5R_H2_WEAK_08","skill_id":"H2_WEAK","concept_key":"H2_WEAK__dilution_and_common_ion","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.稀释弱酸溶液通常会增大其电离程度。 Ⅱ.稀释使电离平衡向粒子数较多的离子一侧移动。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。稀释使电离平衡向粒子数较多的离子一侧移动。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_09","mother_id":"M5R_H2_WEAK_09","skill_id":"H2_WEAK","concept_key":"H2_WEAK__dilution_and_common_ion","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.稀释醋酸溶液时，醋酸电离程度增大，所以c(H⁺)一定增大。 Ⅱ.电离程度虽增大，但总体被稀释，c(H⁺)通常减小。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。电离程度虽增大，但总体被稀释，c(H⁺)通常减小。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_10","mother_id":"M5R_H2_WEAK_10","skill_id":"H2_WEAK","concept_key":"H2_WEAK__dilution_and_common_ion","level":2,"grade_band":"高二","stem":"判断：向醋酸溶液中加入少量醋酸钠，会抑制醋酸电离。","options":["正确","错误"],"correct_option":0,"explanation":"正确。CH₃COO⁻是同离子，使电离平衡向左移动。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_11","mother_id":"M5R_H2_WEAK_11","skill_id":"H2_WEAK","concept_key":"H2_WEAK__dilution_and_common_ion","level":2,"grade_band":"高二","stem":"判断：向氨水中加入少量NH₄Cl，会促进一水合氨电离。","options":["正确","错误"],"correct_option":1,"explanation":"错误。NH₄⁺是同离子，会使NH₃·H₂O电离平衡向左移动。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_12","mother_id":"M5R_H2_WEAK_12","skill_id":"H2_WEAK","concept_key":"H2_WEAK__dilution_and_common_ion","level":2,"grade_band":"高二","stem":"判断：向弱酸溶液中加入少量强碱，消耗H⁺后会促进弱酸继续电离。","options":["正确","错误"],"correct_option":0,"explanation":"正确。移去电离产物H⁺使平衡向右移动。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_13","mother_id":"M5R_H2_WEAK_13","skill_id":"H2_WEAK","concept_key":"H2_WEAK__acid_strength_ph_and_conductivity","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.同浓度的一元强酸与一元弱酸相比，强酸的c(H⁺)通常更大。 Ⅱ.强酸近乎完全电离，弱酸只部分电离。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。强酸近乎完全电离，弱酸只部分电离。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_14","mother_id":"M5R_H2_WEAK_14","skill_id":"H2_WEAK","concept_key":"H2_WEAK__acid_strength_ph_and_conductivity","level":2,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.pH相同的一元强酸与一元弱酸溶液中，酸的总浓度一定相同。 Ⅱ.弱酸只部分电离，要达到相同c(H⁺)通常需要更高总浓度。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。弱酸只部分电离，要达到相同c(H⁺)通常需要更高总浓度。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_15","mother_id":"M5R_H2_WEAK_15","skill_id":"H2_WEAK","concept_key":"H2_WEAK__acid_strength_ph_and_conductivity","level":2,"grade_band":"高二","stem":"判断：相同浓度的CH₃COOH和HCl溶液，前者导电能力一定更强。","options":["正确","错误"],"correct_option":1,"explanation":"错误。醋酸部分电离，自由离子浓度通常较小，导电能力较弱。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_16","mother_id":"M5R_H2_WEAK_16","skill_id":"H2_WEAK","concept_key":"H2_WEAK__acid_strength_ph_and_conductivity","level":2,"grade_band":"高二","stem":"判断：溶液导电性强弱只由电解质强弱决定。","options":["正确","错误"],"correct_option":1,"explanation":"错误。还与离子浓度、离子电荷和迁移能力等有关。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_17","mother_id":"M5R_H2_WEAK_17","skill_id":"H2_WEAK","concept_key":"H2_WEAK__weak_electrolyte_definition","level":3,"grade_band":"高二","stem":"判断：NH₃·H₂O属于弱电解质。","options":["正确","错误"],"correct_option":0,"explanation":"正确。它在水中只部分电离产生NH₄⁺和OH⁻。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_18","mother_id":"M5R_H2_WEAK_18","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_equilibrium_composition","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.水是极弱电解质，能发生微弱的自偶电离。 Ⅱ.纯水中存在H⁺和OH⁻的动态平衡。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。纯水中存在H⁺和OH⁻的动态平衡。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_19","mother_id":"M5R_H2_WEAK_19","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_constant","level":3,"grade_band":"高二","stem":"判断：电离平衡移动后，电离常数一定改变。","options":["正确","错误"],"correct_option":1,"explanation":"错误。温度不变时，浓度改变可使平衡移动但K不变。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_20","mother_id":"M5R_H2_WEAK_20","skill_id":"H2_WEAK","concept_key":"H2_WEAK__acid_strength_ph_and_conductivity","level":3,"grade_band":"高二","stem":"判断：弱酸溶液中c(H⁺)等于该弱酸的初始浓度。","options":["正确","错误"],"correct_option":1,"explanation":"错误。弱酸只部分电离，且还需考虑水的电离等，不能直接相等。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_21","mother_id":"M5R_H2_WEAK_21","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_equilibrium_composition","level":3,"grade_band":"高二","stem":"组合判断：判断下列两项：Ⅰ.对于一元弱酸HA，忽略水的电离时，平衡产生的c(H⁺)与c(A⁻)相等。 Ⅱ.HA每电离1 mol同时生成1 mol H⁺和1 mol A⁻。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。HA每电离1 mol同时生成1 mol H⁺和1 mol A⁻。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_22","mother_id":"M5R_H2_WEAK_22","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_equilibrium_composition","level":3,"grade_band":"高二","stem":"判断：弱酸的电离度可表示为已电离的弱酸量与初始弱酸量之比。","options":["正确","错误"],"correct_option":0,"explanation":"正确。电离度反映一定条件下弱电解质电离的比例。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_23","mother_id":"M5R_H2_WEAK_23","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_equilibrium_composition","level":3,"grade_band":"高二","stem":"判断：在同一弱酸溶液中加水，未电离分子数一定增加。","options":["正确","错误"],"correct_option":1,"explanation":"错误。稀释促进电离，未电离分子数可能减少；不能只凭体积增大判断。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_24","mother_id":"M5R_H2_WEAK_24","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_equilibrium_composition","level":3,"grade_band":"高二","stem":"判断：弱电解质电离达到平衡时，分子电离与离子结合的速率相等。","options":["正确","错误"],"correct_option":0,"explanation":"正确。微观过程继续进行但宏观组成不再变化。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H2_WEAK_25","mother_id":"M5R_H2_WEAK_25","skill_id":"H2_WEAK","concept_key":"H2_WEAK__ionization_constant","level":3,"grade_band":"高二","stem":"判断：25 ℃时Ka(HA)=1.0×10⁻⁴、Ka(HB)=1.0×10⁻⁶，则HA的酸性强于HB。","options":["正确","错误"],"correct_option":0,"explanation":"正确。同温下弱酸的Ka越大，电离倾向越大，酸性通常越强。","scaffold":"列出弱电解质分子和离子，追踪同离子或稀释影响。"},{"id":"Q5R_H3_AQ_01","mother_id":"M5R_H3_AQ_01","skill_id":"H3_AQ","concept_key":"H3_AQ__water_pH_and_acid_strength","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.某水溶液温度为25 ℃时，水的离子积满足Kw=c(H⁺)c(OH⁻)=1.0×10⁻¹⁴。 Ⅱ.Kw是水自偶电离的平衡常数在浓度近似下的表达。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。Kw是水自偶电离的平衡常数在浓度近似下的表达。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_02","mother_id":"M5R_H3_AQ_02","skill_id":"H3_AQ","concept_key":"H3_AQ__water_pH_and_acid_strength","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.中性水溶液在任何温度下都满足pH=7。 Ⅱ.中性本质是c(H⁺)=c(OH⁻)，pH=7只对应25 ℃常用条件。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。中性本质是c(H⁺)=c(OH⁻)，pH=7只对应25 ℃常用条件。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_03","mother_id":"M5R_H3_AQ_03","skill_id":"H3_AQ","concept_key":"H3_AQ__water_pH_and_acid_strength","level":2,"grade_band":"高三","stem":"判断：25 ℃时pH=3的溶液中c(H⁺)=1.0×10⁻³ mol·L⁻¹。","options":["正确","错误"],"correct_option":0,"explanation":"正确。由pH=−lg c(H⁺)得到。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_04","mother_id":"M5R_H3_AQ_04","skill_id":"H3_AQ","concept_key":"H3_AQ__water_pH_and_acid_strength","level":2,"grade_band":"高三","stem":"判断：两种强酸混合后可直接把两个pH相加得到混合液pH。","options":["正确","错误"],"correct_option":1,"explanation":"错误。应先换算H⁺物质的量，按总体积求浓度后再取负对数。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_05","mother_id":"M5R_H3_AQ_05","skill_id":"H3_AQ","concept_key":"H3_AQ__water_pH_and_acid_strength","level":2,"grade_band":"高三","stem":"判断：一定温度下Ka越大的弱酸通常酸性越强。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Ka反映弱酸电离平衡向离子侧进行的程度。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_06","mother_id":"M5R_H3_AQ_06","skill_id":"H3_AQ","concept_key":"H3_AQ__weak_electrolyte_and_hydrolysis","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.稀释弱酸会增大其电离度，同时c(H⁺)通常减小。 Ⅱ.电离程度与离子实际浓度的变化方向可以不同。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。电离程度与离子实际浓度的变化方向可以不同。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_07","mother_id":"M5R_H3_AQ_07","skill_id":"H3_AQ","concept_key":"H3_AQ__weak_electrolyte_and_hydrolysis","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.向醋酸溶液中加入醋酸钠会因同离子效应抑制醋酸电离。 Ⅱ.加入CH₃COO⁻使电离平衡左移。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。加入CH₃COO⁻使电离平衡左移。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_08","mother_id":"M5R_H3_AQ_08","skill_id":"H3_AQ","concept_key":"H3_AQ__weak_electrolyte_and_hydrolysis","level":3,"grade_band":"高三","stem":"判断：Na₂CO₃溶液呈碱性是因为Na⁺水解产生OH⁻。","options":["正确","错误"],"correct_option":1,"explanation":"错误。主要是CO₃²⁻水解生成OH⁻，Na⁺基本不水解。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_09","mother_id":"M5R_H3_AQ_09","skill_id":"H3_AQ","concept_key":"H3_AQ__weak_electrolyte_and_hydrolysis","level":3,"grade_band":"高三","stem":"判断：NH₄Cl溶液通常呈酸性，因为NH₄⁺发生水解。","options":["正确","错误"],"correct_option":0,"explanation":"正确。NH₄⁺与水反应产生H⁺。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_10","mother_id":"M5R_H3_AQ_10","skill_id":"H3_AQ","concept_key":"H3_AQ__weak_electrolyte_and_hydrolysis","level":3,"grade_band":"高三","stem":"判断：升高温度后Kw改变，但中性溶液始终满足c(H⁺)=c(OH⁻)。","options":["正确","错误"],"correct_option":0,"explanation":"正确。中性判断比较两种离子浓度，不固定为某一pH。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_11","mother_id":"M5R_H3_AQ_11","skill_id":"H3_AQ","concept_key":"H3_AQ__acid_base_titration","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.用标准NaOH滴定盐酸时，滴定管尖嘴内若有气泡且终点时气泡消失，会使记录的NaOH体积偏大。 Ⅱ.部分标准液用于填充尖嘴而未进入锥形瓶，却被计入读数差。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。部分标准液用于填充尖嘴而未进入锥形瓶，却被计入读数差。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_12","mother_id":"M5R_H3_AQ_12","skill_id":"H3_AQ","concept_key":"H3_AQ__acid_base_titration","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.用NaOH滴定醋酸时可选酚酞作指示剂，因为其变色范围可落在终点附近的碱性突跃区。 Ⅱ.弱酸强碱滴定等量点呈碱性，应选择合适变色范围。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。弱酸强碱滴定等量点呈碱性，应选择合适变色范围。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_13","mother_id":"M5R_H3_AQ_13","skill_id":"H3_AQ","concept_key":"H3_AQ__acid_base_titration","level":3,"grade_band":"高三","stem":"判断：强酸滴定一元弱碱的等量点溶液一定呈中性。","options":["正确","错误"],"correct_option":1,"explanation":"错误。等量点主要含弱碱对应的共轭酸，水解后通常呈酸性。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_14","mother_id":"M5R_H3_AQ_14","skill_id":"H3_AQ","concept_key":"H3_AQ__acid_base_titration","level":3,"grade_band":"高三","stem":"判断：强碱滴定一元弱酸的等量点溶液通常呈碱性。","options":["正确","错误"],"correct_option":0,"explanation":"正确。等量点主要含弱酸根，水解生成OH⁻。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_15","mother_id":"M5R_H3_AQ_15","skill_id":"H3_AQ","concept_key":"H3_AQ__acid_base_titration","level":3,"grade_band":"高三","stem":"判断：弱酸用强碱滴定至半中和点时，若适用近似条件，pH可等于pKa。","options":["正确","错误"],"correct_option":0,"explanation":"正确。此时弱酸分子与其共轭碱浓度相等，Ka关系给出c(H⁺)=Ka。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_16","mother_id":"M5R_H3_AQ_16","skill_id":"H3_AQ","concept_key":"H3_AQ__solubility_product","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.AgCl饱和溶液中加入少量NaCl固体，AgCl的溶解平衡左移。 Ⅱ.加入共同离子Cl⁻使离子积增大，体系通过析出或抑制溶解恢复平衡。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。加入共同离子Cl⁻使离子积增大，体系通过析出或抑制溶解恢复平衡。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_17","mother_id":"M5R_H3_AQ_17","skill_id":"H3_AQ","concept_key":"H3_AQ__solubility_product","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.AgCl饱和溶液中只要有固体存在，就满足c(Ag⁺)c(Cl⁻)=Ksp。 Ⅱ.溶解与沉淀达到动态平衡。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。溶解与沉淀达到动态平衡。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_18","mother_id":"M5R_H3_AQ_18","skill_id":"H3_AQ","concept_key":"H3_AQ__solubility_product","level":4,"grade_band":"高三","stem":"判断：离子积Qsp>Ksp时，体系有生成相应沉淀的趋势。","options":["正确","错误"],"correct_option":0,"explanation":"正确。沉淀析出使离子浓度降低，直至Qsp回到Ksp。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_19","mother_id":"M5R_H3_AQ_19","skill_id":"H3_AQ","concept_key":"H3_AQ__solubility_product","level":4,"grade_band":"高三","stem":"判断：加入共同离子通常会增大难溶电解质的溶解度。","options":["正确","错误"],"correct_option":1,"explanation":"错误。共同离子使溶解平衡左移，溶解度通常减小。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_20","mother_id":"M5R_H3_AQ_20","skill_id":"H3_AQ","concept_key":"H3_AQ__solubility_product","level":4,"grade_band":"高三","stem":"判断：沉淀达到平衡后，被沉淀离子的浓度一定为0。","options":["正确","错误"],"correct_option":1,"explanation":"错误。Ksp有限，平衡溶液中仍有残留离子。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_21","mother_id":"M5R_H3_AQ_21","skill_id":"H3_AQ","concept_key":"H3_AQ__neutralization_and_indicator","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.25 ℃时将10.0 mL 0.100 mol·L⁻¹ HCl与10.0 mL 0.100 mol·L⁻¹ NaOH混合，所得溶液近似中性。 Ⅱ.H⁺与OH⁻物质的量均为1.00×10⁻³ mol，恰好完全中和。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。H⁺与OH⁻物质的量均为1.00×10⁻³ mol，恰好完全中和。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_22","mother_id":"M5R_H3_AQ_22","skill_id":"H3_AQ","concept_key":"H3_AQ__neutralization_and_indicator","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.用0.100 mol·L⁻¹ HCl滴定等浓度NaOH时，滴加到一半等量体积时溶液仍呈碱性。 Ⅱ.此时OH⁻只被中和一半，锥形瓶中仍有过量OH⁻。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。此时OH⁻只被中和一半，锥形瓶中仍有过量OH⁻。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_23","mother_id":"M5R_H3_AQ_23","skill_id":"H3_AQ","concept_key":"H3_AQ__neutralization_and_indicator","level":4,"grade_band":"高三","stem":"判断：25 ℃时，将等体积pH=2的HCl溶液与pH=12的NaOH溶液混合，忽略混合体积变化，所得溶液近似呈中性。","options":["正确","错误"],"correct_option":0,"explanation":"正确。HCl和NaOH均按完全电离处理；两溶液中的c(H⁺)与c(OH⁻)都为1.0×10⁻² mol·L⁻¹，等体积时物质的量相等并恰好中和。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_24","mother_id":"M5R_H3_AQ_24","skill_id":"H3_AQ","concept_key":"H3_AQ__neutralization_and_indicator","level":4,"grade_band":"高三","stem":"判断：酸碱滴定选择指示剂时，应使其变色范围落在终点附近的pH突跃范围内。","options":["正确","错误"],"correct_option":0,"explanation":"正确。这样指示剂变色造成的终点误差较小。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_AQ_25","mother_id":"M5R_H3_AQ_25","skill_id":"H3_AQ","concept_key":"H3_AQ__neutralization_and_indicator","level":4,"grade_band":"高三","stem":"判断：用甲基橙指示NaOH滴定醋酸的终点通常比用酚酞更合适。","options":["正确","错误"],"correct_option":1,"explanation":"错误。弱酸强碱滴定的突跃区偏碱性，酚酞的变色范围通常更匹配。","scaffold":"列全粒子并联立平衡关系、电荷守恒和物料守恒。"},{"id":"Q5R_H3_ELECTRO_01","mother_id":"M5R_H3_ELECTRO_01","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrode_and_charge_path","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.阳极发生氧化反应，阴极发生还原反应。 Ⅱ.该定义对原电池和电解池都成立。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。该定义对原电池和电解池都成立。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_02","mother_id":"M5R_H3_ELECTRO_02","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrode_and_charge_path","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.原电池负极得到电子，发生还原反应。 Ⅱ.原电池负极失去电子，是发生氧化的阳极。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。原电池负极失去电子，是发生氧化的阳极。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_03","mother_id":"M5R_H3_ELECTRO_03","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrode_and_charge_path","level":2,"grade_band":"高三","stem":"判断：用直流电源电解CuSO₄溶液时，与电源正极相连的电极是阳极。","options":["正确","错误"],"correct_option":0,"explanation":"正确。电源正极抽取电子，使相连电极发生氧化。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_04","mother_id":"M5R_H3_ELECTRO_04","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrode_and_charge_path","level":2,"grade_band":"高三","stem":"判断：原电池的电子通过电解质溶液从负极移向正极。","options":["正确","错误"],"correct_option":1,"explanation":"错误。电子走外电路，电解质中迁移的是离子。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_05","mother_id":"M5R_H3_ELECTRO_05","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrode_and_charge_path","level":2,"grade_band":"高三","stem":"判断：盐桥中的离子迁移可维持两半电池溶液电中性。","options":["正确","错误"],"correct_option":0,"explanation":"正确。离子通路阻止电荷持续积累。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_06","mother_id":"M5R_H3_ELECTRO_06","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electron_stoichiometry","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.写电池总反应时可把两个电极反应按电子数相等相加。 Ⅱ.电子在总反应中应被约去。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。电子在总反应中应被约去。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_07","mother_id":"M5R_H3_ELECTRO_07","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electron_stoichiometry","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.放电时转移1 mol电子，对应电子数约为N_A。 Ⅱ.电子也可用物质的量计数。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。电子也可用物质的量计数。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_08","mother_id":"M5R_H3_ELECTRO_08","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electron_stoichiometry","level":3,"grade_band":"高三","stem":"判断：Cu²⁺+2e⁻=Cu表明析出1 mol Cu需转移2 mol电子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。电子计量数由配平的电极反应确定。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_09","mother_id":"M5R_H3_ELECTRO_09","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electron_stoichiometry","level":3,"grade_band":"高三","stem":"判断：2Cl⁻−2e⁻=Cl₂表明生成1 mol Cl₂需转移1 mol电子。","options":["正确","错误"],"correct_option":1,"explanation":"错误。生成1 mol Cl₂需2 mol Cl⁻失去2 mol电子。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_10","mother_id":"M5R_H3_ELECTRO_10","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electron_stoichiometry","level":3,"grade_band":"高三","stem":"判断：电解时通过0.20 mol电子，若阴极只发生Cu²⁺+2e⁻=Cu，则析出Cu为0.10 mol。","options":["正确","错误"],"correct_option":0,"explanation":"正确。每析出1 mol Cu需要2 mol电子。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_11","mother_id":"M5R_H3_ELECTRO_11","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.牺牲阳极保护法中，被保护金属与更活泼金属相连。 Ⅱ.更活泼金属优先氧化，作为牺牲阳极。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。更活泼金属优先氧化，作为牺牲阳极。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_12","mother_id":"M5R_H3_ELECTRO_12","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.外加电流保护中，被保护金属应接直流电源负极。 Ⅱ.使被保护金属成为阴极而避免自身氧化。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。使被保护金属成为阴极而避免自身氧化。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_13","mother_id":"M5R_H3_ELECTRO_13","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高三","stem":"判断：铁发生吸氧腐蚀时，负极可发生Fe−2e⁻=Fe²⁺。","options":["正确","错误"],"correct_option":0,"explanation":"正确。较活泼的铁区域失电子并逐渐溶解。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_14","mother_id":"M5R_H3_ELECTRO_14","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高三","stem":"判断：钢铁表面镀层若破损，镀锌铁通常比镀锡铁更耐腐蚀。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Zn比Fe活泼，破损后仍可作为牺牲阳极；Sn会使Fe成为更易腐蚀的负极。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_15","mother_id":"M5R_H3_ELECTRO_15","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__corrosion_and_protection","level":3,"grade_band":"高三","stem":"判断：在钢铁地下管道上连接铜块可作为牺牲阳极保护钢管。","options":["正确","错误"],"correct_option":1,"explanation":"错误。铜比铁不活泼，不能优先牺牲；应连接Zn、Mg等更活泼金属。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_16","mother_id":"M5R_H3_ELECTRO_16","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrolysis_products","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.用惰性电极电解CuSO₄溶液时，阴极可析出Cu。 Ⅱ.Cu²⁺在阴极得到电子生成Cu。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。Cu²⁺在阴极得到电子生成Cu。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_17","mother_id":"M5R_H3_ELECTRO_17","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrolysis_products","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.用铜电极电解CuSO₄溶液时，阳极铜可溶解生成Cu²⁺。 Ⅱ.活性铜阳极优先发生Cu−2e⁻=Cu²⁺。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。活性铜阳极优先发生Cu−2e⁻=Cu²⁺。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_18","mother_id":"M5R_H3_ELECTRO_18","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrolysis_products","level":4,"grade_band":"高三","stem":"判断：用惰性电极电解NaCl水溶液时，阴极通常是水得电子生成H₂，而不是Na⁺析出Na。","options":["正确","错误"],"correct_option":0,"explanation":"正确。水溶液中Na⁺难以在阴极放电，水更易被还原。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_19","mother_id":"M5R_H3_ELECTRO_19","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrolysis_products","level":4,"grade_band":"高三","stem":"判断：用惰性电极电解CuCl₂溶液时，阴极析出Cu、阳极可生成Cl₂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。阴极Cu²⁺还原，阳极Cl⁻氧化。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_20","mother_id":"M5R_H3_ELECTRO_20","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__electrolysis_products","level":4,"grade_band":"高三","stem":"判断：用惰性电极电解AgNO₃溶液时，阴极析出Ag，阳极通常生成O₂并使阳极区酸性增强。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Ag⁺还原为Ag，水在阳极氧化生成O₂和H⁺。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_21","mother_id":"M5R_H3_ELECTRO_21","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__membrane_plating_and_efficiency","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.离子交换膜只允许电子通过，不允许离子通过。 Ⅱ.膜用于选择性传递离子；电子通过外电路。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。膜用于选择性传递离子；电子通过外电路。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_22","mother_id":"M5R_H3_ELECTRO_22","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__membrane_plating_and_efficiency","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.串联电解池在相同时间内通过的电量相同，可用同一电子物质的量计算各槽产物。 Ⅱ.串联电路电流相同，Q=It相同。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。串联电路电流相同，Q=It相同。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_23","mother_id":"M5R_H3_ELECTRO_23","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__membrane_plating_and_efficiency","level":4,"grade_band":"高三","stem":"判断：电镀时待镀件通常作阴极。","options":["正确","错误"],"correct_option":0,"explanation":"正确。金属离子在阴极还原沉积到待镀件表面。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_24","mother_id":"M5R_H3_ELECTRO_24","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__membrane_plating_and_efficiency","level":4,"grade_band":"高三","stem":"判断：电流效率低于100%时，按总电量计算的理论产物量通常大于实际目标产物量。","options":["正确","错误"],"correct_option":0,"explanation":"正确。部分电量被副反应消耗。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_ELECTRO_25","mother_id":"M5R_H3_ELECTRO_25","skill_id":"H3_ELECTRO","concept_key":"H3_ELECTRO__membrane_plating_and_efficiency","level":4,"grade_band":"高三","stem":"判断：氯碱工业的阳离子交换膜允许Na⁺迁向阴极室，并尽量阻止OH⁻与Cl₂接触。","options":["正确","错误"],"correct_option":0,"explanation":"正确。选择性迁移既维持电中性，又有利于分隔产物、减少副反应。","scaffold":"把两个电极反应配到电子数相等，再检查膜和离子方向。"},{"id":"Q5R_H3_EQUILIBRIUM_01","mother_id":"M5R_H3_EQUILIBRIUM_01","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_and_reaction_quotient","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.可逆反应达到平衡时，正、逆反应速率相等且均不为0。 Ⅱ.化学平衡是微观反应持续进行的动态平衡。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。化学平衡是微观反应持续进行的动态平衡。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_02","mother_id":"M5R_H3_EQUILIBRIUM_02","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_and_reaction_quotient","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.达到平衡时各反应物和生成物的浓度必须相等。 Ⅱ.平衡只要求各组分浓度保持不变，不要求数值彼此相等。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。平衡只要求各组分浓度保持不变，不要求数值彼此相等。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_03","mother_id":"M5R_H3_EQUILIBRIUM_03","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_and_reaction_quotient","level":2,"grade_band":"高三","stem":"判断：一定温度下，同一反应的平衡常数与反应物初始浓度无关。","options":["正确","错误"],"correct_option":0,"explanation":"正确。改变初始浓度会改变平衡组成，但温度不变时K不变。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_04","mother_id":"M5R_H3_EQUILIBRIUM_04","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_and_reaction_quotient","level":2,"grade_band":"高三","stem":"判断：反应商Q<K时，体系将净向生成物方向变化。","options":["正确","错误"],"correct_option":0,"explanation":"正确。当前生成物相对不足，正反应占优势直至Q=K。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_05","mother_id":"M5R_H3_EQUILIBRIUM_05","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_and_reaction_quotient","level":2,"grade_band":"高三","stem":"判断：反应商Q>K时，体系已经平衡，无需发生净变化。","options":["正确","错误"],"correct_option":1,"explanation":"错误。Q>K时体系净向反应物方向变化。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_06","mother_id":"M5R_H3_EQUILIBRIUM_06","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__condition_shift","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.催化剂可改变达到平衡所需时间，但不改变平衡常数。 Ⅱ.催化剂同倍加快正、逆反应，不改变始末热力学状态。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。催化剂同倍加快正、逆反应，不改变始末热力学状态。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_07","mother_id":"M5R_H3_EQUILIBRIUM_07","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__condition_shift","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.对于气体总物质的量减小的正反应，恒温压缩通常使平衡正向移动。 Ⅱ.加压有利于气体总物质的量较少的一侧。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。加压有利于气体总物质的量较少的一侧。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_08","mother_id":"M5R_H3_EQUILIBRIUM_08","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__condition_shift","level":3,"grade_band":"高三","stem":"判断：气体反应前后总物质的量相等时，恒温改变体积一定使平衡移动。","options":["正确","错误"],"correct_option":1,"explanation":"错误。各分压同比变化时Q可保持不变，平衡可不移动。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_09","mother_id":"M5R_H3_EQUILIBRIUM_09","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__condition_shift","level":3,"grade_band":"高三","stem":"判断：恒温恒容加入不参与反应的气体，原平衡一定移动。","options":["正确","错误"],"correct_option":1,"explanation":"错误。反应组分浓度和分压不变时Q不变。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_10","mother_id":"M5R_H3_EQUILIBRIUM_10","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__condition_shift","level":3,"grade_band":"高三","stem":"判断：对于放热正反应，升温会使平衡常数减小。","options":["正确","错误"],"correct_option":0,"explanation":"正确。升温有利于吸热的逆向，平衡生成物相对减少。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_11","mother_id":"M5R_H3_EQUILIBRIUM_11","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_state_invariance","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.对于吸热正反应，升温会使平衡常数减小。 Ⅱ.升温有利于吸热正向，K通常增大。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。升温有利于吸热正向，K通常增大。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_12","mother_id":"M5R_H3_EQUILIBRIUM_12","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_state_invariance","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.改变浓度造成平衡移动时，只要温度不变，K就不改变。 Ⅱ.平衡移动与平衡常数改变不是同一概念。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。平衡移动与平衡常数改变不是同一概念。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_13","mother_id":"M5R_H3_EQUILIBRIUM_13","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_state_invariance","level":3,"grade_band":"高三","stem":"判断：纯固体反应物增加少量，只要各相仍存在，通常不改变平衡组成。","options":["正确","错误"],"correct_option":0,"explanation":"正确。纯固体活度视为常数，不进入常见K表达式。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_14","mother_id":"M5R_H3_EQUILIBRIUM_14","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_state_invariance","level":3,"grade_band":"高三","stem":"判断：浓度—时间图像进入水平平台可说明宏观浓度不再变化。","options":["正确","错误"],"correct_option":0,"explanation":"正确。若体系满足可逆密闭等条件，可据此判断达到平衡。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_15","mother_id":"M5R_H3_EQUILIBRIUM_15","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__equilibrium_state_invariance","level":3,"grade_band":"高三","stem":"判断：同一温度下从正向和逆向均可建立相同的平衡组成，只要总投料约束相同。","options":["正确","错误"],"correct_option":0,"explanation":"正确。平衡状态由温度、总量和容积等状态条件决定，不取决于路径。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_16","mother_id":"M5R_H3_EQUILIBRIUM_16","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__constant_and_three_stage_calculation","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.反应方程式反向书写后，新平衡常数等于原K的倒数。 Ⅱ.反应物和生成物在表达式中互换。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。反应物和生成物在表达式中互换。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_17","mother_id":"M5R_H3_EQUILIBRIUM_17","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__constant_and_three_stage_calculation","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.反应方程式各系数乘2后，新平衡常数为2K。 Ⅱ.表达式中各项指数乘2，新平衡常数为K²。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。表达式中各项指数乘2，新平衡常数为K²。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_18","mother_id":"M5R_H3_EQUILIBRIUM_18","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__constant_and_three_stage_calculation","level":4,"grade_band":"高三","stem":"判断：多个反应相加得到目标反应时，目标K可由各分步K按乘除和乘方组合。","options":["正确","错误"],"correct_option":0,"explanation":"正确。方程式相加对应K相乘，反向对应取倒数，倍乘对应乘方。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_19","mother_id":"M5R_H3_EQUILIBRIUM_19","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__constant_and_three_stage_calculation","level":4,"grade_band":"高三","stem":"判断：用三段式计算平衡组成时，各物质浓度变化量之比应符合化学计量数之比。","options":["正确","错误"],"correct_option":0,"explanation":"正确。同一反应进度控制所有组分的变化。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_20","mother_id":"M5R_H3_EQUILIBRIUM_20","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__constant_and_three_stage_calculation","level":4,"grade_band":"高三","stem":"判断：反应A(g)⇌B(g)中，A的初始浓度为1.0 mol·L⁻¹、平衡时为0.6 mol·L⁻¹，则B的浓度变化量为0.4 mol·L⁻¹。","options":["正确","错误"],"correct_option":0,"explanation":"正确。A与B系数比为1∶1，A减少0.4 mol·L⁻¹时B增加相同浓度。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_21","mother_id":"M5R_H3_EQUILIBRIUM_21","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__disturbance_and_industry","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.增大某反应物浓度后平衡正向移动，该反应物的新平衡浓度一定低于原平衡浓度。 Ⅱ.平衡只部分抵消加入量，新平衡浓度可能仍高于原值。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。平衡只部分抵消加入量，新平衡浓度可能仍高于原值。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_22","mother_id":"M5R_H3_EQUILIBRIUM_22","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__disturbance_and_industry","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.减小容积的瞬间，所有气体浓度都增大，但正、逆反应速率的变化不一定相同。 Ⅱ.压缩后体系可能不再满足原平衡条件，正、逆速率出现差异并引起净移动。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。压缩后体系可能不再满足原平衡条件，正、逆速率出现差异并引起净移动。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_23","mother_id":"M5R_H3_EQUILIBRIUM_23","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__disturbance_and_industry","level":4,"grade_band":"高三","stem":"判断：平衡移动只能减弱外界改变，不能保证完全抵消该改变。","options":["正确","错误"],"correct_option":0,"explanation":"正确。勒夏特列原理的关键词是“减弱”而非“消除”。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_24","mother_id":"M5R_H3_EQUILIBRIUM_24","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__disturbance_and_industry","level":4,"grade_band":"高三","stem":"判断：合成氨使用催化剂的主要作用是提高氨的平衡产率。","options":["正确","错误"],"correct_option":1,"explanation":"错误。催化剂主要提高反应速率，不改变平衡产率。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EQUILIBRIUM_25","mother_id":"M5R_H3_EQUILIBRIUM_25","skill_id":"H3_EQUILIBRIUM","concept_key":"H3_EQUILIBRIUM__disturbance_and_industry","level":4,"grade_band":"高三","stem":"判断：工业平衡条件需要同时权衡平衡转化率、反应速率、能耗、安全和分离成本。","options":["正确","错误"],"correct_option":0,"explanation":"正确。最优生产条件通常不是单一因素的极端值。","scaffold":"用改变后瞬间的Q与K或v正与v逆判断净方向。"},{"id":"Q5R_H3_EXPERIMENT_01","mother_id":"M5R_H3_EXPERIMENT_01","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__apparatus_and_safety","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.制备气体的装置在加入药品前通常应先检查气密性。 Ⅱ.先检查可避免加药后才发现漏气而被迫拆卸装置。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。先检查可避免加药后才发现漏气而被迫拆卸装置。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_02","mother_id":"M5R_H3_EXPERIMENT_02","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__apparatus_and_safety","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.给试管中的固体加热时，试管口通常应略向下倾斜。 Ⅱ.可防止冷凝液回流到热的试管底部造成炸裂。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。可防止冷凝液回流到热的试管底部造成炸裂。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_03","mother_id":"M5R_H3_EXPERIMENT_03","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__apparatus_and_safety","level":2,"grade_band":"高三","stem":"判断：熄灭酒精灯时可直接用嘴吹灭。","options":["正确","错误"],"correct_option":1,"explanation":"错误。应用灯帽盖灭，吹灭可能引起火焰回窜或酒精飞溅。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_04","mother_id":"M5R_H3_EXPERIMENT_04","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__apparatus_and_safety","level":2,"grade_band":"高三","stem":"判断：稀释浓硫酸时应把水缓慢加入浓硫酸并不断搅拌。","options":["正确","错误"],"correct_option":1,"explanation":"错误。应把浓硫酸沿器壁缓慢加入水中，避免局部剧烈放热导致液体飞溅。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_05","mother_id":"M5R_H3_EXPERIMENT_05","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__apparatus_and_safety","level":2,"grade_band":"高三","stem":"判断：加热装有固体的试管时，应先预热再集中加热药品部位。","options":["正确","错误"],"correct_option":0,"explanation":"正确。先使试管受热较均匀，可降低局部温差过大导致破裂的风险。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_06","mother_id":"M5R_H3_EXPERIMENT_06","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__gas_purification_and_collection","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.净化并干燥气体时通常先除杂、后干燥。 Ⅱ.若先干燥再通过水溶液除杂，气体会重新带入水蒸气。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。若先干燥再通过水溶液除杂，气体会重新带入水蒸气。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_07","mother_id":"M5R_H3_EXPERIMENT_07","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__gas_purification_and_collection","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.可用浓硫酸干燥NH₃。 Ⅱ.NH₃会与浓硫酸发生反应，应选择碱石灰等适用干燥剂。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。NH₃会与浓硫酸发生反应，应选择碱石灰等适用干燥剂。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_08","mother_id":"M5R_H3_EXPERIMENT_08","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__gas_purification_and_collection","level":3,"grade_band":"高三","stem":"判断：可用浓硫酸干燥不与其反应的Cl₂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。浓硫酸吸水且常温下不消耗Cl₂。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_09","mother_id":"M5R_H3_EXPERIMENT_09","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__gas_purification_and_collection","level":3,"grade_band":"高三","stem":"判断：NH₃极易溶于水，不能用排水法收集。","options":["正确","错误"],"correct_option":0,"explanation":"正确。应根据其密度和溶解性选择向下排空气等方法。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_10","mother_id":"M5R_H3_EXPERIMENT_10","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__gas_purification_and_collection","level":3,"grade_band":"高三","stem":"判断：CO₂密度大于空气且能溶于水，实验室常用向上排空气法收集。","options":["正确","错误"],"correct_option":0,"explanation":"正确。排空气可避免排水造成的溶解损失。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_11","mother_id":"M5R_H3_EXPERIMENT_11","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__volumetric_and_titration","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.配制一定物质的量浓度溶液时，容量瓶可用来直接溶解放热的固体。 Ⅱ.应在烧杯中溶解并冷却到室温后再转移定容。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。应在烧杯中溶解并冷却到室温后再转移定容。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_12","mother_id":"M5R_H3_EXPERIMENT_12","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__volumetric_and_titration","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.容量瓶定容时视线应与刻度线及凹液面最低点保持水平。 Ⅱ.俯视或仰视会造成体积系统误差。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。俯视或仰视会造成体积系统误差。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_13","mother_id":"M5R_H3_EXPERIMENT_13","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__volumetric_and_titration","level":3,"grade_band":"高三","stem":"判断：滴定前，酸式滴定管只用蒸馏水洗净即可直接装标准液。","options":["正确","错误"],"correct_option":1,"explanation":"错误。还应使用待装标准液润洗，避免残留水稀释标准液。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_14","mother_id":"M5R_H3_EXPERIMENT_14","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__volumetric_and_titration","level":3,"grade_band":"高三","stem":"判断：滴定用锥形瓶用蒸馏水洗净后，不必用待测液润洗。","options":["正确","错误"],"correct_option":0,"explanation":"正确。瓶内少量蒸馏水不改变待测物质的量。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_15","mother_id":"M5R_H3_EXPERIMENT_15","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__volumetric_and_titration","level":3,"grade_band":"高三","stem":"判断：滴定终点应以指示剂颜色出现瞬时变化为准。","options":["正确","错误"],"correct_option":1,"explanation":"错误。通常要求颜色变化达到规定状态并保持约30 s不褪。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_16","mother_id":"M5R_H3_EXPERIMENT_16","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__separation_operation","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.过滤时漏斗中液面应低于滤纸边缘。 Ⅱ.防止未经过滤的液体从滤纸与漏斗间越过。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。防止未经过滤的液体从滤纸与漏斗间越过。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_17","mother_id":"M5R_H3_EXPERIMENT_17","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__separation_operation","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.洗涤沉淀时可沿玻璃棒向漏斗中加入少量洗液，待流尽后重复。 Ⅱ.少量多次有利于在减少溶解损失的同时除去附着杂质。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。少量多次有利于在减少溶解损失的同时除去附着杂质。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_18","mother_id":"M5R_H3_EXPERIMENT_18","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__separation_operation","level":4,"grade_band":"高三","stem":"判断：检验沉淀是否洗净时，应取少量沉淀本身加入检验试剂。","options":["正确","错误"],"correct_option":1,"explanation":"错误。应检验最后一次洗涤液中是否仍含需除去的离子。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_19","mother_id":"M5R_H3_EXPERIMENT_19","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__separation_operation","level":4,"grade_band":"高三","stem":"判断：蒸发结晶时应把溶液加热至完全蒸干再停止。","options":["正确","错误"],"correct_option":1,"explanation":"错误。接近蒸干时易造成晶体飞溅或分解，通常出现较多晶体时利用余热。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_20","mother_id":"M5R_H3_EXPERIMENT_20","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__separation_operation","level":4,"grade_band":"高三","stem":"判断：蒸馏测沸点时，温度计水银球应位于蒸馏烧瓶支管口附近。","options":["正确","错误"],"correct_option":0,"explanation":"正确。测量的是进入冷凝管的蒸气温度。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_21","mother_id":"M5R_H3_EXPERIMENT_21","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__control_and_evidence","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.探究温度对反应速率的影响时，只改变温度而保持反应物浓度和用量相同，可构成对照。 Ⅱ.控制其他变量后，速率差异才能主要归因于温度。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。控制其他变量后，速率差异才能主要归因于温度。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_22","mother_id":"M5R_H3_EXPERIMENT_22","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__control_and_evidence","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.检验某无色气体是否为CO₂时，仅观察其使澄清石灰水变浑浊不能排除SO₂干扰。 Ⅱ.SO₂也可能产生相似现象，需要增加排除SO₂的检验。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。SO₂也可能产生相似现象，需要增加排除SO₂的检验。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_23","mother_id":"M5R_H3_EXPERIMENT_23","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__control_and_evidence","level":4,"grade_band":"高三","stem":"判断：空白实验可用于扣除试剂、溶剂或仪器本身造成的背景消耗。","options":["正确","错误"],"correct_option":0,"explanation":"正确。空白值能修正非待测物引起的系统偏差。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_24","mother_id":"M5R_H3_EXPERIMENT_24","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__control_and_evidence","level":4,"grade_band":"高三","stem":"判断：探究单一因素对速率的影响时，应尽量只改变该因素并控制其他条件。","options":["正确","错误"],"correct_option":0,"explanation":"正确。控制变量使观察差异具有明确归因。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_EXPERIMENT_25","mother_id":"M5R_H3_EXPERIMENT_25","skill_id":"H3_EXPERIMENT","concept_key":"H3_EXPERIMENT__control_and_evidence","level":4,"grade_band":"高三","stem":"判断：观察到两个现象同时出现，就能直接证明二者存在因果关系。","options":["正确","错误"],"correct_option":1,"explanation":"错误。还需对照、排除干扰并建立与反应原理一致的证据链。","scaffold":"把操作与实验目的对应，并检查安全、对照和误差方向。"},{"id":"Q5R_H3_INORGANIC_01","mother_id":"M5R_H3_INORGANIC_01","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__sodium_compounds","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.Na₂O₂与水反应可生成NaOH和O₂。 Ⅱ.反应为2Na₂O₂+2H₂O=4NaOH+O₂↑。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。反应为2Na₂O₂+2H₂O=4NaOH+O₂↑。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_02","mother_id":"M5R_H3_INORGANIC_02","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__sodium_compounds","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.Na₂O₂中氧元素的化合价为−2。 Ⅱ.过氧化物中氧元素为−1价。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。过氧化物中氧元素为−1价。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_03","mother_id":"M5R_H3_INORGANIC_03","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__sodium_compounds","level":2,"grade_band":"高三","stem":"判断：Na₂O₂可作供氧剂，与其能和CO₂反应放出O₂有关。","options":["正确","错误"],"correct_option":0,"explanation":"正确。2Na₂O₂+2CO₂=2Na₂CO₃+O₂。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_04","mother_id":"M5R_H3_INORGANIC_04","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__sodium_compounds","level":2,"grade_band":"高三","stem":"判断：NaHCO₃受热比Na₂CO₃更稳定。","options":["正确","错误"],"correct_option":1,"explanation":"错误。NaHCO₃受热易分解为Na₂CO₃、CO₂和H₂O。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_05","mother_id":"M5R_H3_INORGANIC_05","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__sodium_compounds","level":2,"grade_band":"高三","stem":"判断：向Na₂CO₃溶液中逐滴加入盐酸时，可依次发生CO₃²⁻转化为HCO₃⁻、再生成CO₂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。盐酸量不足时先生成HCO₃⁻，继续加酸才放出CO₂。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_06","mother_id":"M5R_H3_INORGANIC_06","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__chlorine_and_bleaching","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.氯水的漂白性主要来自HCl。 Ⅱ.漂白、消毒主要来自HClO的强氧化性。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。漂白、消毒主要来自HClO的强氧化性。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_07","mother_id":"M5R_H3_INORGANIC_07","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__chlorine_and_bleaching","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.新制氯水久置后酸性通常增强而漂白性减弱。 Ⅱ.HClO见光分解，最终HCl增多、有效HClO减少。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。HClO见光分解，最终HCl增多、有效HClO减少。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_08","mother_id":"M5R_H3_INORGANIC_08","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__chlorine_and_bleaching","level":3,"grade_band":"高三","stem":"判断：SO₂使品红褪色后，加热颜色可能恢复。","options":["正确","错误"],"correct_option":0,"explanation":"正确。SO₂与某些有色物质形成不稳定无色物，漂白常具有可逆性。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_09","mother_id":"M5R_H3_INORGANIC_09","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__chlorine_and_bleaching","level":3,"grade_band":"高三","stem":"判断：SO₂和Cl₂都具有漂白性，二者等物质的量混合后漂白性一定更强。","options":["正确","错误"],"correct_option":1,"explanation":"错误。二者可发生氧化还原反应而相互消耗，漂白性可能减弱或消失。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_10","mother_id":"M5R_H3_INORGANIC_10","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__chlorine_and_bleaching","level":3,"grade_band":"高三","stem":"判断：Cl₂通入石灰乳可制得含Ca(ClO)₂的漂白粉。","options":["正确","错误"],"correct_option":0,"explanation":"正确。氯气在碱性介质中歧化，次氯酸盐提供漂白消毒能力。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_11","mother_id":"M5R_H3_INORGANIC_11","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__nitrogen_compounds","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.常温下铁遇浓硝酸可发生钝化。 Ⅱ.表面形成致密保护膜，使进一步反应显著变慢。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。表面形成致密保护膜，使进一步反应显著变慢。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_12","mother_id":"M5R_H3_INORGANIC_12","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__nitrogen_compounds","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.钝化说明铁与浓硝酸完全不能发生氧化还原反应。 Ⅱ.钝化源于表面膜，并非没有发生初始反应。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。钝化源于表面膜，并非没有发生初始反应。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_13","mother_id":"M5R_H3_INORGANIC_13","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__nitrogen_compounds","level":3,"grade_band":"高三","stem":"判断：NO是红棕色气体，NO₂是无色气体。","options":["正确","错误"],"correct_option":1,"explanation":"错误。NO通常无色，NO₂呈红棕色。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_14","mother_id":"M5R_H3_INORGANIC_14","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__nitrogen_compounds","level":3,"grade_band":"高三","stem":"判断：NO在空气中可被O₂氧化为NO₂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。反应为2NO+O₂=2NO₂。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_15","mother_id":"M5R_H3_INORGANIC_15","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__nitrogen_compounds","level":3,"grade_band":"高三","stem":"判断：NO₂与水反应只生成HNO₃，不生成其他含氮产物。","options":["正确","错误"],"correct_option":1,"explanation":"错误。常见反应3NO₂+H₂O=2HNO₃+NO。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_16","mother_id":"M5R_H3_INORGANIC_16","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__iron_and_aluminium","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.Fe³⁺溶液可与铁粉发生2Fe³⁺+Fe=3Fe²⁺，所得溶液中Fe³⁺可能减少。 Ⅱ.铁单质还原Fe³⁺并自身被氧化为Fe²⁺。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。铁单质还原Fe³⁺并自身被氧化为Fe²⁺。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_17","mother_id":"M5R_H3_INORGANIC_17","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__iron_and_aluminium","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.Fe²⁺溶液长期暴露在空气中可能被氧化为Fe³⁺。 Ⅱ.空气中的O₂可氧化Fe²⁺。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。空气中的O₂可氧化Fe²⁺。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_18","mother_id":"M5R_H3_INORGANIC_18","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__iron_and_aluminium","level":4,"grade_band":"高三","stem":"判断：向Fe³⁺溶液中加入KSCN出现血红色，可支持存在Fe³⁺。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Fe³⁺与SCN⁻形成显色配合物。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_19","mother_id":"M5R_H3_INORGANIC_19","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__iron_and_aluminium","level":4,"grade_band":"高三","stem":"判断：Fe(OH)₂沉淀在空气中最终可转化为红褐色Fe(OH)₃。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Fe(OH)₂易被O₂氧化。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_20","mother_id":"M5R_H3_INORGANIC_20","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__iron_and_aluminium","level":4,"grade_band":"高三","stem":"判断：Al₂O₃只能与酸反应，不能与强碱反应。","options":["正确","错误"],"correct_option":1,"explanation":"错误。Al₂O₃是两性氧化物，既可与酸也可与强碱反应。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_21","mother_id":"M5R_H3_INORGANIC_21","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__silicon_and_carbon","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.工业制粗硅可用焦炭在高温下还原SiO₂。 Ⅱ.高温反应中SiO₂被还原，体现硅单质制备的基本转化。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。高温反应中SiO₂被还原，体现硅单质制备的基本转化。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_22","mother_id":"M5R_H3_INORGANIC_22","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__silicon_and_carbon","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.SiO₂可直接与水反应生成H₂SiO₃。 Ⅱ.SiO₂通常不与水直接反应。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。SiO₂通常不与水直接反应。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_23","mother_id":"M5R_H3_INORGANIC_23","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__silicon_and_carbon","level":4,"grade_band":"高三","stem":"判断：SiO₂能与HF反应，因此氢氟酸不能长期装在普通玻璃瓶中。","options":["正确","错误"],"correct_option":0,"explanation":"正确。玻璃主要含SiO₂，HF会腐蚀玻璃。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_24","mother_id":"M5R_H3_INORGANIC_24","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__silicon_and_carbon","level":4,"grade_band":"高三","stem":"判断：NaHCO₃受热产生的CO₂通入澄清石灰水，可先生成CaCO₃白色沉淀。","options":["正确","错误"],"correct_option":0,"explanation":"正确。CO₂适量时发生CO₂+Ca(OH)₂=CaCO₃↓+H₂O。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_INORGANIC_25","mother_id":"M5R_H3_INORGANIC_25","skill_id":"H3_INORGANIC","concept_key":"H3_INORGANIC__silicon_and_carbon","level":4,"grade_band":"高三","stem":"判断：Na₂SiO₃溶液中通入CO₂可生成H₂SiO₃胶体，说明碳酸在该条件下能制出更弱的硅酸。","options":["正确","错误"],"correct_option":0,"explanation":"正确。反应利用较强酸制较弱酸，并出现胶体沉淀现象。","scaffold":"锁定中心元素的价态、物质类别和题给反应条件。"},{"id":"Q5R_H3_ION_REDOX_01","mother_id":"M5R_H3_ION_REDOX_01","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ionic_equation_species","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.书写离子方程式时，易溶强电解质通常拆写成离子。 Ⅱ.强酸、强碱和可溶性盐在水溶液中以离子为主。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。强酸、强碱和可溶性盐在水溶液中以离子为主。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_02","mother_id":"M5R_H3_ION_REDOX_02","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ionic_equation_species","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.书写离子方程式时，弱酸、弱碱都应拆写成离子。 Ⅱ.弱电解质主要以分子形式存在，应保留化学式。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。弱电解质主要以分子形式存在，应保留化学式。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_03","mother_id":"M5R_H3_ION_REDOX_03","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ionic_equation_species","level":2,"grade_band":"高三","stem":"判断：盐酸与NaOH溶液反应的离子方程式为H⁺+OH⁻=H₂O。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Na⁺和Cl⁻是旁观离子，约去后得到中和实质。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_04","mother_id":"M5R_H3_ION_REDOX_04","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ionic_equation_species","level":2,"grade_band":"高三","stem":"判断：BaCl₂与Na₂SO₄溶液反应的离子方程式为Ba²⁺+SO₄²⁻=BaSO₄↓。","options":["正确","错误"],"correct_option":0,"explanation":"正确。生成难溶硫酸钡是反应推动力。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_05","mother_id":"M5R_H3_ION_REDOX_05","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ionic_equation_species","level":2,"grade_band":"高三","stem":"判断：CaCO₃与盐酸反应时，CaCO₃应拆写成Ca²⁺和CO₃²⁻。","options":["正确","错误"],"correct_option":1,"explanation":"错误。CaCO₃是难溶固体，在离子方程式中保留化学式。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_06","mother_id":"M5R_H3_ION_REDOX_06","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_balance","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.CO₃²⁻与足量H⁺反应的离子方程式可写为CO₃²⁻+2H⁺=CO₂↑+H₂O。 Ⅱ.足量酸使碳酸根最终转化为CO₂和水。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。足量酸使碳酸根最终转化为CO₂和水。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_07","mother_id":"M5R_H3_ION_REDOX_07","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_balance","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.HCO₃⁻与H⁺反应的离子方程式为HCO₃⁻+H⁺=CO₂↑+H₂O。 Ⅱ.原子数和电荷均守恒。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。原子数和电荷均守恒。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_08","mother_id":"M5R_H3_ION_REDOX_08","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_balance","level":3,"grade_band":"高三","stem":"判断：Fe与Fe³⁺溶液反应可写为Fe+Fe³⁺=2Fe²⁺。","options":["正确","错误"],"correct_option":1,"explanation":"错误。正确配平为Fe+2Fe³⁺=3Fe²⁺，需同时满足电子和电荷守恒。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_09","mother_id":"M5R_H3_ION_REDOX_09","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_balance","level":3,"grade_band":"高三","stem":"判断：酸性条件下MnO₄⁻把Fe²⁺氧化为Fe³⁺时，MnO₄⁻被还原为Mn²⁺。","options":["正确","错误"],"correct_option":0,"explanation":"正确。酸性介质中Mn由+7价降为+2价。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_10","mother_id":"M5R_H3_ION_REDOX_10","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_balance","level":3,"grade_band":"高三","stem":"判断：酸性高锰酸钾与Fe²⁺反应中，1 mol MnO₄⁻得到5 mol电子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Mn由+7价降到+2价，每个Mn得到5e⁻。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_11","mother_id":"M5R_H3_ION_REDOX_11","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ion_test_and_phenomena","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.Cl₂与冷的稀NaOH反应中，Cl₂既作氧化剂又作还原剂。 Ⅱ.Cl由0价分别变为−1价和+1价，发生歧化。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。Cl由0价分别变为−1价和+1价，发生歧化。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_12","mother_id":"M5R_H3_ION_REDOX_12","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ion_test_and_phenomena","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.溶液中加入Ba²⁺后生成白色沉淀，即可唯一证明原溶液含SO₄²⁻。 Ⅱ.CO₃²⁻等也可与Ba²⁺形成白色沉淀，需设计排除干扰。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。CO₃²⁻等也可与Ba²⁺形成白色沉淀，需设计排除干扰。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_13","mother_id":"M5R_H3_ION_REDOX_13","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ion_test_and_phenomena","level":3,"grade_band":"高三","stem":"判断：检验SO₄²⁻时可先用盐酸酸化，再加入BaCl₂溶液。","options":["正确","错误"],"correct_option":0,"explanation":"正确。酸化可排除CO₃²⁻等干扰，出现不溶于酸的白色沉淀支持结论。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_14","mother_id":"M5R_H3_ION_REDOX_14","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ion_test_and_phenomena","level":3,"grade_band":"高三","stem":"判断：NH₄⁺与OH⁻在加热条件下可生成NH₃和H₂O。","options":["正确","错误"],"correct_option":0,"explanation":"正确。离子方程式为NH₄⁺+OH⁻=NH₃↑+H₂O。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_15","mother_id":"M5R_H3_ION_REDOX_15","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__ion_test_and_phenomena","level":3,"grade_band":"高三","stem":"判断：Al³⁺与过量氨水反应可直接生成可溶性偏铝酸根。","options":["正确","错误"],"correct_option":1,"explanation":"错误。氨水碱性较弱，通常生成Al(OH)₃沉淀而不继续溶解。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_16","mother_id":"M5R_H3_ION_REDOX_16","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__coexistence_and_medium","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.强酸性溶液中HCO₃⁻可大量共存。 Ⅱ.HCO₃⁻会与大量H⁺反应生成CO₂和H₂O。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。HCO₃⁻会与大量H⁺反应生成CO₂和H₂O。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_17","mother_id":"M5R_H3_ION_REDOX_17","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__coexistence_and_medium","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.无色溶液中MnO₄⁻可大量存在而不影响“无色”条件。 Ⅱ.MnO₄⁻呈紫色，与无色条件矛盾。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。MnO₄⁻呈紫色，与无色条件矛盾。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_18","mother_id":"M5R_H3_ION_REDOX_18","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__coexistence_and_medium","level":4,"grade_band":"高三","stem":"判断：Fe³⁺与SCN⁻可因形成血红色配合物而用于Fe³⁺检验。","options":["正确","错误"],"correct_option":0,"explanation":"正确。明显颜色变化是常用检验现象，但仍需关注其他干扰。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_19","mother_id":"M5R_H3_ION_REDOX_19","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__coexistence_and_medium","level":4,"grade_band":"高三","stem":"判断：离子方程式配平后只需满足原子守恒，不需满足电荷守恒。","options":["正确","错误"],"correct_option":1,"explanation":"错误。离子反应必须同时满足元素原子守恒和总电荷守恒。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_20","mother_id":"M5R_H3_ION_REDOX_20","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__coexistence_and_medium","level":4,"grade_band":"高三","stem":"判断：氧化还原离子方程式中可用H⁺、H₂O配平酸性介质中的H和O。","options":["正确","错误"],"correct_option":0,"explanation":"正确。介质条件决定可使用的配平粒子。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_21","mother_id":"M5R_H3_ION_REDOX_21","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_validity","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.碱性介质的离子方程式最终可以保留大量H⁺作为反应物。 Ⅱ.碱性条件下应通过加入OH⁻等消去H⁺，使方程式符合介质。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。碱性条件下应通过加入OH⁻等消去H⁺，使方程式符合介质。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_22","mother_id":"M5R_H3_ION_REDOX_22","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_validity","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.含Fe³⁺的溶液中加入I⁻时可发生2Fe³⁺+2I⁻=2Fe²⁺+I₂，因此二者不能大量共存。 Ⅱ.Fe³⁺可氧化I⁻，该方程式同时满足原子、电荷和电子守恒。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。Fe³⁺可氧化I⁻，该方程式同时满足原子、电荷和电子守恒。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_23","mother_id":"M5R_H3_ION_REDOX_23","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_validity","level":4,"grade_band":"高三","stem":"判断：反应2Fe³⁺+Cu=2Fe²⁺+Cu²⁺中Cu为氧化剂。","options":["正确","错误"],"correct_option":1,"explanation":"错误。Cu由0价升为+2价，失电子，是还原剂。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_24","mother_id":"M5R_H3_ION_REDOX_24","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_validity","level":4,"grade_band":"高三","stem":"判断：离子方程式2H⁺+2OH⁻=2H₂O已用最简整数比表示。","options":["正确","错误"],"correct_option":1,"explanation":"错误。各系数仍有公因数2，应约为H⁺+OH⁻=H₂O。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ION_REDOX_25","mother_id":"M5R_H3_ION_REDOX_25","skill_id":"H3_ION_REDOX","concept_key":"H3_ION_REDOX__equation_validity","level":4,"grade_band":"高三","stem":"判断：反应前后的Na⁺分别以Na⁺和NaHCO₃形式出现时，可以把两者直接约去。","options":["正确","错误"],"correct_option":1,"explanation":"错误。粒子形式不同，NaHCO₃中的Na不能作为同形旁观离子直接相消。","scaffold":"先按介质写粒子形式，再检查原子、电荷和电子守恒。"},{"id":"Q5R_H3_ORGANIC_01","mother_id":"M5R_H3_ORGANIC_01","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__carbon_skeleton_and_hydrocarbon","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.有机物中碳原子通常形成4个共价键。 Ⅱ.碳的四价性是分析结构和补氢数的重要基础。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。碳的四价性是分析结构和补氢数的重要基础。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_02","mother_id":"M5R_H3_ORGANIC_02","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__carbon_skeleton_and_hydrocarbon","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.互为同系物的有机物结构相似、属于同一类别，组成上通常相差一个或若干个CH₂。 Ⅱ.同系物具有相同通式和相似化学性质，组成呈规律递变。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。同系物具有相同通式和相似化学性质，组成呈规律递变。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_03","mother_id":"M5R_H3_ORGANIC_03","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__carbon_skeleton_and_hydrocarbon","level":2,"grade_band":"高三","stem":"判断：分子式相同的两种有机物一定是同一种物质。","options":["正确","错误"],"correct_option":1,"explanation":"错误。连接顺序或空间排列不同可形成同分异构体。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_04","mother_id":"M5R_H3_ORGANIC_04","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__carbon_skeleton_and_hydrocarbon","level":2,"grade_band":"高三","stem":"判断：烷烃在光照条件下可与Cl₂发生取代反应。","options":["正确","错误"],"correct_option":0,"explanation":"正确。烷烃中的H可被Cl取代，并可能生成多种取代产物。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_05","mother_id":"M5R_H3_ORGANIC_05","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__carbon_skeleton_and_hydrocarbon","level":2,"grade_band":"高三","stem":"判断：乙烯能使溴水褪色，主要发生加成反应。","options":["正确","错误"],"correct_option":0,"explanation":"正确。C=C中的π键断裂，Br原子加到两个碳上。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_06","mother_id":"M5R_H3_ORGANIC_06","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__unsaturation_and_aromatic_reaction","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.乙烯使酸性KMnO₄溶液褪色时只发生物理萃取。 Ⅱ.乙烯被氧化，属于化学反应。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。乙烯被氧化，属于化学反应。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_07","mother_id":"M5R_H3_ORGANIC_07","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__unsaturation_and_aromatic_reaction","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.苯在一定条件下可与液溴发生取代反应。 Ⅱ.在适当催化剂存在下生成溴苯和HBr。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。在适当催化剂存在下生成溴苯和HBr。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_08","mother_id":"M5R_H3_ORGANIC_08","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__unsaturation_and_aromatic_reaction","level":3,"grade_band":"高三","stem":"判断：乙炔与足量H₂在催化剂存在下完全加成可生成乙烷。","options":["正确","错误"],"correct_option":0,"explanation":"正确。碳碳三键可连续发生加成，完全加氢得到饱和烃。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_09","mother_id":"M5R_H3_ORGANIC_09","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__unsaturation_and_aromatic_reaction","level":3,"grade_band":"高三","stem":"判断：苯与H₂在一定温度、压强和催化剂条件下可加成生成环己烷。","options":["正确","错误"],"correct_option":0,"explanation":"正确。苯的加成需要较强条件，产物碳骨架仍为六元环。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_10","mother_id":"M5R_H3_ORGANIC_10","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__unsaturation_and_aromatic_reaction","level":3,"grade_band":"高三","stem":"判断：甲苯能使酸性KMnO₄溶液褪色，可利用侧链氧化与苯相区别。","options":["正确","错误"],"correct_option":0,"explanation":"正确。苯环侧链含苄位氢时可被强氧化剂氧化，而苯在该条件下通常不反应。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_11","mother_id":"M5R_H3_ORGANIC_11","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__oxygen_functional_group","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.苯酚遇FeCl₃溶液可出现特征显色。 Ⅱ.该反应常用于酚羟基的辅助检验。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。该反应常用于酚羟基的辅助检验。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_12","mother_id":"M5R_H3_ORGANIC_12","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__oxygen_functional_group","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.乙醛可发生银镜反应。 Ⅱ.醛基可还原银氨溶液中的银离子。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。醛基可还原银氨溶液中的银离子。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_13","mother_id":"M5R_H3_ORGANIC_13","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__oxygen_functional_group","level":3,"grade_band":"高三","stem":"判断：丙酮含羰基，因此一定能发生银镜反应。","options":["正确","错误"],"correct_option":1,"explanation":"错误。普通酮羰基不具备醛基的还原性。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_14","mother_id":"M5R_H3_ORGANIC_14","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__oxygen_functional_group","level":3,"grade_band":"高三","stem":"判断：乙酸可与NaHCO₃反应放出CO₂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。羧酸酸性强于碳酸的第一步电离，可生成CO₂和水。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_15","mother_id":"M5R_H3_ORGANIC_15","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__oxygen_functional_group","level":3,"grade_band":"高三","stem":"判断：酯化反应通常是可逆反应，浓硫酸可作催化剂和吸水剂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。移去水还能推动平衡向酯生成方向移动。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_16","mother_id":"M5R_H3_ORGANIC_16","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__biomolecule_reaction","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.油脂在碱性条件下水解可生成高级脂肪酸盐和甘油。 Ⅱ.该反应称为皂化反应，是油脂水解的重要应用。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。该反应称为皂化反应，是油脂水解的重要应用。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_17","mother_id":"M5R_H3_ORGANIC_17","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__biomolecule_reaction","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.氨基酸只含碱性基团，因此只能与酸反应。 Ⅱ.氨基酸通常同时含氨基和羧基，具有两性。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。氨基酸通常同时含氨基和羧基，具有两性。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_18","mother_id":"M5R_H3_ORGANIC_18","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__biomolecule_reaction","level":4,"grade_band":"高三","stem":"判断：葡萄糖含醛基特征，可在适当条件下发生银镜反应。","options":["正确","错误"],"correct_option":0,"explanation":"正确。开链形式含醛基，具有还原性。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_19","mother_id":"M5R_H3_ORGANIC_19","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__biomolecule_reaction","level":4,"grade_band":"高三","stem":"判断：蔗糖属于还原糖，能直接发生银镜反应。","options":["正确","错误"],"correct_option":1,"explanation":"错误。蔗糖通常不表现还原性，水解后产物可具有还原性。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_20","mother_id":"M5R_H3_ORGANIC_20","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__biomolecule_reaction","level":4,"grade_band":"高三","stem":"判断：淀粉遇碘可出现特征蓝色。","options":["正确","错误"],"correct_option":0,"explanation":"正确。该显色可用于淀粉的定性检验。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_21","mother_id":"M5R_H3_ORGANIC_21","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__polymerization","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.乙烯生成聚乙烯属于加聚反应，反应中没有小分子副产物。 Ⅱ.双键打开后单体连续加成形成高分子。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。双键打开后单体连续加成形成高分子。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_22","mother_id":"M5R_H3_ORGANIC_22","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__polymerization","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.由二元酸和二元醇生成聚酯属于缩聚反应。 Ⅱ.形成高分子链的同时通常脱去水等小分子。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。形成高分子链的同时通常脱去水等小分子。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_23","mother_id":"M5R_H3_ORGANIC_23","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__polymerization","level":4,"grade_band":"高三","stem":"判断：氯乙烯发生加聚反应生成聚氯乙烯时，单体的C=C打开并连接成长链。","options":["正确","错误"],"correct_option":0,"explanation":"正确。加聚过程中不脱去小分子，重复单元来自氯乙烯。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_24","mother_id":"M5R_H3_ORGANIC_24","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__polymerization","level":4,"grade_band":"高三","stem":"判断：缩聚反应的单体通常至少含两个可相互反应的官能团。","options":["正确","错误"],"correct_option":0,"explanation":"正确。双官能或多官能单体才能连续成键形成高分子链。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_ORGANIC_25","mother_id":"M5R_H3_ORGANIC_25","skill_id":"H3_ORGANIC","concept_key":"H3_ORGANIC__polymerization","level":4,"grade_band":"高三","stem":"判断：聚乙烯的链节为—CH₂—CH₂—，其单体为CH₂=CH₂。","options":["正确","错误"],"correct_option":0,"explanation":"正确。由链节恢复加聚单体时，在相邻两个碳之间补回双键。","scaffold":"标出碳骨架与官能团，再核对反应类型和原子去向。"},{"id":"Q5R_H3_PROCESS_01","mother_id":"M5R_H3_PROCESS_01","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__leaching_and_impurity_removal","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.矿石浸取前粉碎通常可增大接触面积并提高浸取速率。 Ⅱ.粒径减小使浸取剂更充分接触固体。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。粒径减小使浸取剂更充分接触固体。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_02","mother_id":"M5R_H3_PROCESS_02","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__leaching_and_impurity_removal","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.提高浸取温度在任何情况下都只会提高收率而没有副作用。 Ⅱ.高温还可能加剧副反应、挥发、能耗或设备腐蚀。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。高温还可能加剧副反应、挥发、能耗或设备腐蚀。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_03","mother_id":"M5R_H3_PROCESS_03","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__leaching_and_impurity_removal","level":2,"grade_band":"高三","stem":"判断：酸浸时酸用量越大越好，不必考虑后续除杂。","options":["正确","错误"],"correct_option":1,"explanation":"错误。过量酸会增加中和负担、引入杂质并提高成本。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_04","mother_id":"M5R_H3_PROCESS_04","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__leaching_and_impurity_removal","level":2,"grade_band":"高三","stem":"判断：将Fe²⁺氧化为Fe³⁺后再调pH，有时可利用Fe(OH)₃较易沉淀来除铁。","options":["正确","错误"],"correct_option":0,"explanation":"正确。价态改变可改变氢氧化物溶解性和沉淀所需pH。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_05","mother_id":"M5R_H3_PROCESS_05","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__leaching_and_impurity_removal","level":2,"grade_band":"高三","stem":"判断：调pH除杂时应结合目标离子和杂质离子的沉淀范围选择控制区间。","options":["正确","错误"],"correct_option":0,"explanation":"正确。既要使杂质充分沉淀，又要减少目标离子损失。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_06","mother_id":"M5R_H3_PROCESS_06","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__filtration_and_crystallization","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.过滤操作可直接把两种都溶解在水中的离子完全分开。 Ⅱ.过滤只能分离固体与液体，溶液中的离子会随滤液通过。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。过滤只能分离固体与液体，溶液中的离子会随滤液通过。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_07","mother_id":"M5R_H3_PROCESS_07","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__filtration_and_crystallization","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.过滤所得沉淀若是目标产品，洗涤可除去表面附着的可溶性杂质。 Ⅱ.洗液选择还要兼顾目标沉淀的溶解损失。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。洗液选择还要兼顾目标沉淀的溶解损失。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_08","mother_id":"M5R_H3_PROCESS_08","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__filtration_and_crystallization","level":3,"grade_band":"高三","stem":"判断：洗涤晶体时应优先选能大量溶解目标晶体的热水。","options":["正确","错误"],"correct_option":1,"explanation":"错误。洗液应尽量少溶产品且能带走杂质，常用少量冷溶剂。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_09","mother_id":"M5R_H3_PROCESS_09","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__filtration_and_crystallization","level":3,"grade_band":"高三","stem":"判断：对溶解度随温度变化较大的物质，蒸发浓缩后冷却结晶常可提高析晶率。","options":["正确","错误"],"correct_option":0,"explanation":"正确。高温浓缩、低温降低溶解度有利于晶体析出。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_10","mother_id":"M5R_H3_PROCESS_10","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__filtration_and_crystallization","level":3,"grade_band":"高三","stem":"判断：对溶解度受温度影响很小的物质，只靠冷却通常难以得到大量晶体。","options":["正确","错误"],"correct_option":0,"explanation":"正确。这类物质常更适合蒸发结晶。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_11","mother_id":"M5R_H3_PROCESS_11","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__recycle_and_resource_recovery","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.从结晶母液中继续回收目标盐，可减少目标元素随废液损失。 Ⅱ.母液中通常仍含目标离子，适当浓缩或循环可提高总回收率。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。母液中通常仍含目标离子，适当浓缩或循环可提高总回收率。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_12","mother_id":"M5R_H3_PROCESS_12","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__recycle_and_resource_recovery","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.焙烧碳酸盐矿石产生的CO₂经净化后若能回用，可降低尾气排放并提高资源利用。 Ⅱ.尾气处理与副产物利用可以在同一流程中衔接。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。尾气处理与副产物利用可以在同一流程中衔接。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_13","mother_id":"M5R_H3_PROCESS_13","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__recycle_and_resource_recovery","level":3,"grade_band":"高三","stem":"判断：工艺尾气吸收只影响环保，与物料利用率无关。","options":["正确","错误"],"correct_option":1,"explanation":"错误。吸收产物有时可回用或制成副产品，同时减少排放。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_14","mother_id":"M5R_H3_PROCESS_14","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__recycle_and_resource_recovery","level":3,"grade_band":"高三","stem":"判断：母液循环使用可能提高原料利用率，但也可能造成杂质累积。","options":["正确","错误"],"correct_option":0,"explanation":"正确。循环次数和排放比例需兼顾回收与杂质控制。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_15","mother_id":"M5R_H3_PROCESS_15","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__recycle_and_resource_recovery","level":3,"grade_band":"高三","stem":"判断：副产品若能安全分离并资源化，可改善工艺原子利用和经济性。","options":["正确","错误"],"correct_option":0,"explanation":"正确。评价流程不能只看主产品收率。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_16","mother_id":"M5R_H3_PROCESS_16","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__yield_and_product_quality","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.产品收率等于实际得到纯产品的量与理论量之比。 Ⅱ.若产品含杂质，应先按纯度折算实际纯产品量。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。若产品含杂质，应先按纯度折算实际纯产品量。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_17","mother_id":"M5R_H3_PROCESS_17","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__yield_and_product_quality","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.晶体表面夹带母液会使直接称得的产品质量偏高、纯度偏低。 Ⅱ.母液中的溶剂和杂质被一并计入质量。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。母液中的溶剂和杂质被一并计入质量。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_18","mother_id":"M5R_H3_PROCESS_18","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__yield_and_product_quality","level":4,"grade_band":"高三","stem":"判断：理论上可得20.0 g产品，若转化与分离总收率为80%，则实际纯产品最多为16.0 g。","options":["正确","错误"],"correct_option":0,"explanation":"正确。实际纯产品质量=理论质量×总收率=20.0×80% g。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_19","mother_id":"M5R_H3_PROCESS_19","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__yield_and_product_quality","level":4,"grade_band":"高三","stem":"判断：晶体洗涤后未充分干燥便称量，会使计算的产品收率偏高。","options":["正确","错误"],"correct_option":0,"explanation":"正确。残留洗液被计入产品质量，称量值大于实际干晶体质量。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_20","mother_id":"M5R_H3_PROCESS_20","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__yield_and_product_quality","level":4,"grade_band":"高三","stem":"判断：用热水洗涤在热水中溶解度较大的目标晶体，可能使产品收率偏低。","options":["正确","错误"],"correct_option":0,"explanation":"正确。部分目标晶体溶入洗液并随滤液损失。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_21","mother_id":"M5R_H3_PROCESS_21","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__environment_and_mass_balance","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.处理易被空气氧化的中间产物时，可采用惰性气氛或及时密封。 Ⅱ.减少与O₂接触可保持所需价态。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。减少与O₂接触可保持所需价态。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_22","mother_id":"M5R_H3_PROCESS_22","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__environment_and_mass_balance","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.含重金属离子的废水可未经处理直接排放，只要浓度较低。 Ⅱ.应按排放要求沉淀、吸附或回收，不能凭主观“较低”判断。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。应按排放要求沉淀、吸附或回收，不能凭主观“较低”判断。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_23","mother_id":"M5R_H3_PROCESS_23","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__environment_and_mass_balance","level":4,"grade_band":"高三","stem":"判断：提高温度、延长时间和增加试剂量都会提高成本，因此流程优化需比较边际收益。","options":["正确","错误"],"correct_option":0,"explanation":"正确。工艺最优点要综合转化率、速率、能耗和设备寿命。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_24","mother_id":"M5R_H3_PROCESS_24","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__environment_and_mass_balance","level":4,"grade_band":"高三","stem":"判断：流程图中的循环箭头表示该物流可返回前序步骤，应核对其中有效组分和杂质去向。","options":["正确","错误"],"correct_option":0,"explanation":"正确。循环物组成决定其能否直接回用及是否需净化。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_PROCESS_25","mother_id":"M5R_H3_PROCESS_25","skill_id":"H3_PROCESS","concept_key":"H3_PROCESS__environment_and_mass_balance","level":4,"grade_band":"高三","stem":"判断：用元素守恒检查工艺流程时，目标元素在原料、产品、副产物和废液中的去向都应计入。","options":["正确","错误"],"correct_option":0,"explanation":"正确。完整物料衡算能发现漏项和异常损失。","scaffold":"沿原料—转化—分离—结晶追踪目标元素和杂质去向。"},{"id":"Q5R_H3_STOICH_01","mother_id":"M5R_H3_STOICH_01","skill_id":"H3_STOICH","concept_key":"H3_STOICH__amount_conversion","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.1 mol任何指定微粒都含有约N_A个该微粒。 Ⅱ.物质的量必须对应明确微粒，1 mol对应阿伏加德罗常数个微粒。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。物质的量必须对应明确微粒，1 mol对应阿伏加德罗常数个微粒。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_02","mother_id":"M5R_H3_STOICH_02","skill_id":"H3_STOICH","concept_key":"H3_STOICH__amount_conversion","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.18 g H₂O含有约N_A个H₂O分子。 Ⅱ.18 g H₂O为1 mol，因此含N_A个水分子。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。18 g H₂O为1 mol，因此含N_A个水分子。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_03","mother_id":"M5R_H3_STOICH_03","skill_id":"H3_STOICH","concept_key":"H3_STOICH__amount_conversion","level":2,"grade_band":"高三","stem":"判断：18 g H₂O所含原子总数约为2N_A。","options":["正确","错误"],"correct_option":1,"explanation":"错误。每个H₂O分子含3个原子，1 mol H₂O含3N_A个原子。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_04","mother_id":"M5R_H3_STOICH_04","skill_id":"H3_STOICH","concept_key":"H3_STOICH__amount_conversion","level":2,"grade_band":"高三","stem":"判断：标准状况下22.4 L O₂的物质的量约为1 mol。","options":["正确","错误"],"correct_option":0,"explanation":"正确。标准状况下Vₘ约为22.4 L·mol⁻¹。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_05","mother_id":"M5R_H3_STOICH_05","skill_id":"H3_STOICH","concept_key":"H3_STOICH__amount_conversion","level":2,"grade_band":"高三","stem":"判断：标准状况下2.24 L CO₂含有约0.10N_A个CO₂分子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。2.24 L对应0.10 mol，分子数为0.10N_A。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_06","mother_id":"M5R_H3_STOICH_06","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_concentration","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.0.500 L 0.200 mol·L⁻¹ NaCl溶液中NaCl的物质的量为0.100 mol。 Ⅱ.n=cV=0.200×0.500 mol=0.100 mol。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。n=cV=0.200×0.500 mol=0.100 mol。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_07","mother_id":"M5R_H3_STOICH_07","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_concentration","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.将0.100 mol溶质配成500 mL溶液，所得物质的量浓度为0.500 mol·L⁻¹。 Ⅱ.c=n/V=0.100/0.500 mol·L⁻¹=0.200 mol·L⁻¹。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。c=n/V=0.100/0.500 mol·L⁻¹=0.200 mol·L⁻¹。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_08","mother_id":"M5R_H3_STOICH_08","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_concentration","level":3,"grade_band":"高三","stem":"判断：稀释溶液时若溶质不反应、不损失，稀释前后溶质的物质的量不变。","options":["正确","错误"],"correct_option":0,"explanation":"正确。可据此使用c₁V₁=c₂V₂。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_09","mother_id":"M5R_H3_STOICH_09","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_concentration","level":3,"grade_band":"高三","stem":"判断：从100 mL 1.00 mol·L⁻¹ NaCl溶液中取出20.0 mL，所取溶液中NaCl为0.0200 mol。","options":["正确","错误"],"correct_option":0,"explanation":"正确。取样前溶液均一，n=cV=1.00×0.0200 mol=0.0200 mol。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_10","mother_id":"M5R_H3_STOICH_10","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_concentration","level":3,"grade_band":"高三","stem":"判断：将50.0 mL 2.00 mol·L⁻¹ HCl稀释到200 mL，所得浓度为1.00 mol·L⁻¹。","options":["正确","错误"],"correct_option":1,"explanation":"错误。由c₁V₁=c₂V₂，稀释后浓度为0.500 mol·L⁻¹。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_11","mother_id":"M5R_H3_STOICH_11","skill_id":"H3_STOICH","concept_key":"H3_STOICH__reaction_conservation","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.4Al+3O₂=2Al₂O₃中，2 mol Al完全反应需要1.5 mol O₂。 Ⅱ.按系数比n(O₂)=2×3/4 mol=1.5 mol。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。按系数比n(O₂)=2×3/4 mol=1.5 mol。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_12","mother_id":"M5R_H3_STOICH_12","skill_id":"H3_STOICH","concept_key":"H3_STOICH__reaction_conservation","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.1 mol CH₄完全燃烧需要1 mol O₂。 Ⅱ.CH₄+2O₂=CO₂+2H₂O，1 mol CH₄需2 mol O₂。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。CH₄+2O₂=CO₂+2H₂O，1 mol CH₄需2 mol O₂。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_13","mother_id":"M5R_H3_STOICH_13","skill_id":"H3_STOICH","concept_key":"H3_STOICH__reaction_conservation","level":3,"grade_band":"高三","stem":"判断：密闭体系发生化学反应时，反应前后总质量守恒。","options":["正确","错误"],"correct_option":0,"explanation":"正确。化学反应中原子种类和数目不变，因此封闭体系总质量不变。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_14","mother_id":"M5R_H3_STOICH_14","skill_id":"H3_STOICH","concept_key":"H3_STOICH__reaction_conservation","level":3,"grade_band":"高三","stem":"判断：含碳物质完全燃烧时，生成CO₂中的碳原子物质的量等于燃料中碳原子物质的量。","options":["正确","错误"],"correct_option":0,"explanation":"正确。碳元素守恒可绕开具体反应步骤。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_15","mother_id":"M5R_H3_STOICH_15","skill_id":"H3_STOICH","concept_key":"H3_STOICH__reaction_conservation","level":3,"grade_band":"高三","stem":"判断：氧化还原计算中，氧化剂得到电子总数等于还原剂失去电子总数。","options":["正确","错误"],"correct_option":0,"explanation":"正确。电子守恒决定氧化剂与还原剂的计量关系。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_16","mother_id":"M5R_H3_STOICH_16","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_preparation","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.质量分数为w、密度为ρ g·cm⁻³、溶质摩尔质量为M g·mol⁻¹的溶液，其浓度可用c=1000ρw/M计算。 Ⅱ.取1 L溶液质量为1000ρ g，溶质质量为1000ρw g。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。取1 L溶液质量为1000ρ g，溶质质量为1000ρw g。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_17","mother_id":"M5R_H3_STOICH_17","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_preparation","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.用固体配制一定物质的量浓度溶液时，可把固体直接放在容量瓶中溶解。 Ⅱ.应先在烧杯中溶解并冷却，再定量转移到容量瓶。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。应先在烧杯中溶解并冷却，再定量转移到容量瓶。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_18","mother_id":"M5R_H3_STOICH_18","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_preparation","level":4,"grade_band":"高三","stem":"判断：配液转移后洗涤烧杯和玻璃棒，并把洗液并入容量瓶，可减少溶质损失。","options":["正确","错误"],"correct_option":0,"explanation":"正确。定量转移要求原溶液中的溶质全部进入容量瓶。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_19","mother_id":"M5R_H3_STOICH_19","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_preparation","level":4,"grade_band":"高三","stem":"判断：容量瓶定容时俯视刻度线，会使所配溶液实际体积偏小、浓度偏高。","options":["正确","错误"],"correct_option":0,"explanation":"正确。俯视时液面低于刻度线便误判到线，实际加水不足。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_20","mother_id":"M5R_H3_STOICH_20","skill_id":"H3_STOICH","concept_key":"H3_STOICH__solution_preparation","level":4,"grade_band":"高三","stem":"判断：移液洗涤后未把洗液转入容量瓶，会使所配溶液浓度偏低。","options":["正确","错误"],"correct_option":0,"explanation":"正确。有溶质残留在烧杯和玻璃棒上，进入容量瓶的溶质物质的量偏小。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_21","mother_id":"M5R_H3_STOICH_21","skill_id":"H3_STOICH","concept_key":"H3_STOICH__purity_and_yield","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.20.0 g纯度为80%的CaCO₃样品中，CaCO₃的质量为16.0 g。 Ⅱ.纯物质质量=样品质量×纯度=20.0×80% g。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。纯物质质量=样品质量×纯度=20.0×80% g。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_22","mother_id":"M5R_H3_STOICH_22","skill_id":"H3_STOICH","concept_key":"H3_STOICH__purity_and_yield","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.理论上生成0.100 mol产品，实际得到0.080 mol纯产品，则产率为125%。 Ⅱ.产率=0.080/0.100×100%=80%。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。产率=0.080/0.100×100%=80%。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_23","mother_id":"M5R_H3_STOICH_23","skill_id":"H3_STOICH","concept_key":"H3_STOICH__purity_and_yield","level":4,"grade_band":"高三","stem":"判断：某反应理论产物10.0 g，实际得到8.0 g，则产率为80%。","options":["正确","错误"],"correct_option":0,"explanation":"正确。产率=实际产量/理论产量×100%。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_24","mother_id":"M5R_H3_STOICH_24","skill_id":"H3_STOICH","concept_key":"H3_STOICH__purity_and_yield","level":4,"grade_band":"高三","stem":"判断：含杂质20%的10.0 g样品中纯物质质量为8.0 g。","options":["正确","错误"],"correct_option":0,"explanation":"正确。纯度为80%，纯物质质量=10.0×0.80 g。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STOICH_25","mother_id":"M5R_H3_STOICH_25","skill_id":"H3_STOICH","concept_key":"H3_STOICH__purity_and_yield","level":4,"grade_band":"高三","stem":"判断：某反应理论生成10.0 g产品，实际得到含产品90%的混合物8.0 g，则产品收率为72%。","options":["正确","错误"],"correct_option":0,"explanation":"正确。实际纯产品为8.0×90%=7.2 g，收率=7.2/10.0×100%=72%。","scaffold":"把质量、体积、浓度或微粒数统一换成n，再用守恒。"},{"id":"Q5R_H3_STRUCTURE_01","mother_id":"M5R_H3_STRUCTURE_01","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__atomic_orbital_and_periodicity","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.同一原子中每个原子轨道最多容纳2个自旋方向相反的电子。 Ⅱ.这符合泡利不相容原理。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。这符合泡利不相容原理。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_02","mother_id":"M5R_H3_STRUCTURE_02","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__atomic_orbital_and_periodicity","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.简并轨道填充时，电子总是先在同一轨道中成对。 Ⅱ.通常先以自旋平行方式分占各简并轨道，再成对。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。通常先以自旋平行方式分占各简并轨道，再成对。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_03","mother_id":"M5R_H3_STRUCTURE_03","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__atomic_orbital_and_periodicity","level":2,"grade_band":"高三","stem":"判断：主量子数相同的电子一定具有相同能量。","options":["正确","错误"],"correct_option":1,"explanation":"错误。多电子原子中轨道能量还与角量子数及屏蔽等有关。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_04","mother_id":"M5R_H3_STRUCTURE_04","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__atomic_orbital_and_periodicity","level":2,"grade_band":"高三","stem":"判断：Na失去最外层1个电子形成Na⁺后，半径通常减小。","options":["正确","错误"],"correct_option":0,"explanation":"正确。电子层数减少，且原子核对剩余电子的吸引增强。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_05","mother_id":"M5R_H3_STRUCTURE_05","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__atomic_orbital_and_periodicity","level":2,"grade_band":"高三","stem":"判断：同周期主族元素从左到右第一电离能严格单调增大，没有例外。","options":["正确","错误"],"correct_option":1,"explanation":"错误。总体增大但受亚层全满、半满及电子成对等影响存在局部异常。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_06","mother_id":"M5R_H3_STRUCTURE_06","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__chemical_bond","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.电负性越大的元素，在共价键中吸引成键电子的能力通常越强。 Ⅱ.电负性用于描述化合状态下原子吸引共用电子的相对能力。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。电负性用于描述化合状态下原子吸引共用电子的相对能力。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_07","mother_id":"M5R_H3_STRUCTURE_07","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__chemical_bond","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.NaCl晶体中存在独立的NaCl分子。 Ⅱ.NaCl是离子晶体，以离子按空间点阵排列，不存在独立分子。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":3,"explanation":"Ⅰ错误，Ⅱ正确。NaCl是离子晶体，以离子按空间点阵排列，不存在独立分子。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_08","mother_id":"M5R_H3_STRUCTURE_08","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__chemical_bond","level":3,"grade_band":"高三","stem":"判断：HCl分子中的H—Cl键属于极性共价键。","options":["正确","错误"],"correct_option":0,"explanation":"正确。Cl电负性较大，共用电子对偏向Cl。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_09","mother_id":"M5R_H3_STRUCTURE_09","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__chemical_bond","level":3,"grade_band":"高三","stem":"判断：NH₄⁺形成过程中存在配位键的形成，但形成后四个N—H键通常等同。","options":["正确","错误"],"correct_option":0,"explanation":"正确。成键来源可不同，形成稳定离子后键的结构地位等同。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_10","mother_id":"M5R_H3_STRUCTURE_10","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__chemical_bond","level":3,"grade_band":"高三","stem":"判断：CH₄分子的空间构型为正四面体。","options":["正确","错误"],"correct_option":0,"explanation":"正确。中心C周围四对成键电子尽量远离。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_11","mother_id":"M5R_H3_STRUCTURE_11","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__molecular_geometry","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.NH₃分子的空间构型为平面三角形。 Ⅱ.N上有一对孤电子对，分子构型为三角锥形。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。N上有一对孤电子对，分子构型为三角锥形。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_12","mother_id":"M5R_H3_STRUCTURE_12","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__molecular_geometry","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.H₂O分子的空间构型为直线形。 Ⅱ.O上有两对孤电子对，H₂O为V形。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":1,"explanation":"Ⅰ错误，Ⅱ正确。O上有两对孤电子对，H₂O为V形。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_13","mother_id":"M5R_H3_STRUCTURE_13","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__molecular_geometry","level":3,"grade_band":"高三","stem":"判断：CO₂分子为直线形且整体为非极性分子。","options":["正确","错误"],"correct_option":0,"explanation":"正确。两个C=O键偶极矩方向相反并相互抵消。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_14","mother_id":"M5R_H3_STRUCTURE_14","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__molecular_geometry","level":3,"grade_band":"高三","stem":"判断：BF₃分子为平面三角形。","options":["正确","错误"],"correct_option":0,"explanation":"正确。中心B周围三组价层电子对呈平面三角排布。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_15","mother_id":"M5R_H3_STRUCTURE_15","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__molecular_geometry","level":3,"grade_band":"高三","stem":"判断：CH₄中C原子常描述为sp³杂化。","options":["正确","错误"],"correct_option":0,"explanation":"正确。四个等价成键方向对应正四面体。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_16","mother_id":"M5R_H3_STRUCTURE_16","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__hybridization","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.乙烯分子中双键碳原子常描述为sp³杂化。 Ⅱ.双键碳为sp²杂化，未杂化p轨道形成π键。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":0,"explanation":"Ⅰ错误，Ⅱ正确。双键碳为sp²杂化，未杂化p轨道形成π键。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_17","mother_id":"M5R_H3_STRUCTURE_17","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__hybridization","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.乙炔分子中三键碳原子常描述为sp杂化。 Ⅱ.两个sp轨道成σ键，两个未杂化p轨道形成两个π键。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。两个sp轨道成σ键，两个未杂化p轨道形成两个π键。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_18","mother_id":"M5R_H3_STRUCTURE_18","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__hybridization","level":4,"grade_band":"高三","stem":"判断：气态BeCl₂分子呈直线形时，中心Be原子可描述为sp杂化。","options":["正确","错误"],"correct_option":0,"explanation":"正确。两个sp杂化轨道沿直线方向分别形成Be—Cl键。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_19","mother_id":"M5R_H3_STRUCTURE_19","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__hybridization","level":4,"grade_band":"高三","stem":"判断：BF₃中B原子常描述为sp²杂化，对应平面三角形的三个成键方向。","options":["正确","错误"],"correct_option":0,"explanation":"正确。三个sp²杂化轨道位于同一平面并彼此约成120°。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_20","mother_id":"M5R_H3_STRUCTURE_20","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__hybridization","level":4,"grade_band":"高三","stem":"判断：NH₃中N原子只有三个N—H键，因此应描述为sp²杂化。","options":["正确","错误"],"correct_option":1,"explanation":"错误。还要计入一对孤电子对，价层共有四组电子对，常描述为sp³杂化。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_21","mother_id":"M5R_H3_STRUCTURE_21","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__crystal_type_and_cell","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.离子晶体在固态时通常不导电，熔融后可导电。 Ⅱ.固态离子被束缚，熔融后离子可自由移动。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。固态离子被束缚，熔融后离子可自由移动。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_22","mother_id":"M5R_H3_STRUCTURE_22","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__crystal_type_and_cell","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.金属导电与晶体中可自由移动的离域电子有关。 Ⅱ.金属阳离子与离域电子共同构成金属键模型。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。金属阳离子与离域电子共同构成金属键模型。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_23","mother_id":"M5R_H3_STRUCTURE_23","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__crystal_type_and_cell","level":4,"grade_band":"高三","stem":"判断：金刚石和石墨物理性质差异显著，与其碳原子连接方式不同有关。","options":["正确","错误"],"correct_option":0,"explanation":"正确。金刚石为三维网状结构，石墨具有层状结构和离域电子。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_24","mother_id":"M5R_H3_STRUCTURE_24","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__crystal_type_and_cell","level":4,"grade_band":"高三","stem":"判断：位于立方晶胞顶点的一个粒子对该晶胞的贡献为1/8。","options":["正确","错误"],"correct_option":0,"explanation":"正确。一个顶点由8个相邻晶胞共有。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_STRUCTURE_25","mother_id":"M5R_H3_STRUCTURE_25","skill_id":"H3_STRUCTURE","concept_key":"H3_STRUCTURE__crystal_type_and_cell","level":4,"grade_band":"高三","stem":"判断：晶胞密度可由ρ=ZM/(N_A V)计算，其中Z为每个晶胞所含化学式单位数。","options":["正确","错误"],"correct_option":0,"explanation":"正确。晶胞质量为ZM/N_A，再除以晶胞体积V。","scaffold":"从电子排布、成键和空间结构逐层连接到宏观性质。"},{"id":"Q5R_H3_THERMO_RATE_01","mother_id":"M5R_H3_THERMO_RATE_01","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__rate_factors","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.相同条件下，镁粉与盐酸的反应通常比等质量镁条更快。 Ⅱ.镁粉接触面积更大，单位时间发生的有效碰撞更多。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。镁粉接触面积更大，单位时间发生的有效碰撞更多。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_02","mother_id":"M5R_H3_THERMO_RATE_02","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__rate_factors","level":2,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.相同浓度盐酸与等表面积Mg、Zn反应时，Mg通常放出H₂更快。 Ⅱ.金属本身的性质会影响反应速率。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。金属本身的性质会影响反应速率。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_03","mother_id":"M5R_H3_THERMO_RATE_03","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__rate_factors","level":2,"grade_band":"高三","stem":"判断：升高温度通常使单位时间内有效碰撞次数增加。","options":["正确","错误"],"correct_option":0,"explanation":"正确。更多粒子达到活化能且碰撞更频繁，反应速率通常增大。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_04","mother_id":"M5R_H3_THERMO_RATE_04","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__rate_factors","level":2,"grade_band":"高三","stem":"判断：增大反应物浓度只会改变平衡位置，不会改变反应速率。","options":["正确","错误"],"correct_option":1,"explanation":"错误。浓度增大会提高碰撞频率，通常使瞬时速率增大。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_05","mother_id":"M5R_H3_THERMO_RATE_05","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__rate_factors","level":2,"grade_band":"高三","stem":"判断：对于气相反应，恒温压缩容器通常会同时改变气体浓度和反应速率。","options":["正确","错误"],"correct_option":0,"explanation":"正确。体积减小使气体浓度增大。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_06","mother_id":"M5R_H3_THERMO_RATE_06","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__enthalpy_and_hess","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.已知C(s)+O₂(g)=CO₂(g) ΔH₁，CO(g)+1/2O₂(g)=CO₂(g) ΔH₂，则C(s)+1/2O₂(g)=CO(g)的ΔH为ΔH₁−ΔH₂。 Ⅱ.目标反应可由第一个反应减去第二个反应得到，焓变作相同代数组合。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":0,"explanation":"Ⅰ正确，Ⅱ正确。目标反应可由第一个反应减去第二个反应得到，焓变作相同代数组合。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_07","mother_id":"M5R_H3_THERMO_RATE_07","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__enthalpy_and_hess","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.同一反应的热化学方程式系数全部乘2时，ΔH也应乘2。 Ⅱ.ΔH与按方程式计量发生的反应进度成正比。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。ΔH与按方程式计量发生的反应进度成正比。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_08","mother_id":"M5R_H3_THERMO_RATE_08","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__enthalpy_and_hess","level":3,"grade_band":"高三","stem":"判断：比较石墨和金刚石燃烧热可间接求二者转化的焓变。","options":["正确","错误"],"correct_option":0,"explanation":"正确。利用盖斯定律可消去共同产物CO₂，得到两种碳单质之间的转化。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_09","mother_id":"M5R_H3_THERMO_RATE_09","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__enthalpy_and_hess","level":3,"grade_band":"高三","stem":"判断：盖斯定律可把若干已知反应的ΔH按方程式代数组合得到目标ΔH。","options":["正确","错误"],"correct_option":0,"explanation":"正确。焓是状态函数，路径可拆分组合。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_10","mother_id":"M5R_H3_THERMO_RATE_10","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__enthalpy_and_hess","level":3,"grade_band":"高三","stem":"判断：反向书写热化学方程式时，ΔH数值绝对值和符号都保持不变。","options":["正确","错误"],"correct_option":1,"explanation":"错误。绝对值保持，符号改变。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_11","mother_id":"M5R_H3_THERMO_RATE_11","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__bond_energy","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.断裂反应物中的化学键吸收能量，形成生成物中的化学键释放能量。 Ⅱ.键能估算遵循“断键吸能、成键放能”。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。键能估算遵循“断键吸能、成键放能”。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_12","mother_id":"M5R_H3_THERMO_RATE_12","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__bond_energy","level":3,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.用平均键能估算H₂(g)+Cl₂(g)=2HCl(g)的ΔH时，应计算E(H—H)+E(Cl—Cl)−2E(H—Cl)。 Ⅱ.断裂反应物中的键吸能，形成生成物中的键放能。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。断裂反应物中的键吸能，形成生成物中的键放能。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_13","mother_id":"M5R_H3_THERMO_RATE_13","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__bond_energy","level":3,"grade_band":"高三","stem":"判断：若形成生成物中的化学键释放的总能量大于断裂反应物化学键吸收的总能量，反应通常为放热反应。","options":["正确","错误"],"correct_option":0,"explanation":"正确。ΔH≈断键吸能−成键放能，此时ΔH<0。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_14","mother_id":"M5R_H3_THERMO_RATE_14","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__bond_energy","level":3,"grade_band":"高三","stem":"判断：用键能估算反应热时，把生成物成键释放能量减去反应物断键吸收能量可直接得到ΔH。","options":["正确","错误"],"correct_option":1,"explanation":"错误。常用表达是ΔH≈反应物断键吸能−生成物成键放能。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_15","mother_id":"M5R_H3_THERMO_RATE_15","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__bond_energy","level":3,"grade_band":"高三","stem":"判断：H₂(g)和F₂(g)生成HF(g)时，若成键放能显著大于断键吸能，则ΔH为负。","options":["正确","错误"],"correct_option":0,"explanation":"正确。始态到终态净释放能量，反应焓变小于0。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_16","mother_id":"M5R_H3_THERMO_RATE_16","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__catalyst_and_rate_curve","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.工业反应选择催化剂后可以不再考虑温度和压强。 Ⅱ.催化剂、速率、平衡、能耗、安全和设备承压需综合权衡。","options":["Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误"],"correct_option":2,"explanation":"Ⅰ错误，Ⅱ正确。催化剂、速率、平衡、能耗、安全和设备承压需综合权衡。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_17","mother_id":"M5R_H3_THERMO_RATE_17","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__catalyst_and_rate_curve","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.能量—反应过程图中催化路径的峰值较低，可说明活化能降低。 Ⅱ.峰值相对反应物能量的高度对应正反应活化能。","options":["Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确"],"correct_option":3,"explanation":"Ⅰ正确，Ⅱ正确。峰值相对反应物能量的高度对应正反应活化能。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_18","mother_id":"M5R_H3_THERMO_RATE_18","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__catalyst_and_rate_curve","level":4,"grade_band":"高三","stem":"判断：同一反应使用催化剂后，正反应活化能降低而逆反应活化能升高。","options":["正确","错误"],"correct_option":1,"explanation":"错误。催化剂通常同时降低正、逆反应活化能。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_19","mother_id":"M5R_H3_THERMO_RATE_19","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__catalyst_and_rate_curve","level":4,"grade_band":"高三","stem":"判断：一定温度下反应物浓度随时间曲线逐渐变平，说明其消耗速率逐渐减小。","options":["正确","错误"],"correct_option":0,"explanation":"正确。曲线斜率绝对值逐渐减小。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_20","mother_id":"M5R_H3_THERMO_RATE_20","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__catalyst_and_rate_curve","level":4,"grade_band":"高三","stem":"判断：由平均速率可以断定时间区间内每一时刻的速率都相同。","options":["正确","错误"],"correct_option":1,"explanation":"错误。平均速率只反映整体变化，瞬时速率可随时间改变。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_21","mother_id":"M5R_H3_THERMO_RATE_21","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__calorimetry","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.燃料充分燃烧释放的热量可由燃料物质的量与摩尔燃烧焓估算。 Ⅱ.在状态和燃烧产物符合定义时，Q=nΔHc并注意符号。","options":["Ⅰ错误、Ⅱ正确","Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误"],"correct_option":2,"explanation":"Ⅰ正确，Ⅱ正确。在状态和燃烧产物符合定义时，Q=nΔHc并注意符号。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_22","mother_id":"M5R_H3_THERMO_RATE_22","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__calorimetry","level":4,"grade_band":"高三","stem":"组合判断：判断下列两项：Ⅰ.中和热测定中，实际量取55.0 mL 1.0 mol·L⁻¹ HCl并与足量NaOH完全反应，却仍按50.0 mL HCl计算参与反应的物质的量；其他条件理想时，所得每摩尔中和热的绝对值会偏大。 Ⅱ.实际放热对应0.055 mol HCl，而计算分母误用0.050 mol，折算到每摩尔后的放热绝对值偏大。","options":["Ⅰ、Ⅱ均错误","Ⅰ、Ⅱ均正确","Ⅰ正确、Ⅱ错误","Ⅰ错误、Ⅱ正确"],"correct_option":1,"explanation":"Ⅰ正确，Ⅱ正确。实际放热对应0.055 mol HCl，而计算分母误用0.050 mol，折算到每摩尔后的放热绝对值偏大。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_23","mother_id":"M5R_H3_THERMO_RATE_23","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__calorimetry","level":4,"grade_band":"高三","stem":"判断：反应热测定中，T₁为反应前酸、碱溶液温度的平均值，T₂为混合后的最高温度。若热量散失到环境中，T₂和ΔT=T₂−T₁都会偏小，因此算出的反应放出的热量也偏小。","options":["正确","错误"],"correct_option":0,"explanation":"正确。热量散失使T₂偏低，进而使ΔT和算出的反应放出的热量偏小；放热反应的ΔH为负，所以算出的ΔH数值偏大，更接近0。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_24","mother_id":"M5R_H3_THERMO_RATE_24","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__calorimetry","level":4,"grade_band":"高三","stem":"判断：中和热测定中用环形玻璃搅拌棒轻轻搅拌，有利于使酸碱迅速混合并记录最高温度。","options":["正确","错误"],"correct_option":0,"explanation":"正确。充分而快速混合可减少反应不完全和读数滞后造成的误差。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"},{"id":"Q5R_H3_THERMO_RATE_25","mother_id":"M5R_H3_THERMO_RATE_25","skill_id":"H3_THERMO_RATE","concept_key":"H3_THERMO_RATE__calorimetry","level":4,"grade_band":"高三","stem":"判断：中和热测定中用铜质搅拌棒代替玻璃搅拌棒，铜会吸收一部分热量，使混合后的最高温度T₂偏低。","options":["正确","错误"],"correct_option":0,"explanation":"正确。T₁为反应前酸、碱溶液温度的平均值，反应前后的温度差ΔT=T₂−T₁；因此ΔT和算出的反应放出的热量偏小。放热反应的ΔH为负，所以算出的ΔH数值偏大，更接近0。","scaffold":"分清ΔH、活化能、速率和平衡限度四个量。"}]$review_question_bank$::jsonb
  ) as q(
    id text,
    mother_id text,
    skill_id text,
    concept_key text,
    level smallint,
    grade_band text,
    stem text,
    options jsonb,
    correct_option smallint,
    explanation text,
    scaffold text
  )
)
insert into public.chem_questions(
  id,mother_id,skill_id,concept_key,level,grade_band,stem,options,correct_option,
  explanation,scaffold,review_status,scope_status,source_kind,image_url,
  usable_for_class_quiz,usable_for_review,usable_for_exam_sprint,updated_at
)
select
  id,mother_id,skill_id,concept_key,level,grade_band,stem,options,correct_option,
  explanation,scaffold,'approved','IN','teacher_original',null,
  false,true,true,now()
from authored
on conflict (id) do update set
  mother_id=excluded.mother_id,
  skill_id=excluded.skill_id,
  concept_key=excluded.concept_key,
  level=excluded.level,
  grade_band=excluded.grade_band,
  stem=excluded.stem,
  options=excluded.options,
  correct_option=excluded.correct_option,
  explanation=excluded.explanation,
  scaffold=excluded.scaffold,
  review_status='approved',
  scope_status='IN',
  source_kind='teacher_original',
  image_url=null,
  usable_for_class_quiz=false,
  usable_for_review=true,
  usable_for_exam_sprint=true,
  updated_at=now();

do $$
begin
  if exists (
    with used as (
      select distinct unnest(p.skill_ids) skill_id
      from public.chem_learning_plans p
      join public.chem_students_v2 s on s.id=p.student_id
      where p.mode='REVIEW'
        and s.record_status='active'
        and s.grade_band in ('高一','高二','高三')
    )
    select 1
    from (
      (select skill_id from used except select skill_id from review_exam_target_skills)
      union all
      (select skill_id from review_exam_target_skills except select skill_id from used)
    ) mismatch
  ) then
    raise exception 'The authored bank and active high-school REVIEW skill set no longer match';
  end if;

  if (select count(*) from public.chem_questions where id like 'Q5R\_%' escape '\') <> 600
     or (select count(distinct mother_id) from public.chem_questions where id like 'Q5R\_%' escape '\') <> 600
     or (select count(distinct concept_key) from public.chem_questions where id like 'Q5R\_%' escape '\') <> 120 then
    raise exception 'The five-round authored bank must contain 600 unique questions and mothers';
  end if;

  if exists (
    select 1
    from (
      select skill_id,concept_key,
             count(*) question_count,
             count(distinct mother_id) mother_count,
             count(*) filter (where jsonb_array_length(options)=4) four_option_count,
             count(*) filter (where jsonb_array_length(options)=2) two_option_count
      from public.chem_questions
      where id like 'Q5R\_%' escape '\'
      group by skill_id,concept_key
    ) concept_pool
    where concept_key is null
       or question_count<>5
       or mother_count<>5
       or four_option_count<>2
       or two_option_count<>3
  ) or exists (
    select 1
    from (
      select skill_id,count(distinct concept_key) concept_count
      from public.chem_questions
      where id like 'Q5R\_%' escape '\'
      group by skill_id
    ) skill_pool
    where concept_count<>5
  ) then
    raise exception 'Every REVIEW skill must contain five concepts, each with five mothers, two four-option and three true/false variants';
  end if;

  if exists (
    select 1
    from review_exam_target_skills t
    left join lateral (
      select count(*) eligible_questions,
             count(distinct q.mother_id) eligible_mothers
      from public.chem_questions q
      where q.skill_id=t.skill_id
        and q.review_status='approved'
        and q.scope_status='IN'
        and q.usable_for_review
        and q.level<=t.level_cap
    ) pool on true
    where pool.eligible_questions<25 or pool.eligible_mothers<25
  ) then
    raise exception 'At least one REVIEW skill cannot supply 25 approved IN-scope unique mothers under its level cap';
  end if;

  if exists (
    select 1
    from public.chem_questions q
    join review_exam_target_skills t on t.skill_id=q.skill_id
    where q.review_status='approved'
      and q.scope_status='IN'
      and q.usable_for_review
      and q.level<=t.level_cap
      and q.stem ~ '(核心规律|最可靠.{0,8}第一步|处理.{0,20}(第一步|优先)|优先检查|最先做)'
  ) then
    raise exception 'A generic meta-prompt remains in the active high-school REVIEW pool';
  end if;

  if exists (
    select 1 from public.chem_questions
    where id like 'Q5R\_%' escape '\'
      and (review_status<>'approved' or scope_status<>'IN' or not usable_for_review
        or usable_for_class_quiz or source_kind<>'teacher_original'
        or concept_key is null or concept_key not like skill_id||'__%'
        or jsonb_array_length(options) not in (2,4)
        or correct_option<0 or correct_option>=jsonb_array_length(options)
        or scaffold is null or length(scaffold)<8
        or explanation is null or length(explanation)<8
        or position('N'||chr(8336) in stem)>0)
  ) then
    raise exception 'The authored five-round question metadata or notation contract is invalid';
  end if;
end $$;

commit;
